INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25510, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "脂肪酸", "is_correct": true, "explanation": "正确：牛奶含有脂肪酸，与后面“也含有蛋白质”并列，符合句意。"}, {"text": "石油", "is_correct": false, "explanation": "语义：牛奶里不会含有石油。"}, {"text": "汽油", "is_correct": false, "explanation": "语义：牛奶里不会含有汽油。"}, {"text": "笑容", "is_correct": false, "explanation": "搭配：“含有”后面要接物质，“笑容”不能被“含有”。"}], "explanations": {"脂肪酸": "正确：牛奶含有脂肪酸，与后面“也含有蛋白质”并列，符合句意。", "石油": "语义：牛奶里不会含有石油。", "汽油": "语义：牛奶里不会含有汽油。", "笑容": "搭配：“含有”后面要接物质，“笑容”不能被“含有”。"}, "sentence_index": 6, "correct_answer": "脂肪酸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "脂肪酸是一种饮料。", "explanation": "这里应该用〈有机酸〉。脂肪酸属于有机酸，不是饮料，不能这样归类。"}, {"text": "脂肪酸是一种水果。", "explanation": "这里应该用〈有机酸〉。脂肪酸属于有机酸，不是水果，不能这样归类。"}, {"text": "脂肪酸是一种蔬菜。", "explanation": "这里应该用〈有机酸〉。脂肪酸属于有机酸，不是蔬菜，不能这样归类。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44a1f037-7793-4423-b2e9-2ec73afc657c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25510, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种食用油里含有一条脂肪酸。", "corrected_sentence": "这种食用油里含有一种脂肪酸。", "error_description": "量词错误：脂肪酸应该用“种”，不用“条”。“条”一般用于长形物件，不能用来修饰脂肪酸。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44a1f037-7793-4423-b2e9-2ec73afc657c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25510, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种牛奶里含有很多条脂肪酸。", "corrected_sentence": "这种牛奶里含有很多脂肪酸。", "error_description": "量词错误：脂肪酸前不能用“条”，应直接说“很多脂肪酸”。“条”一般用于长形物件，不能用来修饰脂肪酸。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44a1f037-7793-4423-b2e9-2ec73afc657c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
