INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25518, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "来自哪里", "primary_collocate": null, "pronunciation": "yuán zì", "ipa": "ɥɛn˧˥ tsɹ̩˥˩", "syllable_count": 2, "sentences": [{"text": "这种水果源自南美洲。", "target_word": "源自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咖啡最早源自非洲。", "target_word": "源自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长江源自青藏高原。", "target_word": "源自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河源自北边的高山。", "target_word": "源自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种花源自哪个国家？", "target_word": "源自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗的名字源自它的出生地。", "target_word": "源自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道菜源自四川的小城。", "target_word": "源自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些茶叶源自南方的山里。", "target_word": "源自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "马铃薯源自南美洲的山区。", "target_word": "源自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人的口音源自他的家乡。", "target_word": "源自", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "事物最早来自的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4242725a-da6e-4fb3-b896-246ef3d081ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25518, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "源自", "is_correct": true, "explanation": "源自表示事物最早来自的地方，读作 yuán zì，例如“这种水果源自南美洲”。"}, {"text": "原子", "is_correct": false, "explanation": "zǐ（第三声）与 zì（第四声）声调不同，意思是原子。"}, {"text": "原始", "is_correct": false, "explanation": "shǐ（第三声）与 zì（第四声）声母与声调都不同，意思是原始。"}, {"text": "原则", "is_correct": false, "explanation": "zé（第二声）与 zì（第四声）韵母与声调不同，意思是原则。"}], "explanations": {"源自": "源自表示事物最早来自的地方，读作 yuán zì，例如“这种水果源自南美洲”。", "原子": "zǐ（第三声）与 zì（第四声）声调不同，意思是原子。", "原始": "shǐ（第三声）与 zì（第四声）声母与声调都不同，意思是原始。", "原则": "zé（第二声）与 zì（第四声）韵母与声调不同，意思是原则。"}, "sentence_index": null, "correct_answer": "源自"}, "level_3": {"options": [{"text": "源自", "is_correct": true, "explanation": "源自表示事物最早来自的地方，“这种水果源自南美洲”句意正确。"}, {"text": "位于", "is_correct": false, "explanation": "语义：“位于”说某物在某处，不说事物最早来自何处，与水果的来源不符。"}, {"text": "访问", "is_correct": false, "explanation": "语义：水果不能“访问”地方，与事物的来源无关。"}, {"text": "生活", "is_correct": false, "explanation": "配价：“生活”后要带“在”，“这种水果生活南美洲”不成立。"}], "explanations": {"源自": "源自表示事物最早来自的地方，“这种水果源自南美洲”句意正确。", "位于": "语义：“位于”说某物在某处，不说事物最早来自何处，与水果的来源不符。", "访问": "语义：水果不能“访问”地方，与事物的来源无关。", "生活": "配价：“生活”后要带“在”，“这种水果生活南美洲”不成立。"}, "sentence_index": 0, "correct_answer": "源自"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他源自北京。", "explanation": "这里应该用〈来自〉。“源自”指事物的起源或出处，说人的籍贯要用“来自”。"}, {"text": "这个学生源自喜欢数学。", "explanation": "这里应该用〈喜欢〉。“源自”表示来源，后面接地方或事物，不能接动词短语“喜欢数学”。"}, {"text": "这份工作源自昨天。", "explanation": "这里应该用〈始于〉。“源自”表示来源，接事物或地点；说工作从哪天开始要用“始于”，不能接时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2e5a0de-8f20-49ae-ab04-d651f3bdb347') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25518, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "源自", "is_correct": true, "explanation": "源自表示事物最早来自的地方，读作 yuán zì。"}, {"text": "圆子", "is_correct": false, "explanation": "zi（轻声）与 zì（第四声）声调不同，意思是圆子，一种圆形的食物。"}, {"text": "园子", "is_correct": false, "explanation": "zi（轻声）与 zì（第四声）声调不同，意思是园子，即小花园。"}, {"text": "原指", "is_correct": false, "explanation": "zhǐ（第三声）与 zì（第四声）声母与声调都不同，意思是原本所指。"}], "explanations": {"源自": "源自表示事物最早来自的地方，读作 yuán zì。", "圆子": "zi（轻声）与 zì（第四声）声调不同，意思是圆子，一种圆形的食物。", "园子": "zi（轻声）与 zì（第四声）声调不同，意思是园子，即小花园。", "原指": "zhǐ（第三声）与 zì（第四声）声母与声调都不同，意思是原本所指。"}, "sentence_index": null, "correct_answer": "源自"}, "level_3": {"options": [{"text": "源自", "is_correct": true, "explanation": "源自表示来源，“这道菜源自四川的小城”说明菜的来源，句意正确。"}, {"text": "路过", "is_correct": false, "explanation": "语义：“路过”是经过某地，不能表示这道菜的来源。"}, {"text": "参观", "is_correct": false, "explanation": "语义：菜不能“参观”城市，与来源关系无关。"}, {"text": "制造", "is_correct": false, "explanation": "语义：“制造”说的是做出来，句中“四川的小城”是来源，搭配不当。"}], "explanations": {"源自": "源自表示来源，“这道菜源自四川的小城”说明菜的来源，句意正确。", "路过": "语义：“路过”是经过某地，不能表示这道菜的来源。", "参观": "语义：菜不能“参观”城市，与来源关系无关。", "制造": "语义：“制造”说的是做出来，句中“四川的小城”是来源，搭配不当。"}, "sentence_index": 6, "correct_answer": "源自"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我源自家去学校。", "explanation": "这里应该用〈出发〉。“源自”只表示事物的来源，不能用来说人从某处动身去别的地方。"}, {"text": "这座房子源自很多砖。", "explanation": "这里应该用〈由……组成〉。“源自”表示来源，不表示事物由哪些部分构成。"}, {"text": "这辆车源自上海开往北京。", "explanation": "这里应该用〈从……开往〉。“源自”只表示来源，不表示车辆的出发和去向。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2e5a0de-8f20-49ae-ab04-d651f3bdb347') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25518, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种茶叶被源自中国南方。", "corrected_sentence": "这种茶叶源自中国南方。", "error_description": "“源自”表示来源，不用被动式，应说“这种茶叶源自中国南方”，去掉“被”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2e5a0de-8f20-49ae-ab04-d651f3bdb347') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25518, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这首诗源自了一本古书。", "corrected_sentence": "这首诗源自一本古书。", "error_description": "“源自”表示来源，不带“了”；应说“这首诗源自一本古书”，去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2e5a0de-8f20-49ae-ab04-d651f3bdb347') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
