INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25522, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用过的纸、瓶子等东西，可以变成新的材料再次使用。", "primary_collocate": null, "pronunciation": "zài shēng zī yuán", "ipa": "tsaɪ˥˩ ʂɤŋ˥˥ tsɹ̩˥˥ ɥɛn˧˥", "syllable_count": 4, "sentences": [{"text": "用过的纸是再生资源。", "target_word": "再生资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旧报纸也是再生资源。", "target_word": "再生资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个袋子是用再生资源做成的。", "target_word": "再生资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空瓶子是再生资源，不要乱扔。", "target_word": "再生资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校里有放再生资源的大箱子。", "target_word": "再生资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把旧纸箱收起来，因为它们是再生资源。", "target_word": "再生资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些旧书是再生资源，可以再用。", "target_word": "再生资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "再生资源能做成新的东西。", "target_word": "再生资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每个星期都收集再生资源。", "target_word": "再生资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "再生资源要和别的垃圾分开放。", "target_word": "再生资源", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "再生資源", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用过的纸、瓶子等可再次使用的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4242725a-da6e-4fb3-b896-246ef3d081ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25522, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "再生资源", "is_correct": true, "explanation": "用过的纸能再次使用，正符合「再生资源」的定义。"}, {"text": "老师", "is_correct": false, "explanation": "语义：纸不是人，「老师」指人，不能用来说明「用过的纸」是什么。"}, {"text": "首都", "is_correct": false, "explanation": "语义：「首都」指城市，与「用过的纸」没有类属关系。"}, {"text": "雨伞", "is_correct": false, "explanation": "搭配：「是」后的名词要与主语同类，「雨伞」与「用过的纸」不同类，整句不通。"}], "explanations": {"再生资源": "用过的纸能再次使用，正符合「再生资源」的定义。", "老师": "语义：纸不是人，「老师」指人，不能用来说明「用过的纸」是什么。", "首都": "语义：「首都」指城市，与「用过的纸」没有类属关系。", "雨伞": "搭配：「是」后的名词要与主语同类，「雨伞」与「用过的纸」不同类，整句不通。"}, "sentence_index": 0, "correct_answer": "再生资源"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这些再生资源已经没有用了，应该扔掉。", "explanation": "这里应该用〈废品〉。「再生资源」指用过后还能再加工利用的材料，不能说没有用、该扔掉；没用、要扔掉的东西是〈废品〉。"}, {"text": "吃剩的饭菜是再生资源，要放进回收箱。", "explanation": "这里应该用〈厨余垃圾〉。「再生资源」指纸、瓶子等用过后能再加工利用的材料，吃剩的饭菜属于厨余垃圾。"}, {"text": "再生资源会发臭，要每天倒掉。", "explanation": "这里应该用〈垃圾〉。「再生资源」指可以再利用的材料，不会腐烂发臭，这里说的是会腐烂的废弃物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2e5a0de-8f20-49ae-ab04-d651f3bdb347') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25522, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "再生资源", "is_correct": true, "explanation": "这些旧书可以再用，正符合「再生资源」指可再次利用的材料这一意思。"}, {"text": "星期", "is_correct": false, "explanation": "语义：「星期」指时间单位，不能用来说明「旧书」是什么。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：「窗户」指建筑的组成部分，与「旧书」没有类属关系。"}, {"text": "手套", "is_correct": false, "explanation": "搭配：「手套」成双使用，「是手套」不能用来判断一批旧书的性质，整句不通。"}], "explanations": {"再生资源": "这些旧书可以再用，正符合「再生资源」指可再次利用的材料这一意思。", "星期": "语义：「星期」指时间单位，不能用来说明「旧书」是什么。", "窗户": "语义：「窗户」指建筑的组成部分，与「旧书」没有类属关系。", "手套": "搭配：「手套」成双使用，「是手套」不能用来判断一批旧书的性质，整句不通。"}, "sentence_index": 6, "correct_answer": "再生资源"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司最宝贵的再生资源是员工的能力。", "explanation": "这里应该用〈人力资源〉。「再生资源」指用过后可再次利用的材料，不能指人才和能力，说员工的能力要用〈人力资源〉。"}, {"text": "这个项目的再生资源不够发工资，只好停工了。", "explanation": "这里应该用〈经费〉。「再生资源」指用过后可再利用的材料，不能用来发工资；发工资要用〈经费〉。"}, {"text": "这个国家的再生资源很丰富，地下有很多石油和煤。", "explanation": "这里应该用〈自然资源〉。「再生资源」指用过后能再次利用的纸、瓶子等材料，地下的石油和煤是自然资源。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2e5a0de-8f20-49ae-ab04-d651f3bdb347') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25522, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们每周收集一只再生资源。", "corrected_sentence": "我们每周收集一批再生资源。", "error_description": "量词用错。「再生资源」是集合性的物料，计量应用「批」；「只」用于单个或成对的动物、物品。错误形式是「一只再生资源」，正确形式是「一批再生资源」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2e5a0de-8f20-49ae-ab04-d651f3bdb347') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25522, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校每周处理一批的再生资源。", "corrected_sentence": "学校每周处理一批再生资源。", "error_description": "结构助词错误。数量短语“一批”直接修饰名词“再生资源”，中间不加“的”，错误形式是“一批的再生资源”，正确形式是“一批再生资源”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2e5a0de-8f20-49ae-ab04-d651f3bdb347') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
