INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25526, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把很多个东西合在一起，变成一个。", "primary_collocate": null, "pronunciation": "jù hé", "ipa": "tɕy˥˩ xɤ˧˥", "syllable_count": 2, "sentences": [{"text": "我们把三个小班聚合成了一个大班。", "target_word": "聚合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个表格把十个数字聚合成一个总数。", "target_word": "聚合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个软件把你所有的邮箱聚合成一个收件箱。", "target_word": "聚合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几条短视频聚合成一个长视频。", "target_word": "聚合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小颗粒聚合在一起，变成了大颗粒。", "target_word": "聚合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把大家的意见聚合成了一份报告。", "target_word": "聚合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这些文件聚合成一个压缩包。", "target_word": "聚合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把零散的故事聚合在一起，编成了一本书。", "target_word": "聚合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "油滴在水面上聚合成一大滴。", "target_word": "聚合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这五家小店聚合在一起，变成了一个品牌。", "target_word": "聚合", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "聚合过", "label": "体标"}, {"form": "聚合了", "label": "体标"}, {"form": "聚合物", "label": "复合"}], "register": "中性", "sense_fingerprint": "把许多个东西合并起来，变成一个整体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1e12ecc-3ac0-4aa7-b224-954d9d880c62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25526, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "聚合", "is_correct": true, "explanation": "正确答案：聚合（jù hé），指把许多东西合在一起，变成一个。"}, {"text": "句号", "is_correct": false, "explanation": "hào（第四声）与 hé（第二声）韵母不同（ao 与 e），意思是句末的标点符号。"}, {"text": "巨额", "is_correct": false, "explanation": "é 与 hé 只差声母 h，意思是数目非常大。"}, {"text": "聚会", "is_correct": false, "explanation": "huì（第四声）与 hé（第二声）韵母不同（ui 与 e），意思是人们聚在一起的活动。"}], "explanations": {"聚合": "正确答案：聚合（jù hé），指把许多东西合在一起，变成一个。", "句号": "hào（第四声）与 hé（第二声）韵母不同（ao 与 e），意思是句末的标点符号。", "巨额": "é 与 hé 只差声母 h，意思是数目非常大。", "聚会": "huì（第四声）与 hé（第二声）韵母不同（ui 与 e），意思是人们聚在一起的活动。"}, "sentence_index": null, "correct_answer": "聚合"}, "level_3": {"options": [{"text": "聚合", "is_correct": true, "explanation": "正确答案：聚合。三个小班合并成一个大班，“聚合”表示把多个合为一个。"}, {"text": "分开", "is_correct": false, "explanation": "语义：“分开”与“成了一个大班”的结果相矛盾。"}, {"text": "拆分", "is_correct": false, "explanation": "语义：“拆分”是分成几部分，与“合成一个大班”的意思相反。"}, {"text": "切割", "is_correct": false, "explanation": "搭配：“切割”用于物体，不能用来处理“小班”这样的班级。"}], "explanations": {"聚合": "正确答案：聚合。三个小班合并成一个大班，“聚合”表示把多个合为一个。", "分开": "语义：“分开”与“成了一个大班”的结果相矛盾。", "拆分": "语义：“拆分”是分成几部分，与“合成一个大班”的意思相反。", "切割": "搭配：“切割”用于物体，不能用来处理“小班”这样的班级。"}, "sentence_index": 0, "correct_answer": "聚合"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人把大块钢板聚合成了很多小块。", "explanation": "这里应该用〈切割〉。聚合是把多个合为一个，把大块钢板切成小块要说切割。"}, {"text": "细胞聚合成两个。", "explanation": "这里应该用〈分裂〉。细胞分成两个是分裂，聚合是合为一个。"}, {"text": "他用锤子把石头聚合成粉末。", "explanation": "这里应该用〈粉碎〉。把石头弄成粉末是粉碎，聚合不指把东西弄碎。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfa4217b-4928-4b3d-b514-21ac69746120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25526, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "聚合", "is_correct": true, "explanation": "正确答案：聚合。请把这些文件聚合成一个压缩包，“聚合”表示把多个合为一个。"}, {"text": "删除", "is_correct": false, "explanation": "语义：删除是去掉，不能得到一个压缩包。"}, {"text": "烧毁", "is_correct": false, "explanation": "语义：烧毁是把东西毁掉，与“成一个压缩包”的结果相矛盾。"}, {"text": "撕碎", "is_correct": false, "explanation": "搭配：“撕碎”与“压缩包”不搭配，撕碎的东西不会成为压缩包。"}], "explanations": {"聚合": "正确答案：聚合。请把这些文件聚合成一个压缩包，“聚合”表示把多个合为一个。", "删除": "语义：删除是去掉，不能得到一个压缩包。", "烧毁": "语义：烧毁是把东西毁掉，与“成一个压缩包”的结果相矛盾。", "撕碎": "搭配：“撕碎”与“压缩包”不搭配，撕碎的东西不会成为压缩包。"}, "sentence_index": 6, "correct_answer": "聚合"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "糖在水里聚合得很快。", "explanation": "这里应该用〈溶解〉。糖在水中化开是溶解，聚合指事物组合成整体。"}, {"text": "小麦在地里聚合得很好。", "explanation": "这里应该用〈生长〉。小麦长大是生长，不能用聚合。"}, {"text": "他用刀把木头聚合成了一个小人。", "explanation": "这里应该用〈雕刻〉。把木头刻成小人是雕刻，聚合不指加工成形。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfa4217b-4928-4b3d-b514-21ac69746120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25526, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把三张照片聚合了成一个文件夹。", "corrected_sentence": "他把三张照片聚合成了一个文件夹。", "error_description": "“了”位置错：“聚合”后先接结果补语“成”，“了”放在“成”之后，应说“聚合成了一个文件夹”，不能说“聚合了成”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfa4217b-4928-4b3d-b514-21ac69746120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25526, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几个视频聚合起了一个合集。", "corrected_sentence": "这几个视频聚合成了一个合集。", "error_description": "补语用错：表示变成一个合集应说“聚合成”。“起”是“起来”的一部分，不能单独接在“聚合”后面表示结果。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfa4217b-4928-4b3d-b514-21ac69746120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25530, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "低温", "is_correct": true, "explanation": "与“高温”构成反义，指气温低，与“高温”相对。"}, {"text": "湿度", "is_correct": false, "explanation": "“湿度”指空气湿润程度，与“高温”不构成反义。"}, {"text": "风力", "is_correct": false, "explanation": "“风力”指风的强弱，与“高温”不是反义关系。"}, {"text": "降水", "is_correct": false, "explanation": "“降水”指降落的雨雪等，与“高温”不构成反义。"}], "correct_answer": "低温", "explanations": {"低温": "与“高温”构成反义，指气温低，与“高温”相对。", "湿度": "“湿度”指空气湿润程度，与“高温”不构成反义。", "风力": "“风力”指风的强弱，与“高温”不是反义关系。", "降水": "“降水”指降落的雨雪等，与“高温”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfa4217b-4928-4b3d-b514-21ac69746120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25530, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "低温", "is_correct": true, "explanation": "与“高温”构成反义，指气温低，与“高温”相对。"}, {"text": "气压", "is_correct": false, "explanation": "“气压”指大气的压力，与“高温”不构成反义。"}, {"text": "风速", "is_correct": false, "explanation": "“风速”指风的快慢，与“高温”不是反义关系。"}, {"text": "雾霾", "is_correct": false, "explanation": "“雾霾”指空气污染现象，与“高温”不构成反义。"}], "correct_answer": "低温", "explanations": {"低温": "与“高温”构成反义，指气温低，与“高温”相对。", "气压": "“气压”指大气的压力，与“高温”不构成反义。", "风速": "“风速”指风的快慢，与“高温”不是反义关系。", "雾霾": "“雾霾”指空气污染现象，与“高温”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfa4217b-4928-4b3d-b514-21ac69746120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25530, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "天气非常热，像在火炉旁边一样。", "primary_collocate": null, "pronunciation": "gāo wēn", "ipa": "kaʊ˥ wən˥", "syllable_count": 2, "sentences": [{"text": "今天高温，外面像火炉一样。", "target_word": "高温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几天高温，我一出门就满身是汗。", "target_word": "高温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高温的天气让我只想待在空调房里。", "target_word": "高温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天的高温真让人受不了。", "target_word": "高温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高温天里走路，冰水一下就喝完了。", "target_word": "高温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高温的中午，街上几乎没有人。", "target_word": "高温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶说今年的高温比去年还厉害。", "target_word": "高温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高温天，孩子们都跑去河边玩水。", "target_word": "高温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高温让我晚上睡不着觉。", "target_word": "高温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在高温天里也要去上班。", "target_word": "高温", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "高温天", "label": "复合"}, {"form": "高溫", "label": "繁体"}], "register": "口语", "sense_fingerprint": "天气热得像火炉，让人难受", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1e12ecc-3ac0-4aa7-b224-954d9d880c62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25530, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高温", "is_correct": true, "explanation": "与“外面像火炉一样”呼应，描述天气炎热。"}, {"text": "寒流", "is_correct": false, "explanation": "语义：寒流带来降温，与“像火炉一样”的炎热相矛盾。"}, {"text": "湿度", "is_correct": false, "explanation": "搭配：“今天湿度”不能单独作主语描述天气，也与“像火炉”不相容。"}, {"text": "冷空气", "is_correct": false, "explanation": "语义：冷空气使天气变冷，与“外面像火炉一样”冲突。"}], "explanations": {"高温": "与“外面像火炉一样”呼应，描述天气炎热。", "寒流": "语义：寒流带来降温，与“像火炉一样”的炎热相矛盾。", "湿度": "搭配：“今天湿度”不能单独作主语描述天气，也与“像火炉”不相容。", "冷空气": "语义：冷空气使天气变冷，与“外面像火炉一样”冲突。"}, "sentence_index": 0, "correct_answer": "高温"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本小说的高温很精彩。", "explanation": "这里应该用〈高潮〉。“高潮”指情节最激烈、最精彩的部分，“高温”只指气温，不能用来说小说的情节。"}, {"text": "这里的房价很高温，我买不起。", "explanation": "这里应该用〈高〉。“高温”只指温度高，说价格贵要用“高”。"}, {"text": "这里有高温电，千万别靠近。", "explanation": "这里应该用〈高压〉。“高压”指电压高，“高温”只说温度，不能修饰“电”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfa4217b-4928-4b3d-b514-21ac69746120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25530, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高温", "is_correct": true, "explanation": "“高温”指热的程度，与“比去年还厉害”搭配，说明今年更热。"}, {"text": "账单", "is_correct": false, "explanation": "语义：账单是付款凭证，不能比较“厉害”的程度，与天气无关。"}, {"text": "鞋子", "is_correct": false, "explanation": "搭配：“鞋子”不能与“比去年还厉害”组成程度比较，与天气语境不合。"}, {"text": "积木", "is_correct": false, "explanation": "语义：积木是玩具，不能用“厉害”来描述气候，句子说不通。"}], "explanations": {"高温": "“高温”指热的程度，与“比去年还厉害”搭配，说明今年更热。", "账单": "语义：账单是付款凭证，不能比较“厉害”的程度，与天气无关。", "鞋子": "搭配：“鞋子”不能与“比去年还厉害”组成程度比较，与天气语境不合。", "积木": "语义：积木是玩具，不能用“厉害”来描述气候，句子说不通。"}, "sentence_index": 6, "correct_answer": "高温"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "早上高温时，公交车里特别挤。", "explanation": "这里应该用〈高峰〉。“高峰”指人流最多的时段，公交车挤说“早上高峰”，“高温”不能表示这个时段。"}, {"text": "我明年要参加高温，很紧张。", "explanation": "这里应该用〈高考〉。“高考”是全国统一的考试，“高温”只指天气，不能用来说参加考试。"}, {"text": "这首歌的高温很动听。", "explanation": "这里应该用〈高音〉。“高音”指音调高的声部，“高温”只说温度，不能用来形容歌声。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfa4217b-4928-4b3d-b514-21ac69746120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25530, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只高温压得人喘不过气。", "corrected_sentence": "那场高温压得人喘不过气。", "error_description": "量词错误：天气现象用量词“场”，“只”一般用于动物，不能用来数“高温”。应说“那场高温”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfa4217b-4928-4b3d-b514-21ac69746120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25530, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "高温了天里，老人最好少出门。", "corrected_sentence": "高温天里，老人最好少出门。", "error_description": "错误：“了”插在“高温”和“天”之间，拆开了“高温天”这个词。“高温天”中间不能加“了”，应说“高温天里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfa4217b-4928-4b3d-b514-21ac69746120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
