INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25536, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "用于聚在一起的许多人或动物的量词。", "primary_collocate": null, "pronunciation": "qún", "ipa": "tɕʰyn˧˥", "syllable_count": 1, "sentences": [{"text": "公园里有一群孩子在玩儿。", "target_word": "群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天上飞过一群鸟。", "target_word": "群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路边站着一群人。", "target_word": "群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "草地上有一群羊在吃草。", "target_word": "群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一群学生走进了教室。", "target_word": "群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河里有一群小鱼。", "target_word": "群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他和一群朋友去爬山。", "target_word": "群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一群蜜蜂在花上飞来飞去。", "target_word": "群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一群警察在门口等着。", "target_word": "群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我看见一群大雁往南飞。", "target_word": "群", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一群", "label": "量词搭配"}, {"form": "人群", "label": "复合"}, {"form": "鸟群", "label": "复合"}, {"form": "成群", "label": "复合"}], "register": "中性", "sense_fingerprint": "用于聚在一起的许多人或动物的量词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T1: 3 words above tier T1 (max 2): 蜜蜂 (Zipf 3.69), 飞来 (Zipf 3.47), 飞去 (Zipf 3.36)']::text[], 'af672a29-e1eb-4780-8f57-35ac2a0384e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25536, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "群", "is_correct": true, "explanation": "正确答案。群读 qún（第二声），指聚在一起的许多人或动物。"}, {"text": "寻", "is_correct": false, "explanation": "xún（第二声）与 qún 声母不同（x/q），意思是寻找。"}, {"text": "询", "is_correct": false, "explanation": "xún（第二声）与 qún 声母不同（x/q），意思是询问。"}, {"text": "全", "is_correct": false, "explanation": "quán（第二声）与 qún 韵母不同，意思是完整、全部。"}], "explanations": {"群": "正确答案。群读 qún（第二声），指聚在一起的许多人或动物。", "寻": "xún（第二声）与 qún 声母不同（x/q），意思是寻找。", "询": "xún（第二声）与 qún 声母不同（x/q），意思是询问。", "全": "quán（第二声）与 qún 韵母不同，意思是完整、全部。"}, "sentence_index": null, "correct_answer": "群"}, "level_3": {"options": [{"text": "座", "is_correct": false, "explanation": "搭配：“座”用于山、房屋等大型固定物，不能修饰“孩子”。"}, {"text": "群", "is_correct": true, "explanation": "正确。“一群”指聚在一起的许多人，与“孩子”搭配，句意通顺。"}, {"text": "颗", "is_correct": false, "explanation": "语义：“颗”用于小而圆的东西，与成群玩耍的孩子不符。"}, {"text": "条", "is_correct": false, "explanation": "体貌：“条”用于细长之物，孩子不具有这样的形状特征。"}], "explanations": {"座": "搭配：“座”用于山、房屋等大型固定物，不能修饰“孩子”。", "群": "正确。“一群”指聚在一起的许多人，与“孩子”搭配，句意通顺。", "颗": "语义：“颗”用于小而圆的东西，与成群玩耍的孩子不符。", "条": "体貌：“条”用于细长之物，孩子不具有这样的形状特征。"}, "sentence_index": 0, "correct_answer": "群"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "仓库里运来了一群货物。", "explanation": "这里应该用〈批〉。货物成批运来要用“批”，“群”多用于聚在一起的人或动物。"}, {"text": "他的桌上放着一群笔。", "explanation": "这里应该用〈支〉。笔按“支”计量，“群”只用于聚在一起的人或动物。"}, {"text": "我去车站买了一群车票。", "explanation": "这里应该用〈张〉。车票按“张”计量，“群”只用于聚在一起的人或动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4626a58c-eb93-4819-bf7d-f85fcc0a7cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25536, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "群", "is_correct": true, "explanation": "正确答案。群读 qún（第二声），指聚在一起的许多人或动物。"}, {"text": "巡", "is_correct": false, "explanation": "xún（第二声）与 qún 声母不同（x/q），意思是巡视。"}, {"text": "拳", "is_correct": false, "explanation": "quán（第二声）与 qún 韵母不同，意思是拳头。"}, {"text": "旬", "is_correct": false, "explanation": "xún（第二声）与 qún 声母不同（x/q），意思是十天。"}], "explanations": {"群": "正确答案。群读 qún（第二声），指聚在一起的许多人或动物。", "巡": "xún（第二声）与 qún 声母不同（x/q），意思是巡视。", "拳": "quán（第二声）与 qún 韵母不同，意思是拳头。", "旬": "xún（第二声）与 qún 声母不同（x/q），意思是十天。"}, "sentence_index": null, "correct_answer": "群"}, "level_3": {"options": [{"text": "匹", "is_correct": false, "explanation": "搭配：“匹”用于马、布等，不能修饰“朋友”。"}, {"text": "张", "is_correct": false, "explanation": "体貌：“张”用于平面、扁平之物，“朋友”不具有这种形态。"}, {"text": "群", "is_correct": true, "explanation": "正确。“一群朋友”指聚在一起的一伙人，与“他和”搭配，句意通顺。"}, {"text": "把", "is_correct": false, "explanation": "语义：“把”用于有柄可握的东西，与“朋友”无关，句意不通。"}], "explanations": {"匹": "搭配：“匹”用于马、布等，不能修饰“朋友”。", "张": "体貌：“张”用于平面、扁平之物，“朋友”不具有这种形态。", "群": "正确。“一群朋友”指聚在一起的一伙人，与“他和”搭配，句意通顺。", "把": "语义：“把”用于有柄可握的东西，与“朋友”无关，句意不通。"}, "sentence_index": 6, "correct_answer": "群"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "停车场里停着一群汽车。", "explanation": "这里应该用〈辆〉。汽车按“辆”计量，“群”只用于聚在一起的人或动物。"}, {"text": "桌上摆着一群花瓶。", "explanation": "这里应该用〈个〉。花瓶按“个”计量，“群”只用于聚在一起的人或动物。"}, {"text": "他的抽屉里放着一群旧信。", "explanation": "这里应该用〈封〉。信件按“封”计量，“群”只用于聚在一起的人或动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4626a58c-eb93-4819-bf7d-f85fcc0a7cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25536, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "树上停着一个群麻雀。", "corrected_sentence": "树上停着一群麻雀。", "error_description": "错误形式：「一个群麻雀」。正确形式：「一群麻雀」。“群”本身就是量词，前面不能再加“个”，应直接说“一群”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4626a58c-eb93-4819-bf7d-f85fcc0a7cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25536, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "门口站着一群记者们。", "corrected_sentence": "门口站着一群记者。", "error_description": "错误形式：「一群记者们」。正确形式：「一群记者」。“一群”已表示多数，后面的名词不能再加“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4626a58c-eb93-4819-bf7d-f85fcc0a7cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25538, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfa4217b-4928-4b3d-b514-21ac69746120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25538, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfa4217b-4928-4b3d-b514-21ac69746120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25538, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "很多小分子连在一起变成大分子，同时会放出水。", "primary_collocate": null, "pronunciation": "suō jù", "ipa": "swo˥ tɕy˥˩", "syllable_count": 2, "sentences": [{"text": "小分子缩聚以后，会变成大分子。", "target_word": "缩聚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做涤纶的时候，小分子要先缩聚。", "target_word": "缩聚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "缩聚的时候，会同时放出水。", "target_word": "缩聚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，很多小分子缩聚成一个大分子。", "target_word": "缩聚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "加热后，液体里的小分子慢慢缩聚了。", "target_word": "缩聚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "加聚不放出水，缩聚会放出水。", "target_word": "缩聚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "尼龙的小分子缩聚后，变成了长长的线。", "target_word": "缩聚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看，小分子缩聚时，杯子里出现了水珠。", "target_word": "缩聚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生做实验，让两种小分子缩聚在一起。", "target_word": "缩聚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "缩聚得到的大分子，比原来的小分子重很多。", "target_word": "缩聚", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "缩聚了", "label": "体标"}, {"form": "缩聚反应", "label": "复合"}, {"form": "缩聚物", "label": "复合"}], "register": "中性", "sense_fingerprint": "许多小分子连成大分子，同时放出水", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1e12ecc-3ac0-4aa7-b224-954d9d880c62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25538, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "缩聚", "is_correct": true, "explanation": "与后文“变成大分子”呼应，小分子连在一起才会变成大分子。"}, {"text": "切开", "is_correct": false, "explanation": "语义：切开会把东西分成小块，与“变成大分子”的结果相反。"}, {"text": "散步", "is_correct": false, "explanation": "搭配：“小分子”不能散步，句子说不通。"}, {"text": "讨论", "is_correct": false, "explanation": "搭配：“小分子”不能讨论，与“以后”后的变化没有关系。"}], "explanations": {"缩聚": "与后文“变成大分子”呼应，小分子连在一起才会变成大分子。", "切开": "语义：切开会把东西分成小块，与“变成大分子”的结果相反。", "散步": "搭配：“小分子”不能散步，句子说不通。", "讨论": "搭配：“小分子”不能讨论，与“以后”后的变化没有关系。"}, "sentence_index": 0, "correct_answer": "缩聚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "乙烯在催化剂作用下缩聚，生成聚乙烯，过程中不放出水。", "explanation": "这里应该用〈加聚〉。乙烯加聚不放出水，而缩聚要同时放出水，所以这里不能用缩聚。"}, {"text": "乙醇和乙酸在浓硫酸作用下缩聚，生成乙酸乙酯和水。", "explanation": "这里应该用〈酯化〉。乙酸乙酯是一个简单的小分子，并没有很多小分子连成大分子，所以不能用缩聚。"}, {"text": "水蒸气在空中缩聚成小水滴。", "explanation": "这里应该用〈凝结〉。水蒸气变成小水滴只是状态变化，没有小分子连成大分子，不能说缩聚。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfa4217b-4928-4b3d-b514-21ac69746120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25538, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "缩聚", "is_correct": true, "explanation": "与“变成了长长的线”呼应，小分子连成长链才能变成长线。"}, {"text": "切断", "is_correct": false, "explanation": "语义：切断会使链条变短，不会变成长长的线。"}, {"text": "唱歌", "is_correct": false, "explanation": "搭配：“小分子”不能唱歌，句子说不通。"}, {"text": "熄灭", "is_correct": false, "explanation": "语义：熄灭指火焰或光线消失，与“变成了长长的线”不相关。"}], "explanations": {"缩聚": "与“变成了长长的线”呼应，小分子连成长链才能变成长线。", "切断": "语义：切断会使链条变短，不会变成长长的线。", "唱歌": "搭配：“小分子”不能唱歌，句子说不通。", "熄灭": "语义：熄灭指火焰或光线消失，与“变成了长长的线”不相关。"}, "sentence_index": 6, "correct_answer": "缩聚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "蛋白质在胃酶作用下缩聚，分解成氨基酸。", "explanation": "这里应该用〈水解〉。蛋白质被酶分解成氨基酸是大分子断裂成小分子，与缩聚的方向相反。"}, {"text": "石油在塔里缩聚，得到汽油等不同的产品。", "explanation": "这里应该用〈分馏〉。分馏是按沸点把混合物分开，不是小分子连成大分子，所以不能用缩聚。"}, {"text": "盐水蒸发后会缩聚，析出食盐。", "explanation": "这里应该用〈结晶〉。食盐从溶液中析出是结晶，没有小分子连成大分子，不能说缩聚。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfa4217b-4928-4b3d-b514-21ac69746120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25538, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些小分子缩聚出去，形成了大分子。", "corrected_sentence": "这些小分子缩聚起来，形成了大分子。", "error_description": "趋向补语错误：小分子连成一体要说“缩聚起来”，“缩聚出去”方向不对。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfa4217b-4928-4b3d-b514-21ac69746120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25538, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两种小分子在加热时会缩聚着。", "corrected_sentence": "两种小分子在加热时会缩聚。", "error_description": "体标错误：“着”表示持续状态，与表示将来或可能的“会”搭配不自然，应说“会缩聚”，不加“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfa4217b-4928-4b3d-b514-21ac69746120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
