INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25540, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a73fe963-f640-4930-8c6d-59e02e87f32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25540, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "像把橡皮筋拉长一样变长。", "primary_collocate": null, "pronunciation": "yán shēn", "ipa": "jɛn˧˥ ʂən˥", "syllable_count": 2, "sentences": [{"text": "这条路一直延伸到山里。", "target_word": "延伸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "铁路向远方延伸。", "target_word": "延伸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座山脉向北延伸了很远。", "target_word": "延伸", "complexity_tier": "T3", "furigana": "zhè zuò shān mài xiàng běi yán shēn le hěn yuǎn.", "sentence_source": "generated"}, {"text": "这条小路延伸到村子后面。", "target_word": "延伸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长城在山上延伸了几千公里。", "target_word": "延伸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边的沙滩一直向前延伸。", "target_word": "延伸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁线路会延伸到机场。", "target_word": "延伸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大树的根向地下延伸。", "target_word": "延伸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这排电线一直向远处延伸。", "target_word": "延伸", "complexity_tier": "T3", "furigana": "zhè pái diàn xiàn yì zhí xiàng yuǎn chù yán shēn.", "sentence_source": "generated"}, {"text": "窗外的草地向远处延伸。", "target_word": "延伸", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "延伸了", "label": "体标"}, {"form": "延伸着", "label": "体标"}, {"form": "延伸过", "label": "体标"}], "register": "通用", "sense_fingerprint": "道路、线路等向远处伸展变长", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17259789-fe49-4308-9f94-df080a361105') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25540, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "延伸", "is_correct": true, "explanation": "「延伸」指道路等向远处伸展，与「这条路一直……到山里」相符，正确。"}, {"text": "流淌", "is_correct": false, "explanation": "搭配：「流淌」多指液体流动，不用来形容道路。"}, {"text": "闭合", "is_correct": false, "explanation": "语义：「闭合」指合上，与道路向远处伸展的情境不合。"}, {"text": "延误", "is_correct": false, "explanation": "语义：「延误」指耽误时间，与「道路伸到山里」无关。"}], "explanations": {"延伸": "「延伸」指道路等向远处伸展，与「这条路一直……到山里」相符，正确。", "流淌": "搭配：「流淌」多指液体流动，不用来形容道路。", "闭合": "语义：「闭合」指合上，与道路向远处伸展的情境不合。", "延误": "语义：「延误」指耽误时间，与「道路伸到山里」无关。"}, "sentence_index": 0, "correct_answer": "延伸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家店决定延伸营业时间到晚上十点。", "explanation": "这里应该用〈延长〉。「延伸」指道路、线路等空间上的伸展，时间变长要用「延长」。"}, {"text": "他起床后先延伸了一下身体。", "explanation": "这里应该用〈伸展〉。「延伸」用于道路、线路等，活动身体要用「伸展」。"}, {"text": "航班延伸了两个小时才起飞。", "explanation": "这里应该用〈延迟〉。「延伸」不能表示时间推后，航班推迟要用「延迟」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a73fe963-f640-4930-8c6d-59e02e87f32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25540, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "延伸", "is_correct": true, "explanation": "「延伸」指线路向远处伸展，与「地铁线路会……到机场」相符，正确。"}, {"text": "喷射", "is_correct": false, "explanation": "语义：「喷射」指液体或气体快速射出，线路不能喷射到机场。"}, {"text": "挥发", "is_correct": false, "explanation": "语义：「挥发」指液体变成气体散发，与线路伸到机场的情境不合。"}, {"text": "奔赴", "is_correct": false, "explanation": "语义：「奔赴」指人赶往某处，主语须是人，不能说线路奔赴机场。"}], "explanations": {"延伸": "「延伸」指线路向远处伸展，与「地铁线路会……到机场」相符，正确。", "喷射": "语义：「喷射」指液体或气体快速射出，线路不能喷射到机场。", "挥发": "语义：「挥发」指液体变成气体散发，与线路伸到机场的情境不合。", "奔赴": "语义：「奔赴」指人赶往某处，主语须是人，不能说线路奔赴机场。"}, "sentence_index": 6, "correct_answer": "延伸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把椅子延伸了一米。", "explanation": "这里应该用〈加长〉。「延伸」指道路、线路等空间的伸展，椅子变长要用「加长」。"}, {"text": "这次改革延伸了我们的工资。", "explanation": "这里应该用〈提高〉。「延伸」指道路、线路等空间上的伸展，工资增加要用「提高」。"}, {"text": "他延伸出手，和我打招呼。", "explanation": "这里应该用〈伸出〉。「延伸」用于道路、线路等，伸出手要用「伸出」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a73fe963-f640-4930-8c6d-59e02e87f32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25540, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一条河流延伸远处的湖边。", "corrected_sentence": "一条河流延伸到远处的湖边。", "error_description": "缺少补语：「延伸」不能直接带处所宾语，表示终点要加「到」，应说「延伸到远处的湖边」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a73fe963-f640-4930-8c6d-59e02e87f32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25540, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一条铁路线延伸了到港口。", "corrected_sentence": "一条铁路线延伸到了港口。", "error_description": "了的位置错误：「到」是结果补语，「了」应放在「到」之后，应说「延伸到了港口」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a73fe963-f640-4930-8c6d-59e02e87f32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
