INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25544, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "大家聚在一起，变成一大群人。", "primary_collocate": null, "pronunciation": "gòng jù", "ipa": "kʊŋ˥˩ tɕy˥˩", "syllable_count": 2, "sentences": [{"text": "节日到了，亲友们共聚一堂。", "target_word": "共聚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每年春节，全家人都会共聚在老家。", "target_word": "共聚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家下班后在饭店共聚。", "target_word": "共聚", "complexity_tier": "T3", "furigana": "gòng jù", "sentence_source": "generated"}, {"text": "孩子们放学后共聚在操场上。", "target_word": "共聚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老同学二十年后又共聚一堂。", "target_word": "共聚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "晚会上，客人们共聚在大厅。", "target_word": "共聚", "complexity_tier": "T3", "furigana": "gòng jù", "sentence_source": "generated"}, {"text": "他们在广场共聚，人越来越多。", "target_word": "共聚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村民们共聚在大树下听故事。", "target_word": "共聚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末大家共聚在公园里。", "target_word": "共聚", "complexity_tier": "T3", "furigana": "gòng jù", "sentence_source": "generated"}, {"text": "过年的时候，朋友们来我家共聚。", "target_word": "共聚", "complexity_tier": "T3", "furigana": "gòng jù", "sentence_source": "generated"}], "morphological_forms": [{"form": "共聚了", "label": "完成体"}, {"form": "共聚过", "label": "经历体"}, {"form": "共聚一堂", "label": "固定短语"}], "register": "书面语", "sense_fingerprint": "大家聚在一起成为一大群人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29ae13fa-e2f6-4de8-a72a-3575f717bdf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25544, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "共聚", "is_correct": true, "explanation": "gòng jù（第四声）指大家聚在一起，变成一大群人。"}, {"text": "工具", "is_correct": false, "explanation": "gōng jù（第一声）与 gòng jù（第四声）只差声调，意思是工具。"}, {"text": "共居", "is_correct": false, "explanation": "gòng jū 与 gòng jù 只差第二音节声调，意思是共同居住。"}, {"text": "共计", "is_correct": false, "explanation": "gòng jì 与 gòng jù 韵母不同（i 与 ü），意思是总计。"}], "explanations": {"共聚": "gòng jù（第四声）指大家聚在一起，变成一大群人。", "工具": "gōng jù（第一声）与 gòng jù（第四声）只差声调，意思是工具。", "共居": "gòng jū 与 gòng jù 只差第二音节声调，意思是共同居住。", "共计": "gòng jì 与 gòng jù 韵母不同（i 与 ü），意思是总计。"}, "sentence_index": null, "correct_answer": "共聚"}, "level_3": {"options": [{"text": "共聚", "is_correct": true, "explanation": "“共聚一堂”表示亲友聚在一个地方，与“节日到了”的语境相合。"}, {"text": "分散", "is_correct": false, "explanation": "语义：“分散”与“一堂”的聚集含义相反，句意不通。"}, {"text": "疏远", "is_correct": false, "explanation": "语义：“疏远”指关系变淡，与节日聚会的语境冲突。"}, {"text": "出发", "is_correct": false, "explanation": "搭配：“出发”不能与“一堂”搭配，“出发一堂”不成词组。"}], "explanations": {"共聚": "“共聚一堂”表示亲友聚在一个地方，与“节日到了”的语境相合。", "分散": "语义：“分散”与“一堂”的聚集含义相反，句意不通。", "疏远": "语义：“疏远”指关系变淡，与节日聚会的语境冲突。", "出发": "搭配：“出发”不能与“一堂”搭配，“出发一堂”不成词组。"}, "sentence_index": 0, "correct_answer": "共聚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在会上共聚了很多经验。", "explanation": "这里应该用〈分享〉。“共聚”指大家聚在一起、变成一大群人，不表示把经验交给别人，经验要说“分享”。"}, {"text": "我一个人共聚在教室里学习。", "explanation": "这里应该用〈独自〉。“共聚”要求多个人聚在一起，单独一人不能说“共聚”。"}, {"text": "代表们共聚了各自的意见。", "explanation": "这里应该用〈交换〉。“共聚”只说人聚到一处，不带“意见”这类抽象宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '359c172d-3f8c-4869-8425-155c116d2b2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25544, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "共聚", "is_correct": true, "explanation": "gòng jù（第四声）指大家聚在一起，变成一大群人。"}, {"text": "共举", "is_correct": false, "explanation": "gòng jǔ 与 gòng jù 只差第二音节声调（第三声与第四声），意思是共同推举或共同举起。"}, {"text": "公据", "is_correct": false, "explanation": "gōng jù 与 gòng jù 只差第一音节声调（第一声与第四声），意思是公共的凭据。"}, {"text": "恐惧", "is_correct": false, "explanation": "kǒng jù 与 gòng jù 第一音节声母（k 与 g）和声调都不同，意思是害怕。"}], "explanations": {"共聚": "gòng jù（第四声）指大家聚在一起，变成一大群人。", "共举": "gòng jǔ 与 gòng jù 只差第二音节声调（第三声与第四声），意思是共同推举或共同举起。", "公据": "gōng jù 与 gòng jù 只差第一音节声调（第一声与第四声），意思是公共的凭据。", "恐惧": "kǒng jù 与 gòng jù 第一音节声母（k 与 g）和声调都不同，意思是害怕。"}, "sentence_index": null, "correct_answer": "共聚"}, "level_3": {"options": [{"text": "共聚", "is_correct": true, "explanation": "“共聚”表示许多人聚在一处，与“人越来越多”的语境相合。"}, {"text": "散开", "is_correct": false, "explanation": "语义：“散开”指分散离去，与“人越来越多”的意思相反。"}, {"text": "发放", "is_correct": false, "explanation": "配价：“发放”是及物动词，需要带宾语，句中缺少宾语。"}, {"text": "散场", "is_correct": false, "explanation": "语义：“散场”指活动结束、人群离开，与“人越来越多”冲突。"}], "explanations": {"共聚": "“共聚”表示许多人聚在一处，与“人越来越多”的语境相合。", "散开": "语义：“散开”指分散离去，与“人越来越多”的意思相反。", "发放": "配价：“发放”是及物动词，需要带宾语，句中缺少宾语。", "散场": "语义：“散场”指活动结束、人群离开，与“人越来越多”冲突。"}, "sentence_index": 6, "correct_answer": "共聚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次展览共聚了三个月。", "explanation": "这里应该用〈持续〉。“共聚”指大家聚在一起，变成一大群人，不能用来说时间的延续，展览历时三个月要用“持续”。"}, {"text": "我们共聚了一场比赛。", "explanation": "这里应该用〈举办〉。“共聚”不能带“比赛”作宾语。"}, {"text": "一个苹果共聚在桌上。", "explanation": "这里应该用〈放〉。“共聚”指许多人聚在一起，物品不能说“共聚”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '359c172d-3f8c-4869-8425-155c116d2b2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25544, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "春节时，邻居们共聚院子里。", "corrected_sentence": "春节时，邻居们共聚在院子里。", "error_description": "漏掉了“在”。“共聚”后面的处所要用“在”引出，应为“共聚在院子里”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '359c172d-3f8c-4869-8425-155c116d2b2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25544, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "同学们在树下共聚了着，等待开会。", "corrected_sentence": "同学们在树下共聚着，等待开会。", "error_description": "“了”和“着”不能同时用在同一个动词后。表示状态的“着”应直接用在“共聚”后，正确说法是“共聚着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '359c172d-3f8c-4869-8425-155c116d2b2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
