INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25554, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "改变一个东西的样子或性质。", "primary_collocate": null, "pronunciation": "gǎi xìng", "ipa": "kai̯˨˩˦ ɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "工程师想给这种塑料改性。", "target_word": "改性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "橡胶改性以后，更耐热了。", "target_word": "改性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种纸要先改性，才不怕水。", "target_word": "改性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们正在给木头改性。", "target_word": "改性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "塑料改性以后，用的时间更长。", "target_word": "改性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们改性过很多种材料。", "target_word": "改性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些旧材料可以改性再用。", "target_word": "改性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们想把玻璃改性，让它不容易碎。", "target_word": "改性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "木头不改性，放在水里很快就坏了。", "target_word": "改性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先改性，再做成桌子。", "target_word": "改性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "改性了", "label": "体标"}, {"form": "改性过", "label": "体标"}, {"form": "改性剂", "label": "复合词"}], "register": "通用", "sense_fingerprint": "动手改变东西的性质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29ae13fa-e2f6-4de8-a72a-3575f717bdf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25554, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "改性", "is_correct": true, "explanation": "正确答案。改性（gǎi xìng）指动手改变东西的性质。"}, {"text": "改型", "is_correct": false, "explanation": "xíng（第二声）与 xìng（第四声）声调不同，意思是改变型号或样式。"}, {"text": "改命", "is_correct": false, "explanation": "mìng 与 xìng 声母不同（m 与 x），意思是改变命运。"}, {"text": "改信", "is_correct": false, "explanation": "xìn 与 xìng 韵尾不同（n 与 ng），意思是改变信仰或信念。"}], "explanations": {"改性": "正确答案。改性（gǎi xìng）指动手改变东西的性质。", "改型": "xíng（第二声）与 xìng（第四声）声调不同，意思是改变型号或样式。", "改命": "mìng 与 xìng 声母不同（m 与 x），意思是改变命运。", "改信": "xìn 与 xìng 韵尾不同（n 与 ng），意思是改变信仰或信念。"}, "sentence_index": null, "correct_answer": "改性"}, "level_3": {"options": [{"text": "改性", "is_correct": true, "explanation": "正确。工程师想给这种塑料改性，指改变塑料的性质，句意通顺。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”只用于食物，不能用于塑料，句意荒谬。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”是发声动作，与塑料无关，句子不通。"}, {"text": "读", "is_correct": false, "explanation": "配价：“读”的宾语须是文字或书籍，不能带“塑料”作宾语。"}], "explanations": {"改性": "正确。工程师想给这种塑料改性，指改变塑料的性质，句意通顺。", "吃": "语义：“吃”只用于食物，不能用于塑料，句意荒谬。", "唱": "语义：“唱”是发声动作，与塑料无关，句子不通。", "读": "配价：“读”的宾语须是文字或书籍，不能带“塑料”作宾语。"}, "sentence_index": 0, "correct_answer": "改性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们改性了工作条件。", "explanation": "这里应该用〈改善〉。改性指改变东西的性质，工作条件的变好要用改善。"}, {"text": "导演把小说改性成了电影。", "explanation": "这里应该用〈改编〉。改性指改变东西的性质，小说改写成剧本要用改编。"}, {"text": "他改性了作业里的错误。", "explanation": "这里应该用〈改正〉。改性指改变东西的性质，纠正错误要用改正。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '359c172d-3f8c-4869-8425-155c116d2b2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25554, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "改性", "is_correct": true, "explanation": "正确。这些旧材料可以改性再用，指先改变材料性质再重新使用。"}, {"text": "丢弃", "is_correct": false, "explanation": "语义：“丢弃”是不要了，与“再用”的意思相矛盾。"}, {"text": "焚烧", "is_correct": false, "explanation": "语义：“焚烧”会把材料烧毁，无法再用，句意矛盾。"}, {"text": "倒掉", "is_correct": false, "explanation": "搭配：“倒掉”多用于液体，不用于旧材料。"}], "explanations": {"改性": "正确。这些旧材料可以改性再用，指先改变材料性质再重新使用。", "丢弃": "语义：“丢弃”是不要了，与“再用”的意思相矛盾。", "焚烧": "语义：“焚烧”会把材料烧毁，无法再用，句意矛盾。", "倒掉": "搭配：“倒掉”多用于液体，不用于旧材料。"}, "sentence_index": 6, "correct_answer": "改性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把坏掉的椅子改性好了。", "explanation": "这里应该用〈修理〉。改性指改变东西的性质，把坏了的器物修好要用修理。"}, {"text": "她把自己改性得很漂亮。", "explanation": "这里应该用〈打扮〉。改性指改变东西的性质，不用于人的外貌装扮，要用打扮。"}, {"text": "他改性了房间里的书。", "explanation": "这里应该用〈整理〉。改性指改变东西的性质，书籍的摆放和收拾要用整理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '359c172d-3f8c-4869-8425-155c116d2b2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25554, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们改性了过这种材料，效果不错。", "corrected_sentence": "我们改性过这种材料，效果不错。", "error_description": "“过”表示经历，与“了”不能同时使用。应去掉“了”，说“改性过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '359c172d-3f8c-4869-8425-155c116d2b2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25554, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些木头改性后了，就不容易烂了。", "corrected_sentence": "这些木头改性后，就不容易烂了。", "error_description": "“改性后”中的“后”表示之后，后面不能再加“了”。应说“改性后”，不说“改性后了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '359c172d-3f8c-4869-8425-155c116d2b2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
