INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25556, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "事情还没发生，先做好准备。", "primary_collocate": null, "pronunciation": "yù xiān", "ipa": "y˥˩ ɕjɛn˥", "syllable_count": 2, "sentences": [{"text": "考试以前，他预先复习了所有课文。", "target_word": "预先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子要出生了，他们预先买好了小床。", "target_word": "预先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气会变冷，请预先带上外衣。", "target_word": "预先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你预先想好问题，面试时不会紧张。", "target_word": "预先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板预先安排好了明天的工作。", "target_word": "预先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了安全，我们预先检查了机器。", "target_word": "预先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王预先写好了发言的稿子。", "target_word": "预先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议九点开始，大家最好预先准备好发言稿。", "target_word": "预先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她预先准备了一些药，旅行时用。", "target_word": "预先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生预先告诉他，吃药后会想睡觉。", "target_word": "预先", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词：事情未发生，先做准备", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cec2e43-2775-454a-9511-b4b696244bdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25556, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "尚未", "is_correct": false, "explanation": "语义：尚未表示还没有发生，与「复习了所有课文」的完成态矛盾。"}, {"text": "预先", "is_correct": true, "explanation": "预先表示考试之前先做好准备，与「考试以前」和「复习了所有课文」的顺序相合。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：从来要与否定词连用，不能和「复习了」这样的肯定完成句搭配。"}, {"text": "正在", "is_correct": false, "explanation": "语法：正在表示动作进行中，不能和表示完成的「复习了」一起用。"}], "explanations": {"尚未": "语义：尚未表示还没有发生，与「复习了所有课文」的完成态矛盾。", "预先": "预先表示考试之前先做好准备，与「考试以前」和「复习了所有课文」的顺序相合。", "从来": "搭配：从来要与否定词连用，不能和「复习了」这样的肯定完成句搭配。", "正在": "语法：正在表示动作进行中，不能和表示完成的「复习了」一起用。"}, "sentence_index": 0, "correct_answer": "预先"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "起初他很紧张，预先习惯了。", "explanation": "这里应该用〈后来〉。预先指事情发生前的准备，不能描述逐渐发生的变化。"}, {"text": "听到这个消息，他预先冲了出去。", "explanation": "这里应该用〈立刻〉。预先表示事情发生之前做准备，而他是听到消息之后才行动，时间顺序矛盾。"}, {"text": "我预先在书店遇到了老师。", "explanation": "这里应该用〈偶然〉。预先表示事先准备，在书店遇到老师是没有计划的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8a17325-c333-4116-93cf-78505131cfb7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25556, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "千万", "is_correct": false, "explanation": "语法：千万用于劝告或命令，如「千万别忘了」，不能用在叙述已完成事情的陈述句里。"}, {"text": "难道", "is_correct": false, "explanation": "语法：难道用于反问句，句末要有「吗」，这里是普通陈述句，不能用。"}, {"text": "一直", "is_correct": false, "explanation": "搭配：一直修饰持续的动作，不能与「写好了」这样一次性完成的结果搭配。"}, {"text": "预先", "is_correct": true, "explanation": "预先表示在写稿之前先做好准备，与「写好了稿子」的顺序相合。"}], "explanations": {"千万": "语法：千万用于劝告或命令，如「千万别忘了」，不能用在叙述已完成事情的陈述句里。", "难道": "语法：难道用于反问句，句末要有「吗」，这里是普通陈述句，不能用。", "一直": "搭配：一直修饰持续的动作，不能与「写好了」这样一次性完成的结果搭配。", "预先": "预先表示在写稿之前先做好准备，与「写好了稿子」的顺序相合。"}, "sentence_index": 6, "correct_answer": "预先"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他接到电话，预先出发了。", "explanation": "这里应该用〈马上〉。预先指事情发生之前的准备，而他是接到电话之后才出发，时间顺序矛盾。"}, {"text": "听到老师的问题，他预先举起了手。", "explanation": "这里应该用〈立刻〉。预先表示事情发生之前做准备，而他是听到问题之后才举手，时间顺序矛盾。"}, {"text": "他努力了很久，预先考上了大学。", "explanation": "这里应该用〈终于〉。预先表示事先准备，考上大学是长期努力后的结果，不是事先做的准备。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8a17325-c333-4116-93cf-78505131cfb7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25556, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们预先了把行李收拾好了。", "corrected_sentence": "他们预先把行李收拾好了。", "error_description": "错误：「预先」是副词，后面不能直接加「了」。「了」应放在动词「收拾好」之后，应写作「他们预先把行李收拾好了」，不能说「预先了把行李收拾好了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8a17325-c333-4116-93cf-78505131cfb7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25556, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她昨天把预先准备了发言稿。", "corrected_sentence": "她昨天预先准备了发言稿。", "error_description": "错误：「把」字后直接接副词「预先」，缺少名词宾语，「把」字结构不成立。应写作「她昨天预先准备了发言稿」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8a17325-c333-4116-93cf-78505131cfb7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
