INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25560, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把几个东西合在一起。", "primary_collocate": null, "pronunciation": "fù hé", "ipa": "fu˥˩ xɤ˧˥", "syllable_count": 2, "sentences": [{"text": "师傅把两块板复合在一起。", "target_word": "复合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "先把这几层纸复合起来。", "target_word": "复合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两层布复合以后，包更厚了。", "target_word": "复合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个杯子由玻璃和金属复合而成。", "target_word": "复合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂用胶把塑料薄膜和纸复合起来。", "target_word": "复合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三种材料复合后，效果更好。", "target_word": "复合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把几块小木头复合成一块大板。", "target_word": "复合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这两层皮是怎么复合的？", "target_word": "复合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们试过把铁和塑料复合起来。", "target_word": "复合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几层薄膜复合后，变得更结实了。", "target_word": "复合", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "复合了", "label": "完成体"}, {"form": "复合过", "label": "经历体"}, {"form": "复合材料", "label": "复合词"}, {"form": "複合", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "把几个东西合在一起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29ae13fa-e2f6-4de8-a72a-3575f717bdf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25560, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "复合", "is_correct": true, "explanation": "正确答案。复合（fù hé）指把几个东西合在一起。"}, {"text": "符合", "is_correct": false, "explanation": "fú（第二声）与 fù（第四声）声调不同，意思是与标准或事实相合。"}, {"text": "附和", "is_correct": false, "explanation": "hè（第四声）与 hé（第二声）声调不同，意思是跟着别人说相同的话。"}, {"text": "不合", "is_correct": false, "explanation": "bù 与 fù 声母不同（b 与 f），意思是不相合、不合适。"}, {"text": "富含", "is_correct": false, "explanation": "hán（第二声）与 hé 韵母不同（an 与 e），意思是丰富地包含某种成分。"}], "explanations": {"复合": "正确答案。复合（fù hé）指把几个东西合在一起。", "符合": "fú（第二声）与 fù（第四声）声调不同，意思是与标准或事实相合。", "附和": "hè（第四声）与 hé（第二声）声调不同，意思是跟着别人说相同的话。", "不合": "bù 与 fù 声母不同（b 与 f），意思是不相合、不合适。", "富含": "hán（第二声）与 hé 韵母不同（an 与 e），意思是丰富地包含某种成分。"}, "sentence_index": null, "correct_answer": "复合"}, "level_3": {"options": [{"text": "复合", "is_correct": true, "explanation": "正确。师傅把两块板复合在一起，表示把两块板合成一体。"}, {"text": "分开", "is_correct": false, "explanation": "语义：“分开”与后面的“在一起”意思相反，句子自相矛盾。"}, {"text": "拆开", "is_correct": false, "explanation": "语义：“拆开”是拆散，与“在一起”的意思相反，句意不通。"}, {"text": "切开", "is_correct": false, "explanation": "搭配：“切开”指用刀等把东西切断，不用于把两块板合到一起的语境。"}], "explanations": {"复合": "正确。师傅把两块板复合在一起，表示把两块板合成一体。", "分开": "语义：“分开”与后面的“在一起”意思相反，句子自相矛盾。", "拆开": "语义：“拆开”是拆散，与“在一起”的意思相反，句意不通。", "切开": "搭配：“切开”指用刀等把东西切断，不用于把两块板合到一起的语境。"}, "sentence_index": 0, "correct_answer": "复合"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两家公司复合成了一家。", "explanation": "这里应该用〈合并〉。复合多用于材料、物质的组合，公司之间的归并要用合并。"}, {"text": "两条河在这里复合了。", "explanation": "这里应该用〈汇合〉。复合指把几个东西合成一个整体，河流汇到一处要用汇合。"}, {"text": "这只鸟在树上复合了。", "explanation": "这里应该用〈栖息〉。复合指把几样东西合成整体，鸟停歇在树上要用栖息。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '359c172d-3f8c-4869-8425-155c116d2b2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25560, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "复合", "is_correct": true, "explanation": "正确。几块小木头复合成一块大板，表示合成一个整体。"}, {"text": "分解", "is_correct": false, "explanation": "语义：“分解”是拆成部分，与“合成一块大板”的方向相反，句意不通。"}, {"text": "拆散", "is_correct": false, "explanation": "语义：“拆散”是分开，与合成一块大板的结果相矛盾。"}, {"text": "切碎", "is_correct": false, "explanation": "搭配：“切碎”多指弄成碎块，不能接“成一块大板”。"}], "explanations": {"复合": "正确。几块小木头复合成一块大板，表示合成一个整体。", "分解": "语义：“分解”是拆成部分，与“合成一块大板”的方向相反，句意不通。", "拆散": "语义：“拆散”是分开，与合成一块大板的结果相矛盾。", "切碎": "搭配：“切碎”多指弄成碎块，不能接“成一块大板”。"}, "sentence_index": 6, "correct_answer": "复合"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他和队友在比赛中复合得很好。", "explanation": "这里应该用〈配合〉。复合指把材料等合成一体，人与人协同做事要用配合。"}, {"text": "几个国家复合起来抗议了。", "explanation": "这里应该用〈联合〉。复合指部件组合成整体，团体之间的联合行动要用联合。"}, {"text": "他的脾气在这里复合了。", "explanation": "这里应该用〈发作〉。复合指把几样东西合成整体，脾气突然显露要用发作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '359c172d-3f8c-4869-8425-155c116d2b2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25560, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们把两张纸复合掉，做成卡片。", "corrected_sentence": "他们把两张纸复合在一起，做成卡片。", "error_description": "错误形式是“复合掉”。“复合”表示合成一体，不能接“掉”（表示去除），应为“复合在一起”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '359c172d-3f8c-4869-8425-155c116d2b2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25560, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几层布复合起去，更加保暖。", "corrected_sentence": "这几层布复合起来，更加保暖。", "error_description": "“复合起来”中的“来”表示结果是合成一体，不能说“起去”，应为“复合起来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '359c172d-3f8c-4869-8425-155c116d2b2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
