INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25564, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "东西上裂开的小缝。", "primary_collocate": null, "pronunciation": "liè wén", "ipa": "ljɛ˥˩ wən˧˥", "syllable_count": 2, "sentences": [{"text": "碗掉在地上，边上有了一条裂纹。", "target_word": "裂纹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看着茶杯上的裂纹，不想用了。", "target_word": "裂纹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰面上有很长的裂纹，别走过去。", "target_word": "裂纹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "木桌太干，桌面出现了一条裂纹。", "target_word": "裂纹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她摸了摸盘子，找到一条细裂纹。", "target_word": "裂纹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车窗玻璃上的裂纹越变越长。", "target_word": "裂纹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这面镜子有裂纹，不能买。", "target_word": "裂纹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老房子的地板上有很多裂纹。", "target_word": "裂纹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷用旧茶壶，壶身有几条裂纹。", "target_word": "裂纹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小心，墙上的裂纹里有水流出来。", "target_word": "裂纹", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "微裂纹", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词：东西上裂开的小缝", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cec2e43-2775-454a-9511-b4b696244bdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25564, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "鱼", "is_correct": false, "explanation": "语义：鱼是动物，碗掉在地上后的破损与鱼无关，与语境不符。"}, {"text": "路", "is_correct": false, "explanation": "搭配：「一条路」指可以通行的道路，碗的边上不能说「有了一条路」。"}, {"text": "裂纹", "is_correct": true, "explanation": "裂纹指东西上裂开的小缝，与碗掉在地上后边缘出现裂口的情境相合。"}, {"text": "裙子", "is_correct": false, "explanation": "语义：裙子是衣物，碗的边上不会出现一条裙子，与语境不符。"}], "explanations": {"鱼": "语义：鱼是动物，碗掉在地上后的破损与鱼无关，与语境不符。", "路": "搭配：「一条路」指可以通行的道路，碗的边上不能说「有了一条路」。", "裂纹": "裂纹指东西上裂开的小缝，与碗掉在地上后边缘出现裂口的情境相合。", "裙子": "语义：裙子是衣物，碗的边上不会出现一条裙子，与语境不符。"}, "sentence_index": 0, "correct_answer": "裂纹"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "木桌太干，桌面出现了一只裂纹。", "explanation": "这里应该用〈条〉。「只」多用于动物或成对器物，裂纹是细长的线状，应用「条」计量。"}, {"text": "木桌太干，桌上出现了一块裂纹。", "explanation": "这里应该用〈条〉。「块」指成片的东西，裂纹是细长的线条，不能用「块」计量。"}, {"text": "木桌太干，桌面出现了一张裂纹。", "explanation": "这里应该用〈条〉。「张」用于纸、床等平面的东西，裂纹不能用「张」计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8a17325-c333-4116-93cf-78505131cfb7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25564, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "歌声", "is_correct": false, "explanation": "语义：镜子不会发出歌声，「有歌声」与「不能买」的理由无关。"}, {"text": "裂纹", "is_correct": true, "explanation": "裂纹指镜子上的细小裂缝，是不能买的理由，与语境相合。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：「有价格」不能用来说明镜子的状况，应说「价格高」，与「有」搭配不当。"}, {"text": "呼吸", "is_correct": false, "explanation": "语义：镜子没有呼吸，「有呼吸」不是商品缺陷，与语境不符。"}], "explanations": {"歌声": "语义：镜子不会发出歌声，「有歌声」与「不能买」的理由无关。", "裂纹": "裂纹指镜子上的细小裂缝，是不能买的理由，与语境相合。", "价格": "搭配：「有价格」不能用来说明镜子的状况，应说「价格高」，与「有」搭配不当。", "呼吸": "语义：镜子没有呼吸，「有呼吸」不是商品缺陷，与语境不符。"}, "sentence_index": 6, "correct_answer": "裂纹"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "湖面上泛起一圈裂纹。", "explanation": "这里应该用〈波纹〉。裂纹指物体裂开的缝，水面的圈状起伏应用「波纹」。"}, {"text": "这首曲子的裂纹很动听。", "explanation": "这里应该用〈旋律〉。裂纹指物体裂开的小缝，不能用来形容曲子，「旋律」才是曲子的组成部分。"}, {"text": "这杯咖啡的裂纹很浓。", "explanation": "这里应该用〈香气〉。裂纹指物体裂开的缝，咖啡的香味要说香气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8a17325-c333-4116-93cf-78505131cfb7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25564, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "车窗上有一张裂纹。", "corrected_sentence": "车窗上有一条裂纹。", "error_description": "量词错误：「张」用于纸、床等平面的东西；「裂纹」是细长的线状，应用「条」，正确说法是「车窗上有一条裂纹」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8a17325-c333-4116-93cf-78505131cfb7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25564, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "墙上有很多裂纹们。", "corrected_sentence": "墙上有很多裂纹。", "error_description": "错误：「们」只用于指人的名词之后，「裂纹」是物体，不能加「们」，应说「墙上有很多裂纹」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8a17325-c333-4116-93cf-78505131cfb7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
