INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25566, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用于填充空隙、增加体积的材料。", "primary_collocate": null, "pronunciation": "tián liào", "ipa": "tʰjɛn˧˥ ljɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "这个箱子里放着填料。", "target_word": "填料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "填料是用来填空隙的材料。", "target_word": "填料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把填料倒进了桶里。", "target_word": "填料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙上的裂缝需要用填料补好。", "target_word": "填料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种填料粒径细，成本低。", "target_word": "填料", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在塑料制品中加入一定量的填料，可以降低成本。", "target_word": "填料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做沙发要用很多填料。", "target_word": "填料", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些填料是从工厂运来的。", "target_word": "填料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "填料含量过低，制品就不够密实。", "target_word": "填料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了两袋白色的填料。", "target_word": "填料", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种填料", "label": "量词"}, {"form": "一袋填料", "label": "量词"}, {"form": "无机填料", "label": "复合词"}], "register": "科技", "sense_fingerprint": "用来填充东西的材料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d11fcc8-d62b-4b13-af83-f4f5872bc024') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25566, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "填料", "is_correct": true, "explanation": "正确：箱子里放的是用来填充的材料，与句意相符。"}, {"text": "友谊", "is_correct": false, "explanation": "语义：友谊是抽象的情感，不能放进箱子里。"}, {"text": "星期", "is_correct": false, "explanation": "语义：星期是时间单位，不是能放进箱子的东西。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：「放着」后接具体物品，「心情」不能被放进箱子。"}], "explanations": {"填料": "正确：箱子里放的是用来填充的材料，与句意相符。", "友谊": "语义：友谊是抽象的情感，不能放进箱子里。", "星期": "语义：星期是时间单位，不是能放进箱子的东西。", "心情": "搭配：「放着」后接具体物品，「心情」不能被放进箱子。"}, "sentence_index": 0, "correct_answer": "填料"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种填料很结实，可以用来做桌子的腿。", "explanation": "这里应该用〈材料〉。填料只用来填充空隙，不能作为承重的结构材料。"}, {"text": "他用填料把纸片粘在了本子上。", "explanation": "这里应该用〈胶水〉。填料用来填充空隙，不起粘合作用，不能用来粘纸。"}, {"text": "妈妈用填料煮了一锅粥。", "explanation": "这里应该用〈面粉〉。填料是用来填充东西的材料，不能用来煮粥。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d84cfb1-221a-4b10-bbee-f3a36a0ddda0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25566, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "填料", "is_correct": true, "explanation": "正确：做沙发要用填充材料，与句意相符。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板是教学用品，做沙发不用它。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮是天体，不能用来做沙发。"}, {"text": "理想", "is_correct": false, "explanation": "搭配：「做」的宾语应为具体材料，「理想」是抽象概念。"}], "explanations": {"填料": "正确：做沙发要用填充材料，与句意相符。", "黑板": "语义：黑板是教学用品，做沙发不用它。", "月亮": "语义：月亮是天体，不能用来做沙发。", "理想": "搭配：「做」的宾语应为具体材料，「理想」是抽象概念。"}, "sentence_index": 6, "correct_answer": "填料"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在咖啡里加了一些填料。", "explanation": "这里应该用〈糖〉。填料用来填充材料，不能加进食物里。"}, {"text": "他用填料把墙刷成了蓝色。", "explanation": "这里应该用〈颜料〉。填料不能用来上色，刷墙要用颜料。"}, {"text": "他喝了一些填料。", "explanation": "这里应该用〈饮料〉。填料不能饮用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d84cfb1-221a-4b10-bbee-f3a36a0ddda0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25566, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她买了三条填料。", "corrected_sentence": "她买了三袋填料。", "error_description": "错误在量词：「条」用于细长的东西，填料应用「袋」计量，应说「三袋填料」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d84cfb1-221a-4b10-bbee-f3a36a0ddda0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25566, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这匹填料很重。", "corrected_sentence": "这箱填料很重。", "error_description": "错误在量词：「匹」用于马等牲口，不能用于填料，应说「这箱填料」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d84cfb1-221a-4b10-bbee-f3a36a0ddda0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
