INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25570, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个东西外面所有面的大小加起来。", "primary_collocate": null, "pronunciation": "biǎo miàn jī", "ipa": "piɑʊ̯˨˩˦ mjɛn˥˩ tɕi˥", "syllable_count": 3, "sentences": [{"text": "请你算一算这本书的表面积是多少。", "target_word": "表面积", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个小方盒子的表面积是二十四平方厘米。", "target_word": "表面积", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想知道这个大箱子的表面积。", "target_word": "表面积", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "表面积是一个东西外面所有面加起来的大小。", "target_word": "表面积", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个盒子有六个面，表面积就是六个面加在一起。", "target_word": "表面积", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小球的表面积比大球小。", "target_word": "表面积", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "工人要用多少油漆，得先看房子的表面积。", "target_word": "表面积", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一块糖切成小块以后，总的表面积变大了。", "target_word": "表面积", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把盒子打开，算出了它的表面积。", "target_word": "表面积", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水桶的表面积比水杯大得多。", "target_word": "表面积", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "表面積", "label": "繁体"}, {"form": "总表面积", "label": "复合"}], "register": "中性", "sense_fingerprint": "表面积：一个东西外面所有面的大小加起来，常用来算盒子、球、墙的面积", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d854d00-1f88-4c3f-9c27-9bef55911eec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25570, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "表面积", "is_correct": true, "explanation": "正确。算书的表面积，就是算书外面所有面的面积之和。"}, {"text": "作者", "is_correct": false, "explanation": "搭配：“作者”不能用“算一算”和“多少”来问。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色是视觉特征，不是可以算出多少的数量。"}, {"text": "封面", "is_correct": false, "explanation": "语义：封面是书的一个部分，不是可以算出多少的数量。"}], "explanations": {"表面积": "正确。算书的表面积，就是算书外面所有面的面积之和。", "作者": "搭配：“作者”不能用“算一算”和“多少”来问。", "颜色": "语义：颜色是视觉特征，不是可以算出多少的数量。", "封面": "语义：封面是书的一个部分，不是可以算出多少的数量。"}, "sentence_index": 0, "correct_answer": "表面积"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个计划的表面积很大，大家都觉得难做。", "explanation": "这里应该用〈范围〉。表面积只指一个东西外面所有面的大小，计划的大小要说范围。"}, {"text": "这个冰箱的表面积很大，能放很多东西。", "explanation": "这里应该用〈体积〉。表面积量的是外表的面，装多少东西要看体积。"}, {"text": "这块玻璃的表面积很光滑。", "explanation": "这里应该用〈表面〉。表面积是面的大小，不能形容光滑；说玻璃光不光滑要说表面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3077faca-1268-451b-bb11-eb7906611bf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25570, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "表面积", "is_correct": true, "explanation": "正确。刷油漆要先知道要刷多大的面，所以要看表面积。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：房子的年龄和要用多少油漆无关，不能代替“表面积”。"}, {"text": "门牌号", "is_correct": false, "explanation": "语义：门牌号只是编号，与油漆用量无关，读起来不通。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：体温只用于人或动物，不能说房子的体温。"}], "explanations": {"表面积": "正确。刷油漆要先知道要刷多大的面，所以要看表面积。", "年龄": "语义：房子的年龄和要用多少油漆无关，不能代替“表面积”。", "门牌号": "语义：门牌号只是编号，与油漆用量无关，读起来不通。", "体温": "搭配：体温只用于人或动物，不能说房子的体温。"}, "sentence_index": 6, "correct_answer": "表面积"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这箱苹果的表面积有二十斤。", "explanation": "这里应该用〈重量〉。表面积是面的大小，单位是平方；斤是质量单位，不能用来量表面积。"}, {"text": "这杯水的表面积是六十度。", "explanation": "这里应该用〈温度〉。表面积只表示面的大小，不能用度数来说冷热；水的冷热要说温度。"}, {"text": "这块石头的表面积很高，锤子都敲不碎。", "explanation": "这里应该用〈硬度〉。表面积只表示面的大小，不能说高低、软硬；坚硬的程度要说硬度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3077faca-1268-451b-bb11-eb7906611bf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25570, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个纸盒的表面积是三百厘米。", "corrected_sentence": "这个纸盒的表面积是三百平方厘米。", "error_description": "错在“表面积”的单位：应说“平方厘米”。表面积是面的面积，要用平方单位；“厘米”是长度单位。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3077faca-1268-451b-bb11-eb7906611bf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25570, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这间仓库的表面积是三百立方米。", "corrected_sentence": "这间仓库的表面积是三百平方米。", "error_description": "错在单位：表面积要用“平方米”，“立方米”是体积的单位，不能用来量表面积。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3077faca-1268-451b-bb11-eb7906611bf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25572, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "缩小", "is_correct": true, "explanation": "缩小与扩大互为反义，指空间或东西变得比原来小。"}, {"text": "提供", "is_correct": false, "explanation": "提供指供给，与扩大没有反义关系。"}, {"text": "留下", "is_correct": false, "explanation": "留下指留存，与扩大没有反义关系。"}, {"text": "站住", "is_correct": false, "explanation": "站住指停稳不动，与扩大没有反义关系。"}], "correct_answer": "缩小", "explanations": {"缩小": "缩小与扩大互为反义，指空间或东西变得比原来小。", "提供": "提供指供给，与扩大没有反义关系。", "留下": "留下指留存，与扩大没有反义关系。", "站住": "站住指停稳不动，与扩大没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8a17325-c333-4116-93cf-78505131cfb7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25572, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "缩小", "is_correct": true, "explanation": "缩小与扩大互为反义，指空间或东西变得比原来小。"}, {"text": "挂断", "is_correct": false, "explanation": "挂断指切断通话，与扩大没有反义关系。"}, {"text": "准备", "is_correct": false, "explanation": "准备指事先安排，与扩大没有反义关系。"}, {"text": "搬运", "is_correct": false, "explanation": "搬运指移动东西，与扩大没有反义关系。"}], "correct_answer": "缩小", "explanations": {"缩小": "缩小与扩大互为反义，指空间或东西变得比原来小。", "挂断": "挂断指切断通话，与扩大没有反义关系。", "准备": "准备指事先安排，与扩大没有反义关系。", "搬运": "搬运指移动东西，与扩大没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8a17325-c333-4116-93cf-78505131cfb7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25572, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使东西变得比原来更大，或东西自身变得比原来更大。", "primary_collocate": null, "pronunciation": "kuò dà", "ipa": "kʰuo˥˩ ta˥˩", "syllable_count": 2, "sentences": [{"text": "这个房间太小，我们想把它扩大。", "target_word": "扩大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把院子扩大了一倍。", "target_word": "扩大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们想买下旁边的地，把花园扩大。", "target_word": "扩大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，他的伤口正在扩大。", "target_word": "扩大", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个洞太小，工人用机器把它扩大了。", "target_word": "扩大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下了几天雨，湖面一天天扩大。", "target_word": "扩大", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "墙上的裂缝在慢慢扩大，要快点儿修。", "target_word": "扩大", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们把客厅扩大了，现在能坐十个人。", "target_word": "扩大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个停车场太小，政府决定把它扩大。", "target_word": "扩大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游泳池太小，他们把它扩大了。", "target_word": "扩大", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "扩大了", "label": "体标（了）"}, {"form": "扩大过", "label": "体标（过）"}, {"form": "扩大化", "label": "复合词"}], "register": "中性", "sense_fingerprint": "具体的空间或东西变得比原来更大（可及物，也可不及物）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cec2e43-2775-454a-9511-b4b696244bdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25572, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "扩大", "is_correct": true, "explanation": "我们想把房间扩大，表示使空间变得比原来大，符合句意。"}, {"text": "叫醒", "is_correct": false, "explanation": "语义：叫醒的对象是人，房间不能被叫醒。"}, {"text": "煮熟", "is_correct": false, "explanation": "搭配：煮熟用于食物，不能用于房间。"}, {"text": "唱", "is_correct": false, "explanation": "配价：唱需要歌曲作宾语，不能说唱房间。"}], "explanations": {"扩大": "我们想把房间扩大，表示使空间变得比原来大，符合句意。", "叫醒": "语义：叫醒的对象是人，房间不能被叫醒。", "煮熟": "搭配：煮熟用于食物，不能用于房间。", "唱": "配价：唱需要歌曲作宾语，不能说唱房间。"}, "sentence_index": 0, "correct_answer": "扩大"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他跑步的速度扩大了一点儿。", "explanation": "这里应该用〈提高〉。扩大指空间或东西变大，速度的提升要说提高。"}, {"text": "会议扩大了一个小时。", "explanation": "这里应该用〈延长〉。扩大用于空间或东西，时间的增长要说延长。"}, {"text": "这种药能让他的体重扩大。", "explanation": "这里应该用〈增加〉。扩大用于空间或东西变大，体重的增长要说增加。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8a17325-c333-4116-93cf-78505131cfb7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25572, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "扩大", "is_correct": true, "explanation": "墙上的裂缝慢慢扩大，表示裂缝变宽，符合慢慢变化的语境。"}, {"text": "微笑", "is_correct": false, "explanation": "语义：微笑是人的表情，裂缝不能微笑。"}, {"text": "叫喊", "is_correct": false, "explanation": "语义：叫喊的主体是能发声的人或动物，裂缝不能叫喊。"}, {"text": "作曲", "is_correct": false, "explanation": "配价：作曲的对象是乐曲，裂缝不能作曲。"}], "explanations": {"扩大": "墙上的裂缝慢慢扩大，表示裂缝变宽，符合慢慢变化的语境。", "微笑": "语义：微笑是人的表情，裂缝不能微笑。", "叫喊": "语义：叫喊的主体是能发声的人或动物，裂缝不能叫喊。", "作曲": "配价：作曲的对象是乐曲，裂缝不能作曲。"}, "sentence_index": 6, "correct_answer": "扩大"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家餐厅正在扩大服务质量，让客人更满意。", "explanation": "这里应该用〈提升〉。扩大指空间或东西变大，服务质量的提高要说提升。"}, {"text": "他们之间的感情扩大了很多。", "explanation": "这里应该用〈加深〉。扩大指东西变大，感情的深化要说加深。"}, {"text": "这个团队扩大了工作进度，大家都很高兴。", "explanation": "这里应该用〈加快〉。扩大指范围变大，进度的加快要说加快。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8a17325-c333-4116-93cf-78505131cfb7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25572, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这间屋子太挤，我们它扩大了一些。", "corrected_sentence": "这间屋子太挤，我们把它扩大了一些。", "error_description": "错误：缺少“把”字。处置对象“它”要由“把”引出，应说“把它扩大了一些”；“我们它扩大了”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8a17325-c333-4116-93cf-78505131cfb7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25572, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "湖面在雨后扩大地很快。", "corrected_sentence": "湖面在雨后扩大得很快。", "error_description": "错误：补语标记用错。“扩大”后表示程度的补语要用“得”，不能用状语标记“地”；应说“扩大得很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8a17325-c333-4116-93cf-78505131cfb7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
