INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25574, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用来比较两个东西谁大谁小，或者谁和谁一样。", "primary_collocate": null, "pronunciation": "bǐ", "ipa": "pi˨˩˦", "syllable_count": 1, "sentences": [{"text": "我们来比一比，谁跑得快。", "target_word": "比", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这两件衣服，你比比看哪件好。", "target_word": "比", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我和哥哥比身高，他高一点。", "target_word": "比", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两个孩子在比谁的力气大。", "target_word": "比", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "把两张画放在一起比一比，你就知道了。", "target_word": "比", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这两个箱子一样大，不用再比了。", "target_word": "比", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们比谁吃得多，结果吃了五个。", "target_word": "比", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "买手机以前，我先比了比几家店的价钱。", "target_word": "比", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这两个人太不一样，没法比。", "target_word": "比", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小朋友们把手放在一起，比着看谁的大。", "target_word": "比", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "比比", "label": "重叠"}, {"form": "比了", "label": "体标（了）"}, {"form": "比过", "label": "体标（过）"}], "register": "口语", "sense_fingerprint": "动词，把两个东西放在一起，看谁大谁小或是否一样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cec2e43-2775-454a-9511-b4b696244bdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25574, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "比", "is_correct": true, "explanation": "bǐ（第三声）表示比较两者，是正确答案。"}, {"text": "饼", "is_correct": false, "explanation": "bǐng 比 bǐ 多了韵尾 ng，意思是饼。"}, {"text": "壁", "is_correct": false, "explanation": "bì（第四声）与 bǐ（第三声）声调不同，意思是墙壁。"}, {"text": "币", "is_correct": false, "explanation": "bì（第四声）与 bǐ（第三声）声调不同，意思是钱币。"}, {"text": "底", "is_correct": false, "explanation": "dǐ 与 bǐ 声母不同（d 与 b），意思是底部。"}], "explanations": {"比": "bǐ（第三声）表示比较两者，是正确答案。", "饼": "bǐng 比 bǐ 多了韵尾 ng，意思是饼。", "壁": "bì（第四声）与 bǐ（第三声）声调不同，意思是墙壁。", "币": "bì（第四声）与 bǐ（第三声）声调不同，意思是钱币。", "底": "dǐ 与 bǐ 声母不同（d 与 b），意思是底部。"}, "sentence_index": null, "correct_answer": "比"}, "level_3": {"options": [{"text": "比", "is_correct": true, "explanation": "“比”是动词，“我们来比一比”表示较量，句子成立。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”表示发出歌声，不能表示较量谁跑得快。"}, {"text": "跳", "is_correct": false, "explanation": "语义：“跳”表示腾跃，不能表示较量谁跑得快。"}, {"text": "数", "is_correct": false, "explanation": "语义：“数”表示计数，不表示比较两人的快慢。"}], "explanations": {"比": "“比”是动词，“我们来比一比”表示较量，句子成立。", "唱": "语义：“唱”表示发出歌声，不能表示较量谁跑得快。", "跳": "语义：“跳”表示腾跃，不能表示较量谁跑得快。", "数": "语义：“数”表示计数，不表示比较两人的快慢。"}, "sentence_index": 0, "correct_answer": "比"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我比他买了一本书。", "explanation": "这里应该用〈给〉。“给”引出受益的人，表示为别人做事；“比”表示比较，不能用来引出受益的人。这句把“给他买”的“给”换成了“比”。"}, {"text": "我比老师谈了一个小时。", "explanation": "这里应该用〈跟〉。“比”表示比较，不能表示与人一起做某事，“跟老师谈”才对。"}, {"text": "我比了你半个小时。", "explanation": "这里应该用〈等〉。“比”表示比较，不能表示等待。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8a17325-c333-4116-93cf-78505131cfb7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25574, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "比", "is_correct": true, "explanation": "bǐ（第三声）表示比较两者大小，是正确答案。"}, {"text": "必", "is_correct": false, "explanation": "bì（第四声）与 bǐ（第三声）声调不同，意思是必须。"}, {"text": "闭", "is_correct": false, "explanation": "bì（第四声）与 bǐ（第三声）声调不同，意思是关闭。"}, {"text": "鼻", "is_correct": false, "explanation": "bí（第二声）与 bǐ（第三声）声调不同，意思是鼻子。"}, {"text": "米", "is_correct": false, "explanation": "mǐ 与 bǐ 声母不同（m 与 b），意思是米。"}], "explanations": {"比": "bǐ（第三声）表示比较两者大小，是正确答案。", "必": "bì（第四声）与 bǐ（第三声）声调不同，意思是必须。", "闭": "bì（第四声）与 bǐ（第三声）声调不同，意思是关闭。", "鼻": "bí（第二声）与 bǐ（第三声）声调不同，意思是鼻子。", "米": "mǐ 与 bǐ 声母不同（m 与 b），意思是米。"}, "sentence_index": null, "correct_answer": "比"}, "level_3": {"options": [{"text": "比", "is_correct": true, "explanation": "“比”是动词，“他们比谁吃得多”表示比较，句子成立。"}, {"text": "穿", "is_correct": false, "explanation": "配价：「穿」的宾语是衣物，不能接「谁吃得多」这样的小句。"}, {"text": "赢", "is_correct": false, "explanation": "配价：“赢”后面要接对手或奖项，不能直接接“谁吃得多”这样的小句。"}, {"text": "送", "is_correct": false, "explanation": "配价：“送”要带受事和接受者，后面不能接“谁吃得多”。"}], "explanations": {"比": "“比”是动词，“他们比谁吃得多”表示比较，句子成立。", "穿": "配价：「穿」的宾语是衣物，不能接「谁吃得多」这样的小句。", "赢": "配价：“赢”后面要接对手或奖项，不能直接接“谁吃得多”这样的小句。", "送": "配价：“送”要带受事和接受者，后面不能接“谁吃得多”。"}, "sentence_index": 6, "correct_answer": "比"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我比老师问好。", "explanation": "这里应该用〈向〉。“向”引出问候的对象，“比”表示比较，不能用来问候。"}, {"text": "我比汉语有兴趣。", "explanation": "这里应该用〈对〉。“对”引出感兴趣的对象，“比”表示比较，不能引出感兴趣的对象。"}, {"text": "我们比规定办事。", "explanation": "这里应该用〈按照〉。“按照”表示依据，“比”表示比较，不能引出办事的依据。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8a17325-c333-4116-93cf-78505131cfb7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25574, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两个人在谁比先到终点。", "corrected_sentence": "两个人在比谁先到终点。", "error_description": "错误形式：“在谁比先到终点”；正确形式：“在比谁先到终点”。动词“比”后面要紧接宾语“谁先到终点”，“比”和“谁”的位置不能颠倒。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8a17325-c333-4116-93cf-78505131cfb7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25574, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们比一个谁先写完。", "corrected_sentence": "我们比一下谁先写完。", "error_description": "错误形式：“比一个”；正确形式：“比一下”。“比”表示试着较量一次，动量词要用“一下”，不能用量词“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8a17325-c333-4116-93cf-78505131cfb7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
