INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25576, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容事情很难，让人感到紧张。", "primary_collocate": null, "pronunciation": "yán jùn", "ipa": "jɛn˧˥ tɕyn˥˩", "syllable_count": 2, "sentences": [{"text": "今年的就业形势很严峻。", "target_word": "严峻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说他的病情非常严峻。", "target_word": "严峻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们面临着严峻的考验。", "target_word": "严峻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气变冷后，山区的情况更严峻了。", "target_word": "严峻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司现在的情况十分严峻。", "target_word": "严峻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对严峻的挑战，我们不能放松。", "target_word": "严峻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济问题越来越严峻。", "target_word": "严峻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水资源不足的问题很严峻。", "target_word": "严峻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在的环境问题比以前更严峻。", "target_word": "严峻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事情比我想的严峻，我们得马上想办法。", "target_word": "严峻", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "严峻起来", "label": "起始"}, {"form": "严峻了", "label": "完成体"}], "register": "中性", "sense_fingerprint": "形势、问题等困难而让人紧张", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af672a29-e1eb-4780-8f57-35ac2a0384e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25576, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "严峻", "is_correct": true, "explanation": "正确：“形势很严峻”指局面困难、让人紧张，语境相符。"}, {"text": "勇敢", "is_correct": false, "explanation": "语义：“勇敢”形容人的品质，不能用来形容形势。"}, {"text": "柔软", "is_correct": false, "explanation": "语义：“柔软”形容质地，不用来形容形势。"}, {"text": "甜", "is_correct": false, "explanation": "搭配：“甜”形容味道，不能用来形容形势。"}], "explanations": {"严峻": "正确：“形势很严峻”指局面困难、让人紧张，语境相符。", "勇敢": "语义：“勇敢”形容人的品质，不能用来形容形势。", "柔软": "语义：“柔软”形容质地，不用来形容形势。", "甜": "搭配：“甜”形容味道，不能用来形容形势。"}, "sentence_index": 0, "correct_answer": "严峻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间屋子很严峻，大家都说很温馨。", "explanation": "这里应该用〈温馨〉。“严峻”形容局势或神情，不能形容屋子的氛围；形容屋子舒适温暖要用“温馨”。"}, {"text": "院子里的花很严峻，大家都来拍照。", "explanation": "这里应该用〈美丽〉。“严峻”形容形势或神色，不能用来形容花的样子，夸花好看要用“美丽”。"}, {"text": "这件衣服的颜色很严峻，我很喜欢。", "explanation": "这里应该用〈漂亮〉。“严峻”形容形势、问题困难紧张，不能形容衣服的颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4626a58c-eb93-4819-bf7d-f85fcc0a7cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25576, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "严峻", "is_correct": true, "explanation": "正确：“越来越严峻”说明经济问题日益紧迫，语境相符。"}, {"text": "温柔", "is_correct": false, "explanation": "语义：“温柔”形容性情，不能用来形容经济问题。"}, {"text": "宽阔", "is_correct": false, "explanation": "语义：“宽阔”形容空间，与经济问题无关。"}, {"text": "香", "is_correct": false, "explanation": "搭配：“香”形容气味或味道，不能用于形容问题。"}], "explanations": {"严峻": "正确：“越来越严峻”说明经济问题日益紧迫，语境相符。", "温柔": "语义：“温柔”形容性情，不能用来形容经济问题。", "宽阔": "语义：“宽阔”形容空间，与经济问题无关。", "香": "搭配：“香”形容气味或味道，不能用于形容问题。"}, "sentence_index": 6, "correct_answer": "严峻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈做的菜很严峻，大家都吃光了。", "explanation": "这里应该用〈好吃〉。“严峻”形容局势或神情，不能形容菜的味道，夸菜好吃要用“好吃”。"}, {"text": "考试前，我心里很严峻。", "explanation": "这里应该用〈紧张〉。“严峻”形容局势，心里的紧张要用“紧张”。"}, {"text": "这个笑话很严峻，大家都笑了起来。", "explanation": "这里应该用〈幽默〉。“严峻”不能形容笑话的风格，笑话要用“幽默”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4626a58c-eb93-4819-bf7d-f85fcc0a7cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25576, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "面对严峻地形势，大家要更努力。", "corrected_sentence": "面对严峻的形势，大家要更努力。", "error_description": "「严峻地形势」错误。形容词修饰名词要用“的”，“地”用于修饰动词，正确为「严峻的形势」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4626a58c-eb93-4819-bf7d-f85fcc0a7cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25576, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个问题严峻地起来了，我们要马上行动。", "corrected_sentence": "这个问题严峻起来了，我们要马上行动。", "error_description": "「严峻地起来」错误。“起来”是补语，形容词与“起来”之间不加“地”，正确为「严峻起来了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4626a58c-eb93-4819-bf7d-f85fcc0a7cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
