INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25578, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "一个小东西粘在另一个东西上面，很难分开。", "primary_collocate": null, "pronunciation": "fù zhuó", "ipa": "fu˥˩ ʈʂuo˧˥", "syllable_count": 2, "sentences": [{"text": "小贝壳紧紧附着在石头上。", "target_word": "附着", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一片树叶附着在车窗上，怎么也吹不掉。", "target_word": "附着", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "口香糖附着在鞋底，很难弄下来。", "target_word": "附着", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小虫子附着在玻璃上，一动也不动。", "target_word": "附着", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一只小蚂蚁附着在他的袖子上，怎么也甩不掉。", "target_word": "附着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张小贴纸附着在书上，撕不下来。", "target_word": "附着", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "鱼身上附着一些白色的小点。", "target_word": "附着", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蜗牛附着在墙上，慢慢往上爬。", "target_word": "附着", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨后，一些泥土附着在他的鞋底上，很难擦干净。", "target_word": "附着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小螃蟹附着在船边的木头上。", "target_word": "附着", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "附着了", "label": "体标（了）"}, {"form": "附着力", "label": "复合词"}, {"form": "附着物", "label": "复合词"}], "register": "书面", "sense_fingerprint": "小东西粘在别的东西上面，很难分开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cec2e43-2775-454a-9511-b4b696244bdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25578, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "附着", "is_correct": true, "explanation": "小贝壳紧紧附着在石头上，表示小东西粘得很牢，符合句意。"}, {"text": "跳", "is_correct": false, "explanation": "语义：贝壳不能跳，与紧紧粘住石头的意思不合。"}, {"text": "唱", "is_correct": false, "explanation": "配价：唱需要歌曲等宾语，不能说唱在石头上。"}, {"text": "吹", "is_correct": false, "explanation": "语义：吹指用气流推动，贝壳不会因被吹而粘在石头上。"}], "explanations": {"附着": "小贝壳紧紧附着在石头上，表示小东西粘得很牢，符合句意。", "跳": "语义：贝壳不能跳，与紧紧粘住石头的意思不合。", "唱": "配价：唱需要歌曲等宾语，不能说唱在石头上。", "吹": "语义：吹指用气流推动，贝壳不会因被吹而粘在石头上。"}, "sentence_index": 0, "correct_answer": "附着"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他从不附着父母生活，凡事都靠自己。", "explanation": "这里应该用〈依附〉。附着指小东西粘在物体表面，靠他人生活要用依附。"}, {"text": "一头大象附着在树下，慢慢睡着了。", "explanation": "这里应该用〈躺〉。附着指小东西粘在物体上，大象休息要说躺。"}, {"text": "这座大楼附着在河边，很高大。", "explanation": "这里应该用〈矗立〉。附着指小东西粘在物体表面，大楼是固定矗立，不能说附着。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8a17325-c333-4116-93cf-78505131cfb7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25578, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "附着", "is_correct": true, "explanation": "鱼身上附着一些白色的小点，表示小点粘在鱼身上，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：吃的动作要求宾语是食物，白色的小点不能被吃在鱼身上。"}, {"text": "闻", "is_correct": false, "explanation": "语义：闻是嗅觉动作，与小点粘在鱼身上的意思不符。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：穿用于衣物鞋袜，不能与白色的小点搭配。"}], "explanations": {"附着": "鱼身上附着一些白色的小点，表示小点粘在鱼身上，符合句意。", "吃": "语义：吃的动作要求宾语是食物，白色的小点不能被吃在鱼身上。", "闻": "语义：闻是嗅觉动作，与小点粘在鱼身上的意思不符。", "穿": "搭配：穿用于衣物鞋袜，不能与白色的小点搭配。"}, "sentence_index": 6, "correct_answer": "附着"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小鸟附着在树枝上，唱了一首歌。", "explanation": "这里应该用〈停〉。附着指小东西粘在物体表面、难以分开，小鸟停在树枝上不是黏附。"}, {"text": "妈妈附着毛巾，跑去开门了。", "explanation": "这里应该用〈拿〉。附着是不及物的，指小东西粘在物体上，不能直接带“毛巾”作宾语表示拿着。"}, {"text": "老人附着拐杖慢慢走。", "explanation": "这里应该用〈拄〉。附着指小东西粘在物体上，人拿拐杖走路要说拄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8a17325-c333-4116-93cf-78505131cfb7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25578, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一只小蜘蛛附着着在窗角上，一动不动。", "corrected_sentence": "一只小蜘蛛附着在窗角上，一动不动。", "error_description": "错误：多了一个“着”。“附着”本身就是一个词，后面直接接“在……上”，不能再加体标“着”，应说“附着在窗角上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8a17325-c333-4116-93cf-78505131cfb7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25578, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "蜗牛附着树干上，爬得很慢。", "corrected_sentence": "蜗牛附着在树干上，爬得很慢。", "error_description": "错误：「附着」后缺少介词「在」。应说「附着在树干上」，不能直接接名词「树干上」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8a17325-c333-4116-93cf-78505131cfb7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25580, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "微小", "is_correct": true, "explanation": "「微小」与「巨大」在体积或程度上相对，构成反义关系。"}, {"text": "美丽", "is_correct": false, "explanation": "「美丽」形容外观的好看，与「巨大」在体积或程度上没有对立关系。"}, {"text": "寒冷", "is_correct": false, "explanation": "「寒冷」形容温度，与「巨大」不构成反义。"}, {"text": "清楚", "is_correct": false, "explanation": "「清楚」形容明晰，与「巨大」没有反义关系。"}], "correct_answer": "微小", "explanations": {"微小": "「微小」与「巨大」在体积或程度上相对，构成反义关系。", "美丽": "「美丽」形容外观的好看，与「巨大」在体积或程度上没有对立关系。", "寒冷": "「寒冷」形容温度，与「巨大」不构成反义。", "清楚": "「清楚」形容明晰，与「巨大」没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82282c0f-c852-4e81-8345-ad24bbafabfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25580, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "微小", "is_correct": true, "explanation": "「微小」与「巨大」在体积或程度上相对，构成反义关系。"}, {"text": "轻松", "is_correct": false, "explanation": "「轻松」形容负担或心情，与「巨大」没有反义关系。"}, {"text": "坚硬", "is_correct": false, "explanation": "「坚硬」形容质地，与「巨大」不构成反义。"}, {"text": "温暖", "is_correct": false, "explanation": "「温暖」形容温度或感受，与「巨大」无反义关系。"}], "correct_answer": "微小", "explanations": {"微小": "「微小」与「巨大」在体积或程度上相对，构成反义关系。", "轻松": "「轻松」形容负担或心情，与「巨大」没有反义关系。", "坚硬": "「坚硬」形容质地，与「巨大」不构成反义。", "温暖": "「温暖」形容温度或感受，与「巨大」无反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82282c0f-c852-4e81-8345-ad24bbafabfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25580, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "很大很大，比一般的东西大很多。", "primary_collocate": null, "pronunciation": "jù dà", "ipa": "tɕy˥˩ ta˥˩", "syllable_count": 2, "sentences": [{"text": "海里有一条巨大的鱼。", "target_word": "巨大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林里有一棵巨大的树。", "target_word": "巨大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛对他的影响巨大。", "target_word": "巨大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的城市这几年变化巨大。", "target_word": "巨大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里有一个巨大的湖。", "target_word": "巨大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在工作中遇到了巨大的困难。", "target_word": "巨大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈为我付出了巨大的努力。", "target_word": "巨大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山前有一块巨大的石头。", "target_word": "巨大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天空中传来巨大的响声。", "target_word": "巨大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个体育馆里有一个巨大的屏幕。", "target_word": "巨大", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "体积、规模、程度非常大", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61123057-4989-4a95-82bf-725897152c51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25580, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "滚烫", "is_correct": false, "explanation": "语义：海水不会滚烫，「滚烫的鱼」与句子的海洋环境相矛盾。"}, {"text": "抽象", "is_correct": false, "explanation": "语义：「抽象」指不具体，而鱼是具体的事物，不能说「抽象的鱼」。"}, {"text": "巨大", "is_correct": true, "explanation": "「巨大」形容体积很大，修饰「鱼」，符合句意。"}, {"text": "吵闹", "is_correct": false, "explanation": "搭配：「吵闹」多用于声音或人群，不能用来修饰鱼。"}], "explanations": {"滚烫": "语义：海水不会滚烫，「滚烫的鱼」与句子的海洋环境相矛盾。", "抽象": "语义：「抽象」指不具体，而鱼是具体的事物，不能说「抽象的鱼」。", "巨大": "「巨大」形容体积很大，修饰「鱼」，符合句意。", "吵闹": "搭配：「吵闹」多用于声音或人群，不能用来修饰鱼。"}, "sentence_index": 0, "correct_answer": "巨大"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这几年，我们的城市吸引了巨大游客。", "explanation": "这里应该用〈大量〉。「巨大」说事物的体积或程度大，说人数多要用「大量」。"}, {"text": "这家工厂今年招来了巨大新工人。", "explanation": "这里应该用〈大批〉。「巨大」描述体积或程度，表示人数多要用「大批」。"}, {"text": "他的脾气很巨大。", "explanation": "这里应该用〈暴躁〉。「巨大」说体积或程度，形容脾气要用「暴躁」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82282c0f-c852-4e81-8345-ad24bbafabfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25580, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "圆形", "is_correct": false, "explanation": "语义：「圆形」描述形状，不能修饰「努力」，句子不通。"}, {"text": "冰凉", "is_correct": false, "explanation": "语义：「冰凉」形容温度，不能修饰「努力」，与句意不符。"}, {"text": "矮小", "is_correct": false, "explanation": "体貌：「矮小」形容身材或个头，不能用来修饰抽象的「努力」。"}, {"text": "巨大", "is_correct": true, "explanation": "「巨大」形容程度很高，修饰「努力」，符合句意。"}], "explanations": {"圆形": "语义：「圆形」描述形状，不能修饰「努力」，句子不通。", "冰凉": "语义：「冰凉」形容温度，不能修饰「努力」，与句意不符。", "矮小": "体貌：「矮小」形容身材或个头，不能用来修饰抽象的「努力」。", "巨大": "「巨大」形容程度很高，修饰「努力」，符合句意。"}, "sentence_index": 6, "correct_answer": "巨大"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她做事很巨大。", "explanation": "这里应该用〈细致〉。「巨大」说体积或程度大，形容做事认真要用「细致」。"}, {"text": "他巨大地喊道：「快跑！」", "explanation": "这里应该用〈大声〉。「巨大」不用来说明声音的大小，表示声音大要用「大声」。"}, {"text": "这位巨大的科学家获得了诺贝尔奖。", "explanation": "这里应该用〈伟大〉。「巨大」说体积或程度，评价人的成就要用「伟大」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82282c0f-c852-4e81-8345-ad24bbafabfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25580, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次地震造成了巨大地损失。", "corrected_sentence": "这次地震造成了巨大的损失。", "error_description": "「巨大」修饰名词「损失」时应用助词「的」，写成「地」是误用：「地」用来修饰动词，不能修饰名词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82282c0f-c852-4e81-8345-ad24bbafabfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25580, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的进步很非常巨大。", "corrected_sentence": "他的进步非常巨大。", "error_description": "程度副词叠用：「非常」与「很」都表示程度，不能同时修饰「巨大」，应只用「非常」，说「非常巨大」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82282c0f-c852-4e81-8345-ad24bbafabfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
