INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25588, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "纳米是很小很小的长度单位，比头发丝还要小很多很多。", "primary_collocate": null, "pronunciation": "nà mǐ", "ipa": "na˥˩ mi˨˩˦", "syllable_count": 2, "sentences": [{"text": "一纳米比头发丝细得多。", "target_word": "纳米", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "纳米是很小很小的长度单位。", "target_word": "纳米", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "灰尘比一纳米大得多。", "target_word": "纳米", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "一根头发有好几万纳米那么粗。", "target_word": "纳米", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小东西只有几纳米大。", "target_word": "纳米", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "眼睛看不到纳米大小的东西。", "target_word": "纳米", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "用纳米来量，能测出很小东西的大小。", "target_word": "纳米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥问我：“纳米有多小？”", "target_word": "纳米", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师用头发丝来讲纳米有多小。", "target_word": "纳米", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书上说纳米比一粒沙子小得多。", "target_word": "纳米", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "纳米技术", "label": "复合词"}, {"form": "纳米材料", "label": "复合词"}, {"form": "纳米级", "label": "复合词"}, {"form": "納米", "label": "繁体"}], "register": "中性", "sense_fingerprint": "极小的长度单位，比头发丝小得多", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29ae13fa-e2f6-4de8-a72a-3575f717bdf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25588, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "纳米", "is_correct": true, "explanation": "“纳米”是极小的长度单位，与“一……比头发丝细得多”相合。"}, {"text": "纬度", "is_correct": false, "explanation": "语义：“纬度”是地理坐标，不能用来比较粗细。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”不能用来比较头发丝的粗细。"}, {"text": "分贝", "is_correct": false, "explanation": "语义：“分贝”是声音强度单位，与粗细无关。"}], "explanations": {"纳米": "“纳米”是极小的长度单位，与“一……比头发丝细得多”相合。", "纬度": "语义：“纬度”是地理坐标，不能用来比较粗细。", "体重": "搭配：“体重”不能用来比较头发丝的粗细。", "分贝": "语义：“分贝”是声音强度单位，与粗细无关。"}, "sentence_index": 0, "correct_answer": "纳米"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这袋面粉重三纳米。", "explanation": "这里应该用〈千克〉。“纳米”是长度单位，不能用来表示重量。"}, {"text": "我存的钱有好几万纳米。", "explanation": "这里应该用〈元〉。“纳米”是长度单位，不能用来计算钱数。"}, {"text": "这颗灰尘的年龄有几百纳米。", "explanation": "这里应该用〈岁〉。“纳米”是长度单位，不能用来说年龄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '359c172d-3f8c-4869-8425-155c116d2b2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25588, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "纳米", "is_correct": true, "explanation": "“用纳米来量”指用纳米这个单位测量，与“能测出很小东西的大小”相合。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不能用尺子一类的单位来量。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音不能用来测量很小东西的大小。"}, {"text": "香味", "is_correct": false, "explanation": "搭配：“香味”不能用来量，与“测出大小”的语境不符。"}], "explanations": {"纳米": "“用纳米来量”指用纳米这个单位测量，与“能测出很小东西的大小”相合。", "颜色": "语义：颜色不能用尺子一类的单位来量。", "声音": "语义：声音不能用来测量很小东西的大小。", "香味": "搭配：“香味”不能用来量，与“测出大小”的语境不符。"}, "sentence_index": 6, "correct_answer": "纳米"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个路程有三纳米长。", "explanation": "这里应该用〈公里〉。“纳米”只用于很小的长度，不能说路程。"}, {"text": "这次旅行用了三纳米的时间。", "explanation": "这里应该用〈天〉或〈小时〉。“纳米”是长度单位，不能用来计时间。"}, {"text": "这件衣服比一纳米贵得多。", "explanation": "这里应该用〈一块钱〉。“纳米”是长度单位，不能用来比较价钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '359c172d-3f8c-4869-8425-155c116d2b2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25588, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这颗灰尘只有几百纳米重。", "corrected_sentence": "这颗灰尘只有几百纳米大。", "error_description": "错误形式是“纳米重”。“纳米”是长度单位，不能用来说重量，应为“几百纳米大”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '359c172d-3f8c-4869-8425-155c116d2b2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25588, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种颗粒比一纳米重得多。", "corrected_sentence": "这种颗粒比一纳米大得多。", "error_description": "错误形式是“重得多”。“纳米”是长度单位，只能比大小长短，不能比轻重，应为“大得多”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '359c172d-3f8c-4869-8425-155c116d2b2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
