INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25590, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "鸿沟是很大的不同，就像一条大河把两边分开了。", "primary_collocate": null, "pronunciation": "hóng gōu", "ipa": "xʊŋ˧˥ kou˥˥", "syllable_count": 2, "sentences": [{"text": "他们的想法不同，中间有一条鸿沟。", "target_word": "鸿沟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸和我之间好像有一道鸿沟。", "target_word": "鸿沟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市和农村的生活水平存在着巨大的鸿沟。", "target_word": "鸿沟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想和他做朋友，但年龄是一道鸿沟。", "target_word": "鸿沟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要缩小大家之间的鸿沟，先要多说话。", "target_word": "鸿沟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们之间的鸿沟，不是一天形成的。", "target_word": "鸿沟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习成绩的鸿沟让这个孩子很难过。", "target_word": "鸿沟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两种看法之间有一条很深的鸿沟。", "target_word": "鸿沟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们用笑容填平了彼此之间的鸿沟。", "target_word": "鸿沟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说不同的语言，会在人们之间留下鸿沟。", "target_word": "鸿沟", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一道鸿沟", "label": "量词"}, {"form": "一条鸿沟", "label": "量词"}, {"form": "鴻溝", "label": "繁体"}], "register": "中性", "sense_fingerprint": "很大的不同，像大河把两边分开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a971fff3-3f38-4644-95c3-97611e42646a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25590, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "鸿沟", "is_correct": true, "explanation": "鸿沟指很大的不同，与“想法不同”的语境相符。"}, {"text": "绳子", "is_correct": false, "explanation": "语义：绳子是拴东西的器物，不是想法上的不同，“中间有一条绳子”不能指分歧。"}, {"text": "项链", "is_correct": false, "explanation": "语义：项链是首饰，与想法上的分歧无关，句子不通。"}, {"text": "围巾", "is_correct": false, "explanation": "语义：围巾是保暖的衣物，与想法上的差异无关，句子不通。"}], "explanations": {"鸿沟": "鸿沟指很大的不同，与“想法不同”的语境相符。", "绳子": "语义：绳子是拴东西的器物，不是想法上的不同，“中间有一条绳子”不能指分歧。", "项链": "语义：项链是首饰，与想法上的分歧无关，句子不通。", "围巾": "语义：围巾是保暖的衣物，与想法上的差异无关，句子不通。"}, "sentence_index": 0, "correct_answer": "鸿沟"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两个苹果大小有点儿鸿沟。", "explanation": "这里应该用〈差别〉。鸿沟指很大的不同，“有点儿”说的是很小的不同，应说有点儿差别。"}, {"text": "我家到他家有三公里的鸿沟。", "explanation": "这里应该用〈距离〉。“三公里”是距离的计量单位，鸿沟指抽象的差异，不能用公里计算。"}, {"text": "这次考试，我和他之间的鸿沟只有一分。", "explanation": "这里应该用〈差距〉。鸿沟指很大的不同，只差一分是很小的差别，应说差距。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55cb5a59-d6da-4a09-a18c-bdac56c1a581') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25590, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "鸿沟", "is_correct": true, "explanation": "鸿沟指很大的不同或隔阂，作主语与“让这个孩子很难过”相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是成绩之间的差异，“学习成绩的天气”说不通。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：饮料是喝的东西，与学习成绩上的差别无关，句子不通。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语，指东西或事物，与书面叙述不协调，也不能表示成绩之间的差异。"}], "explanations": {"鸿沟": "鸿沟指很大的不同或隔阂，作主语与“让这个孩子很难过”相符。", "天气": "语义：天气不是成绩之间的差异，“学习成绩的天气”说不通。", "饮料": "语义：饮料是喝的东西，与学习成绩上的差别无关，句子不通。", "玩意儿": "语域：“玩意儿”是口语，指东西或事物，与书面叙述不协调，也不能表示成绩之间的差异。"}, "sentence_index": 6, "correct_answer": "鸿沟"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们终于把彼此之间的鸿沟解开了。", "explanation": "这里应该用〈误会〉。“解开”用于误会、疙瘩，鸿沟表示很大的不同，不能被解开。"}, {"text": "这场争论中，双方的鸿沟越来越激化。", "explanation": "这里应该用〈矛盾〉。“激化”用于矛盾、冲突，鸿沟表示很大的不同，不会激化。"}, {"text": "他们要和过去划清鸿沟。", "explanation": "这里应该用〈界限〉。“划清”搭配界限，鸿沟表示很大的不同，不能被划清。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55cb5a59-d6da-4a09-a18c-bdac56c1a581') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25590, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次交流缩小了两家人之间的一颗鸿沟。", "corrected_sentence": "这次交流缩小了两家人之间的一道鸿沟。", "error_description": "量词用错：鸿沟是抽象的隔阂，应该用“道”，“颗”用于圆粒状的东西，不能用来计量鸿沟。正确的说法是“这次交流缩小了两家人之间的一道鸿沟”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55cb5a59-d6da-4a09-a18c-bdac56c1a581') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25590, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两代人之间有一只很深的鸿沟。", "corrected_sentence": "两代人之间有一道很深的鸿沟。", "error_description": "量词用错：“只”用于动物等，不能用来计量鸿沟；鸿沟应该用“道”或“条”。正确的说法是“两代人之间有一道很深的鸿沟”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55cb5a59-d6da-4a09-a18c-bdac56c1a581') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
