INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25600, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "身体里没有足够的氧气。", "primary_collocate": null, "pronunciation": "quē yǎng", "ipa": "tɕʰɥe˥ jaŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "跑得太快，我觉得有点缺氧。", "target_word": "缺氧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "坐在闷热的车里，孩子缺氧了。", "target_word": "缺氧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在高山上缺氧，走不动了。", "target_word": "缺氧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "缺氧的时候，人会头晕。", "target_word": "缺氧", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "游泳时憋气太久，身体会缺氧。", "target_word": "缺氧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人在人多的地方容易缺氧。", "target_word": "缺氧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她缺氧晕倒了，大家马上叫医生。", "target_word": "缺氧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山太高了，很多人都会缺氧。", "target_word": "缺氧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "睡觉时门窗关着，人也可能缺氧。", "target_word": "缺氧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的脸发白，好像是缺氧了。", "target_word": "缺氧", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "缺氧了", "label": "体标"}, {"form": "缺氧症", "label": "复合"}], "register": "中性", "sense_fingerprint": "身体里氧气不够", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d854d00-1f88-4c3f-9c27-9bef55911eec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25600, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "缺氧", "is_correct": true, "explanation": "正确。原句“跑得太快，我觉得有点缺氧”，跑步后身体缺氧。"}, {"text": "降温", "is_correct": false, "explanation": "搭配：“降温”多用于环境或温度，不能说人“有点降温”。"}, {"text": "睡着", "is_correct": false, "explanation": "语义：“睡着”与跑步后的身体状态不符，跑得快不会让人马上睡着。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：跑步后身体发热，不会因此感冒，与原因不符。"}], "explanations": {"缺氧": "正确。原句“跑得太快，我觉得有点缺氧”，跑步后身体缺氧。", "降温": "搭配：“降温”多用于环境或温度，不能说人“有点降温”。", "睡着": "语义：“睡着”与跑步后的身体状态不符，跑得快不会让人马上睡着。", "感冒": "语义：跑步后身体发热，不会因此感冒，与原因不符。"}, "sentence_index": 0, "correct_answer": "缺氧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次谈话让我很缺氧，只想快点离开。", "explanation": "这里应该用〈窒息〉。缺氧指身体或环境缺少氧气，不能用来形容压抑的谈话。"}, {"text": "他的工作很缺氧，每天都觉得没意思。", "explanation": "这里应该用〈枯燥〉。缺氧指氧气不足，不能用来形容工作没意思，工作单调乏味要说枯燥。"}, {"text": "这家店的顾客很缺氧，经常没人。", "explanation": "这里应该用〈缺少〉。缺氧指氧气不足，店里顾客少要说缺少顾客。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3077faca-1268-451b-bb11-eb7906611bf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25600, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "缺氧", "is_correct": true, "explanation": "正确。原句“她缺氧晕倒了”，说明晕倒的原因是缺氧。"}, {"text": "安睡", "is_correct": false, "explanation": "语义：“安睡”与“晕倒”以及“大家马上叫医生”的紧急情境相矛盾。"}, {"text": "吃饱", "is_correct": false, "explanation": "语义：“吃饱”与晕倒、叫医生的情境无关，读起来不通。"}, {"text": "站立", "is_correct": false, "explanation": "搭配：“站立”不能直接与“晕倒”搭配，通常说“站着晕倒”。"}], "explanations": {"缺氧": "正确。原句“她缺氧晕倒了”，说明晕倒的原因是缺氧。", "安睡": "语义：“安睡”与“晕倒”以及“大家马上叫医生”的紧急情境相矛盾。", "吃饱": "语义：“吃饱”与晕倒、叫医生的情境无关，读起来不通。", "站立": "搭配：“站立”不能直接与“晕倒”搭配，通常说“站着晕倒”。"}, "sentence_index": 6, "correct_answer": "缺氧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他工作了一整天，已经很缺氧了。", "explanation": "这里应该用〈疲惫〉。缺氧指氧气不足，不能用来形容劳累后的状态。"}, {"text": "被老板骂了一顿，他心里很缺氧。", "explanation": "这里应该用〈憋屈〉。缺氧不能形容心里的委屈，那种不痛快要说憋屈。"}, {"text": "这道菜做得太干，吃起来很缺氧。", "explanation": "这里应该用〈干涩〉。缺氧指身体里没有足够的空气，形容食物口感要说干涩，不能用缺氧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3077faca-1268-451b-bb11-eb7906611bf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25600, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一口气跑了很远，现在有点被缺氧。", "corrected_sentence": "他一口气跑了很远，现在有点缺氧。", "error_description": "“缺氧”是不及物动词，不能加“被”构成被动句。应去掉“被”，写作“有点缺氧”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3077faca-1268-451b-bb11-eb7906611bf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25600, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医生把那个孩子缺氧了，需要马上吸氧。", "corrected_sentence": "医生说那个孩子缺氧了，需要马上吸氧。", "error_description": "错在把字句：“缺氧”是不及物动词，没有宾语，不能用“把”构成处置句。应改为“医生说那个孩子缺氧了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3077faca-1268-451b-bb11-eb7906611bf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
