INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25602, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "东西用完或人走之后，还剩下一点。", "primary_collocate": null, "pronunciation": "cán liú", "ipa": "tsʰan˨˩˦ ljoʊ˧˥", "syllable_count": 2, "sentences": [{"text": "瓶子里只残留了一点水。", "target_word": "残留", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "客人走后，屋里残留着饭菜的味道。", "target_word": "残留", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "锅里残留的汤已经凉了。", "target_word": "残留", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手上还残留着一点油。", "target_word": "残留", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃完饭，桌上残留着几粒米。", "target_word": "残留", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盘子里残留的米饭，他全吃完了。", "target_word": "残留", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她走了，杯底残留着一点咖啡。", "target_word": "残留", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杯子洗了很久，还是残留着茶的颜色。", "target_word": "残留", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "衣服上残留的香味很淡。", "target_word": "残留", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "冰箱里残留着一股鱼的味道。", "target_word": "残留", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "残留着", "label": "体标"}, {"form": "残留了", "label": "体标"}, {"form": "残留物", "label": "复合"}], "register": "中性", "sense_fingerprint": "东西用完或人走后剩下的一点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d854d00-1f88-4c3f-9c27-9bef55911eec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25602, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "残留", "is_correct": true, "explanation": "正确。原句“瓶子里只残留了一点水”，指用完后剩下的少量水。"}, {"text": "装满", "is_correct": false, "explanation": "语义：“装满”指装到满，与“只一点水”相矛盾。"}, {"text": "倒空", "is_correct": false, "explanation": "语义：“倒空”指全部倒出，与“只剩一点”相矛盾。"}, {"text": "充满", "is_correct": false, "explanation": "搭配：“充满”后接的多是抽象或气氛类宾语，不能直接接“一点水”。"}], "explanations": {"残留": "正确。原句“瓶子里只残留了一点水”，指用完后剩下的少量水。", "装满": "语义：“装满”指装到满，与“只一点水”相矛盾。", "倒空": "语义：“倒空”指全部倒出，与“只剩一点”相矛盾。", "充满": "搭配：“充满”后接的多是抽象或气氛类宾语，不能直接接“一点水”。"}, "sentence_index": 0, "correct_answer": "残留"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她结婚后残留在老家照顾父母。", "explanation": "这里应该用〈留〉。残留指物体用完后剩下的一点，不能用来说人留在某地。"}, {"text": "我的钥匙残留在了办公室里。", "explanation": "这里应该用〈丢〉。残留指用完或走后剩下的痕迹，钥匙遗失要说丢在某处。"}, {"text": "这个月只残留了三天假期。", "explanation": "这里应该用〈剩下〉。残留指物体用完后的痕迹，假期的剩余要说剩下。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3077faca-1268-451b-bb11-eb7906611bf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25602, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "残留", "is_correct": true, "explanation": "正确。原句“杯底残留着一点咖啡”，指人走后杯底剩下的少量咖啡。"}, {"text": "倒掉", "is_correct": false, "explanation": "语义：“倒掉”表示咖啡已被倒走，与“杯底还有一点”相矛盾。"}, {"text": "喝光", "is_correct": false, "explanation": "语义：“喝光”表示已经喝完，与杯底还有咖啡相矛盾。"}, {"text": "陪伴", "is_correct": false, "explanation": "搭配：“陪伴”的对象通常是人，不能用在咖啡这样的物品上。"}], "explanations": {"残留": "正确。原句“杯底残留着一点咖啡”，指人走后杯底剩下的少量咖啡。", "倒掉": "语义：“倒掉”表示咖啡已被倒走，与“杯底还有一点”相矛盾。", "喝光": "语义：“喝光”表示已经喝完，与杯底还有咖啡相矛盾。", "陪伴": "搭配：“陪伴”的对象通常是人，不能用在咖啡这样的物品上。"}, "sentence_index": 6, "correct_answer": "残留"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个小镇的人口残留得很快，几年就翻了一番。", "explanation": "这里应该用〈增长〉。残留指用完或剩下的一点，人口增多要说增长，不能用残留。"}, {"text": "行李残留在车站，等我来取。", "explanation": "这里应该用〈寄存〉。残留是用完后剩下，有意存放的行李要说寄存。"}, {"text": "这次会议残留了三个小时。", "explanation": "这里应该用〈持续〉。残留指剩下的一点，会议时间延续要说持续，不能用残留。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3077faca-1268-451b-bb11-eb7906611bf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25602, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "瓶底还残留在一点水。", "corrected_sentence": "瓶底还残留着一点水。", "error_description": "“残留”后面要用“着”。“在”表示处所，不能引出“一点水”，应写作“瓶底还残留着一点水”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3077faca-1268-451b-bb11-eb7906611bf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25602, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "屋里残留了着一股烟味。", "corrected_sentence": "屋里残留着一股烟味。", "error_description": "“残留”后面已经用“着”，不能再加“了”。应去掉“了”，写作“屋里残留着一股烟味”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3077faca-1268-451b-bb11-eb7906611bf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
