INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25604, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "可以给机器下命令，让它做事情。", "primary_collocate": null, "pronunciation": "kě biān chéng", "ipa": "kʰɤ˨˩ pjɛn˥ ʈʂʰɤŋ˧˥", "syllable_count": 3, "sentences": [{"text": "我家有一个可编程的小机器人。", "target_word": "可编程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个玩具车是可编程的，你可以教它走路。", "target_word": "可编程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥送我一台可编程的小火车。", "target_word": "可编程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个可编程的机器人会按你的命令跳舞。", "target_word": "可编程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说可编程的机器可以帮人做很多事。", "target_word": "可编程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台洗衣机不是可编程的，只能用一种方式洗。", "target_word": "可编程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在课上玩可编程的小汽车。", "target_word": "可编程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "可编程的机器人能给我们送水。", "target_word": "可编程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想买一个可编程的玩具，自己写命令。", "target_word": "可编程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种可编程的玩具狗会听你的命令。", "target_word": "可编程", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "可编程的", "label": "定语形式"}, {"form": "可編程", "label": "繁体"}], "register": "中性", "sense_fingerprint": "可给机器下命令让它做事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a971fff3-3f38-4644-95c3-97611e42646a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25604, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "可编程", "is_correct": true, "explanation": "可编程指可以给机器下命令让它做事，与“小机器人”相符。"}, {"text": "可食用", "is_correct": false, "explanation": "语义：可食用指能当食物吃，机器人不能被吃，句子说不通。"}, {"text": "可溶", "is_correct": false, "explanation": "语义：可溶指能溶解在液体里，与小机器人无关，句子不通。"}, {"text": "可燃", "is_correct": false, "explanation": "语义：可燃指能被点燃，与小机器人的功能无关，句子不通。"}], "explanations": {"可编程": "可编程指可以给机器下命令让它做事，与“小机器人”相符。", "可食用": "语义：可食用指能当食物吃，机器人不能被吃，句子说不通。", "可溶": "语义：可溶指能溶解在液体里，与小机器人无关，句子不通。", "可燃": "语义：可燃指能被点燃，与小机器人的功能无关，句子不通。"}, "sentence_index": 0, "correct_answer": "可编程"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那只小猫真可编程。", "explanation": "这里应该用〈可爱〉。“可编程”指可以给机器下命令，只用于机器，不能用来形容小猫。"}, {"text": "这场台风十分可编程。", "explanation": "这里应该用〈可怕〉。“可编程”指可以给机器下命令，台风是自然现象，不能被下命令。"}, {"text": "他是个可编程的人。", "explanation": "这里应该用〈可靠〉。“可编程”指可以给机器下命令，用来形容人不成立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55cb5a59-d6da-4a09-a18c-bdac56c1a581') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25604, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可编程", "is_correct": true, "explanation": "可编程指可以给机器下命令让它做事，与“小汽车”的语境相符。"}, {"text": "可过滤", "is_correct": false, "explanation": "语义：可过滤指能用滤网分离杂质，与玩小汽车无关，句子不通。"}, {"text": "可加热", "is_correct": false, "explanation": "语义：可加热指能放在火上加热，玩小汽车不需要加热，句子不通。"}, {"text": "可冷冻", "is_correct": false, "explanation": "语义：可冷冻指能放进冰箱保存，与在课上玩小汽车无关，句子不通。"}], "explanations": {"可编程": "可编程指可以给机器下命令让它做事，与“小汽车”的语境相符。", "可过滤": "语义：可过滤指能用滤网分离杂质，与玩小汽车无关，句子不通。", "可加热": "语义：可加热指能放在火上加热，玩小汽车不需要加热，句子不通。", "可冷冻": "语义：可冷冻指能放进冰箱保存，与在课上玩小汽车无关，句子不通。"}, "sentence_index": 6, "correct_answer": "可编程"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那个人的行踪可编程。", "explanation": "这里应该用〈可疑〉。“可编程”只用于能按命令设定功能的机器，不能说人的行踪。"}, {"text": "这笔收入可编程。", "explanation": "这里应该用〈可观〉。“可编程”指能设定功能，不能用来形容收入数量多。"}, {"text": "这次机会真可编程。", "explanation": "这里应该用〈可惜〉。“可编程”指能按命令设定功能，不表示遗憾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55cb5a59-d6da-4a09-a18c-bdac56c1a581') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25604, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台遥控车很可编程，能按指令行驶。", "corrected_sentence": "这台遥控车可编程，能按指令行驶。", "error_description": "程度副词用错：“可编程”不能用“很”修饰，应直接说“这台遥控车可编程”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55cb5a59-d6da-4a09-a18c-bdac56c1a581') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25604, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台机器人已经可编程着。", "corrected_sentence": "这台机器人已经可编程了。", "error_description": "动态助词用错：“已经”表示动作或变化已经完成，要用“了”，不能用“着”。正确的说法是“这台机器人已经可编程了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55cb5a59-d6da-4a09-a18c-bdac56c1a581') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25606, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5836933-6da4-40fd-b175-01f565777b70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25606, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5836933-6da4-40fd-b175-01f565777b70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25606, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指由同一微生物祖先繁殖得到的纯种微生物，科学家常用它来做实验。", "primary_collocate": null, "pronunciation": "jūn zhū", "ipa": "tɕyn˥ ʈʂu˥", "syllable_count": 2, "sentences": [{"text": "科学家用这个菌株做实验。", "target_word": "菌株", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "菌株太小了，只能用显微镜看。", "target_word": "菌株", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说这个菌株很安全。", "target_word": "菌株", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "实验前，要先把菌株培养好。", "target_word": "菌株", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰箱里的试管中保存着这个菌株。", "target_word": "菌株", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种菌株不会让人生病。", "target_word": "菌株", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "学生们观察了菌株的变化。", "target_word": "菌株", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每天给菌株换新的培养液。", "target_word": "菌株", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个菌株是实验室里最重要的材料。", "target_word": "菌株", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "菌株死了，实验只好重新做。", "target_word": "菌株", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个菌株", "label": "量词"}, {"form": "工程菌株", "label": "复合"}, {"form": "野生菌株", "label": "复合"}], "register": "书面", "sense_fingerprint": "由单一微生物繁殖得到、供实验用的纯种", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a662146-0fe1-4053-b97b-687a43040117') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25606, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "菌株", "is_correct": true, "explanation": "正确：菌株是科学家做实验时使用的微小生物，与“做实验”相符。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业不是做实验的材料，科学家不会用作业做实验。"}, {"text": "故事", "is_correct": false, "explanation": "语义：故事不是实验的材料，无法用来做实验。"}, {"text": "礼物", "is_correct": false, "explanation": "搭配：“做实验”的对象应是实验材料，“礼物”与之不搭配。"}], "explanations": {"菌株": "正确：菌株是科学家做实验时使用的微小生物，与“做实验”相符。", "作业": "语义：作业不是做实验的材料，科学家不会用作业做实验。", "故事": "语义：故事不是实验的材料，无法用来做实验。", "礼物": "搭配：“做实验”的对象应是实验材料，“礼物”与之不搭配。"}, "sentence_index": 0, "correct_answer": "菌株"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "厨房水槽的角落里长满了菌株。", "explanation": "这里应该用〈细菌〉。水槽角落里滋生的是一般细菌，菌株指从某一微生物中分离出的纯种，不能泛指。"}, {"text": "草地上长满了菌株。", "explanation": "这里应该用〈蘑菇〉。菌株是实验室里的微生物纯种，不指草地上长出的蘑菇。"}, {"text": "做面包要先把菌株揉成面团。", "explanation": "这里应该用〈面粉〉。菌株是微生物纯种，不能揉成面团；做面包要用面粉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5836933-6da4-40fd-b175-01f565777b70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25606, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "菌株", "is_correct": true, "explanation": "正确：菌株会随时间发生变化，学生可以观察到它的变化。"}, {"text": "圆周率", "is_correct": false, "explanation": "语义：圆周率是固定常数，没有可观察的“变化”，与“观察……的变化”不合。"}, {"text": "真理", "is_correct": false, "explanation": "语义：真理被视为确定不变的道理，不能说“观察真理的变化”。"}, {"text": "三角形内角和", "is_correct": false, "explanation": "语义：三角形内角和恒为180度，不会有变化可供观察。"}], "explanations": {"菌株": "正确：菌株会随时间发生变化，学生可以观察到它的变化。", "圆周率": "语义：圆周率是固定常数，没有可观察的“变化”，与“观察……的变化”不合。", "真理": "语义：真理被视为确定不变的道理，不能说“观察真理的变化”。", "三角形内角和": "语义：三角形内角和恒为180度，不会有变化可供观察。"}, "sentence_index": 6, "correct_answer": "菌株"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "衣柜里挂满了菌株。", "explanation": "这里应该用〈衣服〉。衣柜里挂的是衣服，菌株是微生物纯种，不能挂在衣柜里。"}, {"text": "汽车里坐满了菌株。", "explanation": "这里应该用〈乘客〉。汽车里坐的是乘客，菌株不是人，不能说“坐满”。"}, {"text": "海边的沙滩上堆着很多菌株。", "explanation": "这里应该用〈沙子〉。沙滩上堆的是沙子，菌株指纯种微生物，不能用来堆放。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5836933-6da4-40fd-b175-01f565777b70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25606, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "同学们把一只菌株放进了培养皿里。", "corrected_sentence": "同学们把一个菌株放进了培养皿里。", "error_description": "量词“只”用于动物，菌株应使用量词“个”，应为“一个菌株”，而不是“一只菌株”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5836933-6da4-40fd-b175-01f565777b70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25606, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学生们在培养皿里发现了一片新菌株。", "corrected_sentence": "学生们在培养皿里发现了一种新菌株。", "error_description": "量词“片”用于叶子、平面等，菌株应用“个”或“种”，此处应为“一种新菌株”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5836933-6da4-40fd-b175-01f565777b70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
