INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25608, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用掉了一些东西，比如用掉吃的或用的。", "primary_collocate": null, "pronunciation": "xiāo hào", "ipa": "ɕjɑʊ˥ xɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "我们很快就消耗了带来的面包。", "target_word": "消耗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些饭菜，他一个人就消耗了一大半。", "target_word": "消耗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的路很远，我们消耗了不少水。", "target_word": "消耗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个冬天，家里消耗了很多煤。", "target_word": "消耗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷一个月消耗两袋米。", "target_word": "消耗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "旅行时，我们把带的饼干都消耗完了。", "target_word": "消耗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃得多的人，消耗的食物也多。", "target_word": "消耗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家饭店每天消耗很多菜和肉。", "target_word": "消耗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "玩游戏时，手机的电消耗得很快。", "target_word": "消耗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "营地里的水，三天就消耗了一半。", "target_word": "消耗", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "消耗了", "label": "体标"}, {"form": "消耗着", "label": "体标"}, {"form": "消耗量", "label": "复合"}, {"form": "消耗品", "label": "复合"}], "register": "中性", "sense_fingerprint": "把吃的用的东西用掉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfd7af12-1a73-462f-9399-277b88dbbcd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25608, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "消耗", "is_correct": true, "explanation": "正确：消耗指用掉带来的食物，与句意相符。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱歌的对象不是面包，“唱了带来的面包”句意不通。"}, {"text": "放弃", "is_correct": false, "explanation": "搭配：“放弃”多用于计划、机会，不说放弃面包。"}, {"text": "笑", "is_correct": false, "explanation": "配价：“笑”是不及物动词，不能带“面包”作宾语。"}], "explanations": {"消耗": "正确：消耗指用掉带来的食物，与句意相符。", "唱": "语义：唱歌的对象不是面包，“唱了带来的面包”句意不通。", "放弃": "搭配：“放弃”多用于计划、机会，不说放弃面包。", "笑": "配价：“笑”是不及物动词，不能带“面包”作宾语。"}, "sentence_index": 0, "correct_answer": "消耗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个孩子很快就消耗了老师讲的课。", "explanation": "这里应该用〈消化〉。课程内容被理解吸收用消化；消耗指物资或精力被用掉，不用于课程。"}, {"text": "这个城市的居民消耗了三层楼。", "explanation": "这里应该用〈盖〉。盖楼是建造；消耗指物资或精力被用掉，不能用于建楼。"}, {"text": "这座城市的人口消耗了。", "explanation": "这里应该用〈减少〉。人口下降用减少；消耗指物资或精力被用掉，人不能被消耗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77a80b7b-6215-4605-be79-c8811bfd8ec2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25608, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "消耗", "is_correct": true, "explanation": "正确：消耗指吃掉、用掉食物，与“吃得多”的语境相符。"}, {"text": "运输", "is_correct": false, "explanation": "语义：句子说的是吃得多，“运输”与食物被吃掉的语境不合。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，“睡的食物”不成立。"}, {"text": "欣赏", "is_correct": false, "explanation": "搭配：“欣赏”的对象多为艺术、风景，不说欣赏食物。"}], "explanations": {"消耗": "正确：消耗指吃掉、用掉食物，与“吃得多”的语境相符。", "运输": "语义：句子说的是吃得多，“运输”与食物被吃掉的语境不合。", "睡": "配价：“睡”是不及物动词，“睡的食物”不成立。", "欣赏": "搭配：“欣赏”的对象多为艺术、风景，不说欣赏食物。"}, "sentence_index": 6, "correct_answer": "消耗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜里的噪音渐渐消耗了。", "explanation": "这里应该用〈消失〉。声音渐渐听不到用消失；消耗指物资或精力被用掉。"}, {"text": "医生给伤口消耗了。", "explanation": "这里应该用〈消毒〉。给伤口杀菌用消毒；消耗不能表示这个动作。"}, {"text": "他的脚踝已经消耗了。", "explanation": "这里应该用〈消肿〉。肿胀消退用消肿；消耗指物资、精力被用掉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77a80b7b-6215-4605-be79-c8811bfd8ec2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25608, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把带来的饭菜都消耗了掉。", "corrected_sentence": "他把带来的饭菜都消耗掉了。", "error_description": "错误形式：“消耗了掉”；正确形式：“消耗掉了”。结果补语“掉”要紧跟动词，动词后再加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77a80b7b-6215-4605-be79-c8811bfd8ec2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25608, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们家去年消耗了三个米。", "corrected_sentence": "我们家去年消耗了三袋米。", "error_description": "量词错误：“米”要用“袋”计量，不能用“个”；应说“消耗了三袋米”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77a80b7b-6215-4605-be79-c8811bfd8ec2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
