INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25612, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "什么都能做，什么都会。", "primary_collocate": null, "pronunciation": "wàn néng", "ipa": "wan˥˩ nɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他是个万能的人，什么都会做。", "target_word": "万能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我爸爸很万能，家里的东西坏了他都能修。", "target_word": "万能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有人是万能的，我们要互相帮助。", "target_word": "万能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小王样样都会，大家叫他“万能小王”。", "target_word": "万能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她好像是万能的，唱歌、跳舞、画画都行。", "target_word": "万能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司需要的不是万能的人，而是专业的人。", "target_word": "万能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在我孩子眼里，妈妈是万能的。", "target_word": "万能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个万能的小伙子，什么活儿都干得好。", "target_word": "万能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别把他当成万能的人，他也会累。", "target_word": "万能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他样样都行，同事都说他很万能。", "target_word": "万能", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "萬能", "label": "繁体"}], "register": "中性", "sense_fingerprint": "形容人什么都会做、样样都行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94d632af-a03a-43e4-9d77-faedd541679b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25612, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "无知", "is_correct": false, "explanation": "语义：“无知”与“什么都会做”的能力相悖，不能这样形容这个人。"}, {"text": "万能", "is_correct": true, "explanation": "正确：“他是个万能的人，什么都会做”说明他样样都会，“万能”符合语境。"}, {"text": "笨拙", "is_correct": false, "explanation": "语义：“笨拙”指不灵巧、做不好事，与“什么都会做”相矛盾。"}, {"text": "单一", "is_correct": false, "explanation": "语义：“单一”指只有一种、不多样，与“什么都会做”相悖，不能用来形容这个人。"}], "explanations": {"无知": "语义：“无知”与“什么都会做”的能力相悖，不能这样形容这个人。", "万能": "正确：“他是个万能的人，什么都会做”说明他样样都会，“万能”符合语境。", "笨拙": "语义：“笨拙”指不灵巧、做不好事，与“什么都会做”相矛盾。", "单一": "语义：“单一”指只有一种、不多样，与“什么都会做”相悖，不能用来形容这个人。"}, "sentence_index": 0, "correct_answer": "万能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位医生很万能，只看心脏病，经验丰富。", "explanation": "这里应该用〈专业〉。“专业”指在某一领域很精通；“万能”指什么都会做，不能用来说只看一类病的医生。"}, {"text": "他很万能，说话总是很客气。", "explanation": "这里应该用〈礼貌〉。“礼貌”指待人有礼；“万能”指什么都会做，不用来形容说话的态度。"}, {"text": "他做事很万能，从不拖延。", "explanation": "这里应该用〈利落〉。“利落”指做事干脆迅速；“万能”指什么都会做，不用来说做事快慢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1162e47f-bb97-46f4-bc80-30b284db04e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25612, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "无能", "is_correct": false, "explanation": "语义：“无能”与孩子眼中妈妈的形象相反，“妈妈是无能的”读来矛盾。"}, {"text": "万能", "is_correct": true, "explanation": "正确：“在我孩子眼里，妈妈是万能的”表示孩子认为妈妈什么都会，“万能”符合语境。"}, {"text": "无知", "is_correct": false, "explanation": "语义：“无知”说缺乏知识，与孩子心中的妈妈不符。"}, {"text": "陌生", "is_correct": false, "explanation": "搭配：“陌生”多用于不熟悉的人，不用来形容亲近的妈妈。"}], "explanations": {"无能": "语义：“无能”与孩子眼中妈妈的形象相反，“妈妈是无能的”读来矛盾。", "万能": "正确：“在我孩子眼里，妈妈是万能的”表示孩子认为妈妈什么都会，“万能”符合语境。", "无知": "语义：“无知”说缺乏知识，与孩子心中的妈妈不符。", "陌生": "搭配：“陌生”多用于不熟悉的人，不用来形容亲近的妈妈。"}, "sentence_index": 6, "correct_answer": "万能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很万能，从不说谎。", "explanation": "这里应该用〈诚实〉。“诚实”指不说假话、言行真实；“万能”指什么都会做，不用来形容一个人的品德。"}, {"text": "他很万能，每天第一个到办公室。", "explanation": "这里应该用〈勤快〉。“勤快”指肯干、不偷懒；“万能”指什么都会做，不用来说一个人勤不勤。"}, {"text": "她很万能，从不乱花钱。", "explanation": "这里应该用〈节俭〉。“节俭”指不浪费、不乱花钱；“万能”指什么都会做，不用来说花钱的习惯。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1162e47f-bb97-46f4-bc80-30b284db04e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25612, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她是个万能得老师，什么都懂。", "corrected_sentence": "她是个万能的老师，什么都懂。", "error_description": "结构助词错误：修饰名词“老师”的定语要用“的”，不用“得”（“得”用于动词或形容词后面作补语）。应说“万能的老师”，不说“万能得老师”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1162e47f-bb97-46f4-bc80-30b284db04e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25612, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他这个人很万能过，什么都会修。", "corrected_sentence": "他这个人很万能，什么都会修。", "error_description": "体标错误：形容词“万能”后不加“过”，“过”表示经历，不能与“很万能”这样的状态搭配，应去掉“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1162e47f-bb97-46f4-bc80-30b284db04e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
