INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25616, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "做东西时要用到的材料。", "primary_collocate": null, "pronunciation": "yuán liào", "ipa": "ɥɛn˧˥ ljɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "做面包的原料是面粉和水。", "target_word": "原料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂的原料都从国外买。", "target_word": "原料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "原料不够，工人只好先休息。", "target_word": "原料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做纸要用木头当原料。", "target_word": "原料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种饮料的原料很新鲜。", "target_word": "原料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一批新原料明天会运到工厂。", "target_word": "原料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最近原料涨价，面包也贵了。", "target_word": "原料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅仔细检查了每一种原料。", "target_word": "原料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "豆腐的主要原料是黄豆。", "target_word": "原料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做蛋糕前，先把原料准备好。", "target_word": "原料", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一批原料", "label": "量词"}, {"form": "一种原料", "label": "量词"}, {"form": "原材料", "label": "复合"}, {"form": "食品原料", "label": "复合"}], "register": "中性", "sense_fingerprint": "制造产品所用的材料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59a7a008-8700-472e-9416-a17e42e54d73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25616, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "原料", "is_correct": true, "explanation": "正确：做面包要用的材料，符合“做面包的……是面粉和水”的语境。"}, {"text": "产品", "is_correct": false, "explanation": "语义：“产品”是做好的东西，面粉和水是做面包前用的，与语境不合。"}, {"text": "烤箱", "is_correct": false, "explanation": "语义：“烤箱”是工具，不是材料，“烤箱是面粉和水”不通。"}, {"text": "饲料", "is_correct": false, "explanation": "语义：“饲料”是给动物吃的，不是做面包用的材料。"}], "explanations": {"原料": "正确：做面包要用的材料，符合“做面包的……是面粉和水”的语境。", "产品": "语义：“产品”是做好的东西，面粉和水是做面包前用的，与语境不合。", "烤箱": "语义：“烤箱”是工具，不是材料，“烤箱是面粉和水”不通。", "饲料": "语义：“饲料”是给动物吃的，不是做面包用的材料。"}, "sentence_index": 0, "correct_answer": "原料"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这篇文章的原料很丰富，可以用来写论文。", "explanation": "这里应该用〈材料〉。“原料”指做产品用的东西，文章里的素材要用“材料”。"}, {"text": "我买了一只原料，准备回家做饭。", "explanation": "这里应该用〈种〉。原料不用“只”计量，“只”多用于动物，原料一般用“种”或“批”。"}, {"text": "我们班的原料都很聪明。", "explanation": "这里应该用〈学生〉。“原料”指做东西用的材料，不能指人，说班里的人应该用“学生”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66f38db7-9c14-48aa-ab1e-864b969d105d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25616, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "原料", "is_correct": true, "explanation": "正确：“原料”涨价会使面包也贵，符合“最近……涨价，面包也贵了”的语境。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：说工资上涨用“涨工资”，不说“工资涨价”。"}, {"text": "工人", "is_correct": false, "explanation": "语义：“工人”不是商品，不能说“工人涨价”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不会涨价，“天气涨价”与语境不符。"}], "explanations": {"原料": "正确：“原料”涨价会使面包也贵，符合“最近……涨价，面包也贵了”的语境。", "工资": "搭配：说工资上涨用“涨工资”，不说“工资涨价”。", "工人": "语义：“工人”不是商品，不能说“工人涨价”。", "天气": "语义：“天气”不会涨价，“天气涨价”与语境不符。"}, "sentence_index": 6, "correct_answer": "原料"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个玩具是工厂做好的原料，已经卖到国外了。", "explanation": "这里应该用〈成品〉。玩具是做好的东西，“原料”指还没做成东西前用的材料。"}, {"text": "这次失败的原料是我们没有准备好。", "explanation": "这里应该用〈原因〉。“原料”指做东西用的材料，不能指导致结果的缘由。"}, {"text": "妈妈说，晚饭的原料要趁热吃。", "explanation": "这里应该用〈饭菜〉。“原料”是还没做成的材料，不能直接当饭吃，晚饭应说“饭菜”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66f38db7-9c14-48aa-ab1e-864b969d105d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25616, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买了三只原料，准备做蛋糕。", "corrected_sentence": "我买了三种原料，准备做蛋糕。", "error_description": "错误：“原料”前的量词“只”用错了，“只”多用于动物。正确：“三种原料”，“种”用于原料。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66f38db7-9c14-48aa-ab1e-864b969d105d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25616, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这批原料的很便宜。", "corrected_sentence": "这批原料很便宜。", "error_description": "错误：“原料”后多加了“的”。正确：“这批原料很便宜”，“原料”后直接接形容词谓语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66f38db7-9c14-48aa-ab1e-864b969d105d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
