INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25618, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让一件事开始发生。", "primary_collocate": null, "pronunciation": "chù fā", "ipa": "ʈʂʰu⁵¹ fa⁵⁵", "syllable_count": 2, "sentences": [{"text": "一个小问题触发了大家的讨论。", "target_word": "触发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个消息触发了一连串变化。", "target_word": "触发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一场大雨触发了山上的泥石流。", "target_word": "触发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "什么事触发了他的怒气？", "target_word": "触发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌触发了我对家乡的想念。", "target_word": "触发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "关门的声音触发了孩子的哭声。", "target_word": "触发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一次失败触发了他重新学习的决心。", "target_word": "触发", "complexity_tier": "T3", "furigana": "yí cì shībài chùfā le tā chóngxīn xuéxí de juéxīn", "sentence_source": "generated"}, {"text": "一句玩笑触发了一场争吵。", "target_word": "触发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次事故触发了新的安全规定。", "target_word": "触发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的问题触发了同学们的思考。", "target_word": "触发", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "触发了", "label": "体标"}, {"form": "触发过", "label": "体标"}, {"form": "触发器", "label": "复合"}], "register": "书面", "sense_fingerprint": "某个原因或事件引起另一件事开始发生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a662146-0fe1-4053-b97b-687a43040117') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25618, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "触发", "is_correct": true, "explanation": "正确。触发（chù fā）：某个原因或事件引起另一件事开始发生。"}, {"text": "出发", "is_correct": false, "explanation": "chū（第一声）与 chù（第四声）声调不同，意思是动身、起程。"}, {"text": "处罚", "is_correct": false, "explanation": "chǔ（第三声）与 chù（第四声）、fá（第二声）与 fā（第一声）声调都不同，意思是给予惩罚。"}, {"text": "除法", "is_correct": false, "explanation": "chú（第二声）与 chù（第四声）、fǎ（第三声）与 fā（第一声）声调都不同，意思是数学中的除法运算。"}], "explanations": {"触发": "正确。触发（chù fā）：某个原因或事件引起另一件事开始发生。", "出发": "chū（第一声）与 chù（第四声）声调不同，意思是动身、起程。", "处罚": "chǔ（第三声）与 chù（第四声）、fá（第二声）与 fā（第一声）声调都不同，意思是给予惩罚。", "除法": "chú（第二声）与 chù（第四声）、fǎ（第三声）与 fā（第一声）声调都不同，意思是数学中的除法运算。"}, "sentence_index": null, "correct_answer": "触发"}, "level_3": {"options": [{"text": "触发", "is_correct": true, "explanation": "正确。“触发”表示小问题引起讨论开始，符合语境。"}, {"text": "消除", "is_correct": false, "explanation": "搭配：“消除”接误会、疑虑等，不说“消除讨论”。"}, {"text": "解决", "is_correct": false, "explanation": "搭配：“解决”接问题、矛盾，讨论不能被“解决”。"}, {"text": "冷落", "is_correct": false, "explanation": "语义：“冷落”指冷淡、不予理睬，与讨论被引发、变热烈的意思相反。"}], "explanations": {"触发": "正确。“触发”表示小问题引起讨论开始，符合语境。", "消除": "搭配：“消除”接误会、疑虑等，不说“消除讨论”。", "解决": "搭配：“解决”接问题、矛盾，讨论不能被“解决”。", "冷落": "语义：“冷落”指冷淡、不予理睬，与讨论被引发、变热烈的意思相反。"}, "sentence_index": 0, "correct_answer": "触发"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的话触发了老板。", "explanation": "这里应该用〈惹恼〉。触发的宾语是反应或事件，不能直接指人，惹恼的是人，应说惹恼。"}, {"text": "他故意触发了一场比赛。", "explanation": "这里应该用〈举办〉。触发指条件引起某事自动开始，比赛要由人举办，不能说触发。"}, {"text": "这门课触发了我的能力。", "explanation": "这里应该用〈培养〉。触发指事件或反应开始出现，能力要说培养。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5836933-6da4-40fd-b175-01f565777b70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25618, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "触发", "is_correct": true, "explanation": "正确。“触发”表示失败引起决心的产生，符合语境。"}, {"text": "赠送", "is_correct": false, "explanation": "搭配：“赠送”接有形物品，不说赠送决心。"}, {"text": "嘲笑", "is_correct": false, "explanation": "配价：“嘲笑”的施事须是人，“一次失败”不能嘲笑某人的决心。"}, {"text": "测量", "is_correct": false, "explanation": "搭配：“测量”接可以量化的事物，决心不能被测量。"}], "explanations": {"触发": "正确。“触发”表示失败引起决心的产生，符合语境。", "赠送": "搭配：“赠送”接有形物品，不说赠送决心。", "嘲笑": "配价：“嘲笑”的施事须是人，“一次失败”不能嘲笑某人的决心。", "测量": "搭配：“测量”接可以量化的事物，决心不能被测量。"}, "sentence_index": 6, "correct_answer": "触发"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "暴雨触发了严重的损失。", "explanation": "这里应该用〈造成〉。触发强调条件引起反应或事件开始，损失是结果，应说造成。"}, {"text": "这项改革触发了新的时代。", "explanation": "这里应该用〈开启〉。触发不用于开启时代、局面这类大的阶段。"}, {"text": "这项技术触发了许多便利。", "explanation": "这里应该用〈带来〉。触发引出的是反应或现象，“便利”这类好处应说带来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5836933-6da4-40fd-b175-01f565777b70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25618, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一次意外停电被触发了系统的自动保护。", "corrected_sentence": "一次意外停电触发了系统的自动保护。", "error_description": "“被”字句误用：“触发”的主语应是引起事件的原因“一次意外停电”，应说“一次意外停电触发了系统的自动保护”；加“被”会把停电变成被动承受者，语义颠倒。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5836933-6da4-40fd-b175-01f565777b70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25618, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一次重大的失误会触发了一场争论。", "corrected_sentence": "一次重大的失误会触发一场争论。", "error_description": "“会”表示将要或可能，不能与完成体“了”同用；应说“会触发一场争论”，去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5836933-6da4-40fd-b175-01f565777b70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
