INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25622, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "身体里像管道一样的东西，血液在里面流来流去。", "primary_collocate": null, "pronunciation": "xún huán xì tǒng", "ipa": "ɕyn˧˥ xwan˧˥ ɕi˥˩ tʰʊŋ˨˩˦", "syllable_count": 4, "sentences": [{"text": "身体里的循环系统像水管一样。", "target_word": "循环系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "血液在循环系统里不停地流。", "target_word": "循环系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说我的循环系统很健康。", "target_word": "循环系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们画了人的循环系统。", "target_word": "循环系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "循环系统里的血流得很快。", "target_word": "循环系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生用图给孩子讲循环系统。", "target_word": "循环系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道循环系统在身体的哪里吗？", "target_word": "循环系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "循环系统要是堵住了，人会生病。", "target_word": "循环系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跑步以后，循环系统工作得更快。", "target_word": "循环系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上说，循环系统遍布全身。", "target_word": "循环系统", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "血液循环系统", "label": "复合"}], "register": "口语", "sense_fingerprint": "身体里像管道、让血液流动的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6400fda1-5aa5-4407-a552-0ac0924ed60e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25622, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "循环系统", "is_correct": true, "explanation": "“身体里的循环系统”指身体里像水管一样输送血液的部分，句意成立。"}, {"text": "书架", "is_correct": false, "explanation": "语义：书架是家具，不是身体里像水管一样的东西，句子说不通。"}, {"text": "窗帘", "is_correct": false, "explanation": "语义：窗帘挂在窗前，不会出现在身体里，与“身体里的”相冲突。"}, {"text": "篮球", "is_correct": false, "explanation": "搭配：“身体里的”后不能接球类，篮球不是身体内部的结构。"}], "explanations": {"循环系统": "“身体里的循环系统”指身体里像水管一样输送血液的部分，句意成立。", "书架": "语义：书架是家具，不是身体里像水管一样的东西，句子说不通。", "窗帘": "语义：窗帘挂在窗前，不会出现在身体里，与“身体里的”相冲突。", "篮球": "搭配：“身体里的”后不能接球类，篮球不是身体内部的结构。"}, "sentence_index": 0, "correct_answer": "循环系统"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈在商店买了一个循环系统给我当礼物。", "explanation": "〈循环系统〉是身体里输送血液的结构，不是商品，不能在商店买来送人。"}, {"text": "循环系统每分钟呼吸十几次。", "explanation": "这里应该用〈肺〉。呼吸是肺的功能，循环系统负责输送血液，不能“呼吸”。"}, {"text": "他的循环系统昨天跑去踢足球了。", "explanation": "〈循环系统〉指身体里像管道一样的结构，不是人，不能去踢足球。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff79a57e-830b-49cb-a3be-ec378a51b0be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25622, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "循环系统", "is_correct": true, "explanation": "“你知道循环系统在身体的哪里吗”问的是循环系统位于身体的什么位置，句子成立。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是身体的部件，问它“在身体的哪里”没有意义。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家电，不会位于身体内部，句子不通。"}, {"text": "电话", "is_correct": false, "explanation": "搭配：“在身体的哪里”一般接身体部位或器官，电话不能作为身体内部的部件。"}], "explanations": {"循环系统": "“你知道循环系统在身体的哪里吗”问的是循环系统位于身体的什么位置，句子成立。", "天气": "语义：天气不是身体的部件，问它“在身体的哪里”没有意义。", "冰箱": "语义：冰箱是家电，不会位于身体内部，句子不通。", "电话": "搭配：“在身体的哪里”一般接身体部位或器官，电话不能作为身体内部的部件。"}, "sentence_index": 6, "correct_answer": "循环系统"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天都去循环系统里游泳。", "explanation": "〈循环系统〉是身体内部的结构，不能作为游泳的场所，“去……里游泳”的地点应是水池或水域。"}, {"text": "妈妈用循环系统切菜。", "explanation": "〈循环系统〉指身体里输送血液的结构，不是厨房用具，不能用来切菜。"}, {"text": "他把循环系统挂在墙上当装饰。", "explanation": "〈循环系统〉是身体内部的结构，不能被挂在墙上当装饰品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff79a57e-830b-49cb-a3be-ec378a51b0be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25622, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "医生给我们讲了血液怎么在循环系统上流动。", "corrected_sentence": "医生给我们讲了血液怎么在循环系统里流动。", "error_description": "错误：“循环系统上”；正确：“循环系统里”。循环系统像管道，血液在管道里面流动，不是在表面上，应用方位词“里”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff79a57e-830b-49cb-a3be-ec378a51b0be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25622, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "身体里有一把循环系统。", "corrected_sentence": "身体里有一套循环系统。", "error_description": "错误：“一把”；正确：“一套”。循环系统是成套的器官系统，应用量词“套”，“把”用于有柄的器具。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff79a57e-830b-49cb-a3be-ec378a51b0be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
