INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25623, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "能解除毒性、使中毒的人好起来的药。", "primary_collocate": null, "pronunciation": "jiě yào", "ipa": "tɕjɛ˨˩˦ jɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "小明喝错了东西，要快点吃解药。", "target_word": "解药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这瓶是解药，那瓶是毒药。", "target_word": "解药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "解药在医生手里，他正在给病人用。", "target_word": "解药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吃了解药以后，他不难受了。", "target_word": "解药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "故事里的公主喝了毒水，王子去找解药。", "target_word": "解药", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种毒很少见，医院里没有解药。", "target_word": "解药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他中毒了，必须马上找到解药。", "target_word": "解药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "解药很贵，一小瓶要一千块钱。", "target_word": "解药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有中毒的人不要乱吃解药。", "target_word": "解药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小狗吃了有毒的东西，医生给它打了解药。", "target_word": "解药", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一瓶解药", "label": "量词"}, {"form": "一剂解药", "label": "量词"}, {"form": "解藥", "label": "繁体"}], "register": "中性", "sense_fingerprint": "中毒后用来解毒的药", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94d632af-a03a-43e4-9d77-faedd541679b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25623, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "毒药", "is_correct": false, "explanation": "语义：吃毒药会加重中毒，与“快点吃”让人好起来的目的相反。"}, {"text": "解药", "is_correct": true, "explanation": "正确：“小明喝错了东西，要快点吃解药”符合语境，“解药”能让人不再中毒。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：饼干不能解除喝错东西带来的中毒，与急救语境不符。"}, {"text": "毒蘑菇", "is_correct": false, "explanation": "搭配：“快点吃”后接的应是能帮助康复的东西，“毒蘑菇”是有害之物，不搭配这种急救用法。"}], "explanations": {"毒药": "语义：吃毒药会加重中毒，与“快点吃”让人好起来的目的相反。", "解药": "正确：“小明喝错了东西，要快点吃解药”符合语境，“解药”能让人不再中毒。", "饼干": "语义：饼干不能解除喝错东西带来的中毒，与急救语境不符。", "毒蘑菇": "搭配：“快点吃”后接的应是能帮助康复的东西，“毒蘑菇”是有害之物，不搭配这种急救用法。"}, "sentence_index": 0, "correct_answer": "解药"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道菜要放点解药才好吃。", "explanation": "这里应该用〈调料〉。调料用于调味；解药指能让人不再生病或中毒的药，不用来给菜调味。"}, {"text": "头发油，用解药洗一洗。", "explanation": "这里应该用〈洗发水〉。洗发水用于清洁头发；解药指能让人不再生病或中毒的药，不用来洗头。"}, {"text": "打了解药以后，他不容易生病了。", "explanation": "这里应该用〈疫苗〉。疫苗用于预防，解药用于在中毒或生病后让人好起来，不用于预防。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1162e47f-bb97-46f4-bc80-30b284db04e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25623, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "纸牌", "is_correct": false, "explanation": "语义：纸牌不能解除中毒，“必须马上找到”纸牌救治不了中毒的人，句意不通。"}, {"text": "解药", "is_correct": true, "explanation": "正确：“他中毒了，必须马上找到解药”符合语境，“解药”能让中毒的人好起来。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本不能解毒，与中毒急需救治的语境不符。"}, {"text": "谎言", "is_correct": false, "explanation": "搭配：“找到”后接“谎言”不成立，应说“揭穿谎言”，不说“找到谎言”。"}], "explanations": {"纸牌": "语义：纸牌不能解除中毒，“必须马上找到”纸牌救治不了中毒的人，句意不通。", "解药": "正确：“他中毒了，必须马上找到解药”符合语境，“解药”能让中毒的人好起来。", "课本": "语义：课本不能解毒，与中毒急需救治的语境不符。", "谎言": "搭配：“找到”后接“谎言”不成立，应说“揭穿谎言”，不说“找到谎言”。"}, "sentence_index": 6, "correct_answer": "解药"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老人每天要吃解药，身体才好。", "explanation": "这里应该用〈维生素〉。维生素用于补充营养；解药用于解除毒性，不用于日常保健。"}, {"text": "手术前，护士给他注射解药。", "explanation": "这里应该用〈麻醉剂〉。麻醉剂用于手术前使人暂时失去知觉；解药用于解毒，不用于手术麻醉。"}, {"text": "他很累，喝了解药就精神了。", "explanation": "这里应该用〈提神饮料〉。提神饮料用于消除疲劳；解药用于解毒，疲劳不是中毒，不用解药。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1162e47f-bb97-46f4-bc80-30b284db04e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25623, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他误吞了毒药，医生正在给他一根解药。", "corrected_sentence": "他误吞了毒药，医生正在给他一粒解药。", "error_description": "量词错误：“根”用于细长的东西，解药是药片或药丸，应说“一粒解药”，不说“一根解药”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1162e47f-bb97-46f4-bc80-30b284db04e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25623, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子误服了毒，医院马上送来一把解药。", "corrected_sentence": "孩子误服了毒，医院马上送来一剂解药。", "error_description": "量词错误：解药应用“剂”“粒”等，“把”用于有柄的东西，不说“一把解药”。目标词“解药”的量词用错了。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1162e47f-bb97-46f4-bc80-30b284db04e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
