INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25628, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "我们脚下的东西叫地，比如花园里的泥土。", "primary_collocate": null, "pronunciation": "dì", "ipa": "ti˥˩", "syllable_count": 1, "sentences": [{"text": "雨下了一夜，地还是湿的。", "target_word": "地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈每天早上扫地。", "target_word": "地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们坐在地上玩。", "target_word": "地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刚拖过的地很滑，小心点。", "target_word": "地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这间屋子的地是木头做的。", "target_word": "地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他蹲下来，用手摸了摸地。", "target_word": "地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花园里的地很软，适合种花。", "target_word": "地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷蹲在地上拔草。", "target_word": "地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雪以后，地都白了。", "target_word": "地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请别把垃圾扔到地上。", "target_word": "地", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "地上", "label": "复合"}, {"form": "地面", "label": "复合"}, {"form": "土地", "label": "复合"}], "register": "中性", "sense_fingerprint": "脚下的地面和泥土", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e685e353-0b99-4f1c-ae5d-499665025313') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25628, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "地", "is_correct": true, "explanation": "地：我们脚下的东西，比如花园里的泥土。"}, {"text": "底", "is_correct": false, "explanation": "dǐ（第三声）与 dì（第四声）声调不同，意思是物体的最下部分。"}, {"text": "滴", "is_correct": false, "explanation": "dī（第一声）与 dì（第四声）声调不同，意思是液体一点一点落下。"}, {"text": "敌", "is_correct": false, "explanation": "dí（第二声）与 dì（第四声）声调不同，意思是敌人。"}, {"text": "堤", "is_correct": false, "explanation": "dī（第一声）与 dì（第四声）声调不同，意思是挡水的堤坝。"}], "explanations": {"地": "地：我们脚下的东西，比如花园里的泥土。", "底": "dǐ（第三声）与 dì（第四声）声调不同，意思是物体的最下部分。", "滴": "dī（第一声）与 dì（第四声）声调不同，意思是液体一点一点落下。", "敌": "dí（第二声）与 dì（第四声）声调不同，意思是敌人。", "堤": "dī（第一声）与 dì（第四声）声调不同，意思是挡水的堤坝。"}, "sentence_index": null, "correct_answer": "地"}, "level_3": {"options": [{"text": "地", "is_correct": true, "explanation": "地：地面，雨下了一夜，地面还是湿的。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳是天体，不会被雨淋湿，与“雨下了一夜”的语境不合。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“湿的”形容有形的物体，不修饰时间。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“湿的”形容有形的物体，不修饰声音。"}], "explanations": {"地": "地：地面，雨下了一夜，地面还是湿的。", "太阳": "语义：太阳是天体，不会被雨淋湿，与“雨下了一夜”的语境不合。", "时间": "搭配：“湿的”形容有形的物体，不修饰时间。", "声音": "搭配：“湿的”形容有形的物体，不修饰声音。"}, "sentence_index": 0, "correct_answer": "地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "河里的地很清，能看到鱼。", "explanation": "这里应该用〈水〉。地指脚下的东西，河里清澈的是水，不是地。"}, {"text": "请把你的地写在这张纸上。", "explanation": "这里应该用〈地址〉。地指地面，写住所要用地址。"}, {"text": "地上飞着很多小鸟和白云。", "explanation": "这里应该用〈天〉。地指脚下的地面，鸟和云在天上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96e211d8-98e0-4280-807c-a91714ed980f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25628, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "地", "is_correct": true, "explanation": "地：我们脚下的东西，比如花园里的泥土。"}, {"text": "抵", "is_correct": false, "explanation": "dǐ（第三声）与 dì（第四声）声调不同，意思是抵挡。"}, {"text": "低", "is_correct": false, "explanation": "dī（第一声）与 dì（第四声）声调不同，意思是高度不高。"}, {"text": "笛", "is_correct": false, "explanation": "dí（第二声）与 dì（第四声）声调不同，意思是笛子。"}], "explanations": {"地": "地：我们脚下的东西，比如花园里的泥土。", "抵": "dǐ（第三声）与 dì（第四声）声调不同，意思是抵挡。", "低": "dī（第一声）与 dì（第四声）声调不同，意思是高度不高。", "笛": "dí（第二声）与 dì（第四声）声调不同，意思是笛子。"}, "sentence_index": null, "correct_answer": "地"}, "level_3": {"options": [{"text": "地", "is_correct": true, "explanation": "地：地面，花园里的地很软，适合种花。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是硬的，不能说很软，也不能用来种花。"}, {"text": "床", "is_correct": false, "explanation": "语义：床不能用来种花，与“花园里”的语境不合。"}, {"text": "墙", "is_correct": false, "explanation": "搭配：“很软”形容土、泥等质地，墙一般不说很软。"}], "explanations": {"地": "地：地面，花园里的地很软，适合种花。", "石头": "语义：石头是硬的，不能说很软，也不能用来种花。", "床": "语义：床不能用来种花，与“花园里”的语境不合。", "墙": "搭配：“很软”形容土、泥等质地，墙一般不说很软。"}, "sentence_index": 6, "correct_answer": "地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天坐地去上班。", "explanation": "这里应该用〈地铁〉。地指地面，乘坐地下交通要用地铁。"}, {"text": "这张地很详细，我们一起看吧。", "explanation": "这里应该用〈地图〉。地指地面，说明图要用地图。"}, {"text": "去年这里发生了地，房子都倒了。", "explanation": "这里应该用〈地震〉。地指地面，发生灾害要用地震。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96e211d8-98e0-4280-807c-a91714ed980f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25628, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子们地上跑。", "corrected_sentence": "孩子们在地上跑。", "error_description": "表示动作的处所，要用介词“在”引出“地上”，应说“在地上跑”，不能省略“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96e211d8-98e0-4280-807c-a91714ed980f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25628, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他坐在地哭了。", "corrected_sentence": "他坐在地上哭了。", "error_description": "“地上”表示处所，“上”不能省略，说“坐在地哭”是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96e211d8-98e0-4280-807c-a91714ed980f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
