INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25634, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "两样东西在一起配合使用。", "primary_collocate": null, "pronunciation": "pèi tào", "ipa": "pʰeɪ˥˩ tʰɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "这个杯子和杯盖是配套的。", "target_word": "配套", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我买了一个电饭煲，还有配套的内胆。", "target_word": "配套", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这双运动鞋有配套的鞋带。", "target_word": "配套", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这把锁和钥匙不配套。", "target_word": "配套", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请使用配套的充电线。", "target_word": "配套", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台打印机有配套的墨盒。", "target_word": "配套", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的帽子和围巾很配套。", "target_word": "配套", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这套茶具的配套托盘在哪儿？", "target_word": "配套", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "锅盖和锅不配套，所以漏气。", "target_word": "配套", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个零件是配套的，不能分开用。", "target_word": "配套", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "配套设施", "label": "复合"}], "register": "中性", "sense_fingerprint": "两样东西可以在一起配合使用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94d632af-a03a-43e4-9d77-faedd541679b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25634, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "配套", "is_correct": true, "explanation": "“配套”指两样东西配合使用，正是“杯子和杯盖”之间的关系。"}, {"text": "唯一", "is_correct": false, "explanation": "语义：“唯一”指只有一个，与“杯子和杯盖”是两件东西的语境相矛盾。"}, {"text": "锋利", "is_correct": false, "explanation": "搭配：“锋利”多形容刀刃等，不用来形容杯子和杯盖。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”描写身材或体积，与杯子和杯盖的尺寸不符。"}], "explanations": {"配套": "“配套”指两样东西配合使用，正是“杯子和杯盖”之间的关系。", "唯一": "语义：“唯一”指只有一个，与“杯子和杯盖”是两件东西的语境相矛盾。", "锋利": "搭配：“锋利”多形容刀刃等，不用来形容杯子和杯盖。", "高大": "体貌：“高大”描写身材或体积，与杯子和杯盖的尺寸不符。"}, "sentence_index": 0, "correct_answer": "配套"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的成绩和我的努力很配套。", "explanation": "这里应该用〈契合〉。配套指两样东西在一起使用，不用于说成绩与努力之间的契合关系。"}, {"text": "他的能力和这份工作很配套。", "explanation": "这里应该用〈胜任〉。配套指物件成套搭配使用，不用来说人的能力能否做好一份工作。"}, {"text": "这份报告的结论和题目很配套。", "explanation": "这里应该用〈切题〉。配套指两样东西在一起使用，不用于说报告结论与题目之间的切合。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1162e47f-bb97-46f4-bc80-30b284db04e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25634, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "配套", "is_correct": true, "explanation": "“配套”指成套搭配，与“她的帽子和围巾”的搭配关系相符。"}, {"text": "寂寞", "is_correct": false, "explanation": "语义：“寂寞”形容人的心情，不用来形容帽子和围巾。"}, {"text": "紧张", "is_correct": false, "explanation": "语义：“紧张”指人的心理状态，与衣物之间的搭配无关。"}, {"text": "热心", "is_correct": false, "explanation": "搭配：“热心”形容人的态度，不用来形容衣物。"}], "explanations": {"配套": "“配套”指成套搭配，与“她的帽子和围巾”的搭配关系相符。", "寂寞": "语义：“寂寞”形容人的心情，不用来形容帽子和围巾。", "紧张": "语义：“紧张”指人的心理状态，与衣物之间的搭配无关。", "热心": "搭配：“热心”形容人的态度，不用来形容衣物。"}, "sentence_index": 6, "correct_answer": "配套"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们两人配套得很默契。", "explanation": "这里应该用〈配合〉。配套指物件成套搭配，不用于形容人之间的协作默契。"}, {"text": "她的身份和地位很配套。", "explanation": "这里应该用〈相称〉。配套指物件相互搭配成套，不用于形容人的身份、地位与某种条件相称。"}, {"text": "这篇文章的段落很配套。", "explanation": "这里应该用〈连贯〉。配套指物件成套搭配，不用于描写文章前后衔接。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1162e47f-bb97-46f4-bc80-30b284db04e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25634, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这副眼镜和眼镜盒是配套。", "corrected_sentence": "这副眼镜和眼镜盒是配套的。", "error_description": "错误：“是……的”结构中，形容词“配套”后缺少“的”。应说“是配套的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1162e47f-bb97-46f4-bc80-30b284db04e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25634, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张床和床垫很配套着。", "corrected_sentence": "这张床和床垫很配套。", "error_description": "错误：形容词“配套”表示状态，后面不应加“着”。应说“很配套”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1162e47f-bb97-46f4-bc80-30b284db04e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
