INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25636, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "使命就是一个人或一个组织特别重要的任务。", "primary_collocate": null, "pronunciation": "shǐ mìng", "ipa": "ʂɻ̩˨˩˦ miŋ˥˩", "syllable_count": 2, "sentences": [{"text": "学校的使命是培养好学生。", "target_word": "使命", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个志愿者团队有一个特别的使命。", "target_word": "使命", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "救火是消防员最重要的使命。", "target_word": "使命", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师觉得教好学生是自己的使命。", "target_word": "使命", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司的使命写在大门旁边的墙上。", "target_word": "使命", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个组织的使命是帮助生病的孩子。", "target_word": "使命", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每个人在生活中都有自己的使命。", "target_word": "使命", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他明白了自己的使命，就不再害怕。", "target_word": "使命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家银行的使命是帮助小企业发展。", "target_word": "使命", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察的使命是保护市民的安全。", "target_word": "使命", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个使命", "label": "量词"}, {"form": "历史使命", "label": "复合"}], "register": "书面", "sense_fingerprint": "个人或组织特别重要的任务", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5f18f94-d445-4d0e-a98e-278af7fa0f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25636, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "使命", "is_correct": true, "explanation": "正确：这是听到的目标词 shǐmìng。"}, {"text": "失明", "is_correct": false, "explanation": "shīmíng（第一声、第二声）与 shǐmìng 两个音节声调都不同，意思是失去视力。"}, {"text": "实名", "is_correct": false, "explanation": "shímíng（第二声）与 shǐmìng 两个音节声调都不同，意思是用真实姓名。"}, {"text": "十名", "is_correct": false, "explanation": "shímíng（第二声）与 shǐmìng 两个音节声调都不同，意思是十个人。"}], "explanations": {"使命": "正确：这是听到的目标词 shǐmìng。", "失明": "shīmíng（第一声、第二声）与 shǐmìng 两个音节声调都不同，意思是失去视力。", "实名": "shímíng（第二声）与 shǐmìng 两个音节声调都不同，意思是用真实姓名。", "十名": "shímíng（第二声）与 shǐmìng 两个音节声调都不同，意思是十个人。"}, "sentence_index": null, "correct_answer": "使命"}, "level_3": {"options": [{"text": "使命", "is_correct": true, "explanation": "正确：“学校的……是培养好学生”说的是学校承担的重大责任，“使命”符合语境。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本是教学用品，不是学校的职责，句意不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不能作为学校要承担的任务。"}, {"text": "午饭", "is_correct": false, "explanation": "搭配：“学校的……是培养好学生”的主语应是职责，“午饭”不能这样搭配。"}], "explanations": {"使命": "正确：“学校的……是培养好学生”说的是学校承担的重大责任，“使命”符合语境。", "课本": "语义：课本是教学用品，不是学校的职责，句意不通。", "天气": "语义：天气是自然现象，不能作为学校要承担的任务。", "午饭": "搭配：“学校的……是培养好学生”的主语应是职责，“午饭”不能这样搭配。"}, "sentence_index": 0, "correct_answer": "使命"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师的使命是打篮球。", "explanation": "这里应该用〈爱好〉。使命指个人或组织特别重要的任务，个人兴趣不能说使命。"}, {"text": "今天的使命是打扫教室。", "explanation": "这里应该用〈任务〉。使命指特别重要的任务，日常的小任务不能说使命。"}, {"text": "这辆自行车的使命是送快递。", "explanation": "这里应该用〈用途〉。使命指特别重要的任务，自行车的用途不能说使命。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0a2b70-9da1-43f2-b93f-cae70927e0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25636, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "使命", "is_correct": true, "explanation": "正确：“每个人在生活中都有自己的……”指人生中的重要任务，“使命”符合语境。"}, {"text": "汽油", "is_correct": false, "explanation": "语义：汽油是燃料，不是人生中需要承担的重要任务，句意不通。"}, {"text": "纸张", "is_correct": false, "explanation": "搭配：“自己的”后接“纸张”不能指生活中的重要任务。"}, {"text": "鞋带", "is_correct": false, "explanation": "语义：鞋带是系鞋的带子，不是人生中需要承担的重要任务。"}], "explanations": {"使命": "正确：“每个人在生活中都有自己的……”指人生中的重要任务，“使命”符合语境。", "汽油": "语义：汽油是燃料，不是人生中需要承担的重要任务，句意不通。", "纸张": "搭配：“自己的”后接“纸张”不能指生活中的重要任务。", "鞋带": "语义：鞋带是系鞋的带子，不是人生中需要承担的重要任务。"}, "sentence_index": 6, "correct_answer": "使命"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这顿午饭的使命是让我吃饱。", "explanation": "这里应该用〈目的〉。使命指个人或组织特别重要的任务，吃一顿饭的目的不能说使命。"}, {"text": "他的使命是早起跑步。", "explanation": "这里应该用〈习惯〉。使命指重大责任，日常习惯不能说使命。"}, {"text": "今天的使命是背单词。", "explanation": "这里应该用〈作业〉。使命指重大责任，日常作业不能说使命。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0a2b70-9da1-43f2-b93f-cae70927e0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25636, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他接下了这副重要的使命。", "corrected_sentence": "他接下了这个重要的使命。", "error_description": "量词错误：“使命”应用“个”计量（这个重要的使命），“副”用于成对的东西，不能计量使命。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0a2b70-9da1-43f2-b93f-cae70927e0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25636, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他有一把使命，就是为社区服务。", "corrected_sentence": "他有一个使命，就是为社区服务。", "error_description": "量词错误：“使命”应用“个”计量（一个使命），“把”用于有柄的东西，不能计量使命。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0a2b70-9da1-43f2-b93f-cae70927e0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
