INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25654, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02226a68-658a-4356-821b-8a8997342f34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25654, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "首尾相接、转一圈又回到起点的环形；也指首尾相连、自成循环的完整流程。", "primary_collocate": null, "pronunciation": "bì huán", "ipa": "pi˥˩ xwan˧˥", "syllable_count": 2, "sentences": [{"text": "电路连成闭环，电流才能通过。", "target_word": "闭环", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "从计划到检查，我们形成了一个闭环。", "target_word": "闭环", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条跑道是一个闭环，跑一圈就回到起点。", "target_word": "闭环", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个问题都要处理到位，形成闭环。", "target_word": "闭环", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地铁环线是闭环，不用换车也能回到原站。", "target_word": "闭环", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个设计让水在管子里形成闭环，循环使用。", "target_word": "闭环", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的故事有开头，也有结尾，是一个完整的闭环。", "target_word": "闭环", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条小路绕湖一圈，成了闭环。", "target_word": "闭环", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学习要有闭环：学、练、查、改。", "target_word": "闭环", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂的管理有闭环，每个步骤都能查到。", "target_word": "闭环", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "闭环管理", "label": "复合"}, {"form": "闭环系统", "label": "复合"}, {"form": "閉環", "label": "繁体"}], "register": "书面", "sense_fingerprint": "闭环：首尾相接、回到起点的环形或完整流程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebfe7736-19f5-4660-8550-caa3fb9fd6f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25654, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "闭环", "is_correct": true, "explanation": "闭环：首尾相接、回到起点的环形，与“连成”“电流才能通过”相合。"}, {"text": "花朵", "is_correct": false, "explanation": "语义：花朵不能由电路连成，与“电路”“电流”的语境不相合。"}, {"text": "树枝", "is_correct": false, "explanation": "语义：树枝是植物的部分，与电路的连接无关。"}, {"text": "诗句", "is_correct": false, "explanation": "语义：“诗句”不是电路的结构，“电路连成诗句”搭配不通，句子不通。"}], "explanations": {"闭环": "闭环：首尾相接、回到起点的环形，与“连成”“电流才能通过”相合。", "花朵": "语义：花朵不能由电路连成，与“电路”“电流”的语境不相合。", "树枝": "语义：树枝是植物的部分，与电路的连接无关。", "诗句": "语义：“诗句”不是电路的结构，“电路连成诗句”搭配不通，句子不通。"}, "sentence_index": 0, "correct_answer": "闭环"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我很喜欢这里的闭环，安静又干净。", "explanation": "这里误用了〈闭环〉。闭环指首尾相连的环形结构，不能用来形容环境；这里应该用〈环境〉。"}, {"text": "这扇门闭环得很紧，风都吹不进来。", "explanation": "这里误用了〈闭环〉。闭环指首尾相接的结构，不表示关闭；这里应该用〈闭合〉。"}, {"text": "他是一个闭环，很容易相处。", "explanation": "这里误用了〈闭环〉。闭环是结构或流程，不能用来指人，应说〈随和的人〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02226a68-658a-4356-821b-8a8997342f34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25654, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "闭环", "is_correct": true, "explanation": "闭环：首尾相接的完整结构，与“有开头，也有结尾”的语境相合。"}, {"text": "雨点", "is_correct": false, "explanation": "语义：雨点是降水的小滴，不能指一个有开头和结尾的故事。"}, {"text": "梯子", "is_correct": false, "explanation": "语义：梯子是器具，不能用来比喻故事的完整性。"}, {"text": "饭菜", "is_correct": false, "explanation": "搭配：“饭菜”不说“一个完整的”（应说“一顿”），也不能指故事。"}], "explanations": {"闭环": "闭环：首尾相接的完整结构，与“有开头，也有结尾”的语境相合。", "雨点": "语义：雨点是降水的小滴，不能指一个有开头和结尾的故事。", "梯子": "语义：梯子是器具，不能用来比喻故事的完整性。", "饭菜": "搭配：“饭菜”不说“一个完整的”（应说“一顿”），也不能指故事。"}, "sentence_index": 6, "correct_answer": "闭环"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场比赛晚上闭环，观众陆续离场。", "explanation": "这里误用了〈闭环〉。闭环指首尾相连的结构，不表示活动结束；这里应该用〈闭幕〉。"}, {"text": "这首诗的闭环很和谐，读起来很顺口。", "explanation": "这里误用了〈闭环〉。闭环指环形结构，不能用来形容诗的节奏；这里应该用〈韵律〉。"}, {"text": "妈妈做的闭环很香，我吃了两碗。", "explanation": "这里误用了〈闭环〉。闭环是结构，不能当作食物；这里应该用〈饭菜〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02226a68-658a-4356-821b-8a8997342f34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25654, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次改革让整个流程形成了一根闭环。", "corrected_sentence": "这次改革让整个流程形成了一个闭环。", "error_description": "“闭环”前的量词用错了。“根”用于细长的条状物，不能用来数闭环，应说“一个闭环”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02226a68-658a-4356-821b-8a8997342f34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25654, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这项改革最终形成了一只闭环。", "corrected_sentence": "这项改革最终形成了一个闭环。", "error_description": "量词错误：“闭环”是抽象的结构，不能用“只”来数（“只”多用于动物等个体事物）。应说“一个闭环”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02226a68-658a-4356-821b-8a8997342f34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
