INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25662, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "树上掉下来的叶子。", "primary_collocate": null, "pronunciation": "luò yè", "ipa": "lwo˥˩ jɛ˥˩", "syllable_count": 2, "sentences": [{"text": "秋天到了，地上有很多落叶。", "target_word": "落叶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风一吹，落叶在空中飞来飞去。", "target_word": "落叶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我捡了几片漂亮的落叶。", "target_word": "落叶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人每天早上扫公园里的落叶。", "target_word": "落叶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小河上漂着一片黄色的落叶。", "target_word": "落叶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在落叶上跑来跑去。", "target_word": "落叶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把落叶夹在书里当书签。", "target_word": "落叶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "落叶慢慢地落在她的肩上。", "target_word": "落叶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨后，路上的落叶湿湿的。", "target_word": "落叶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢踩着落叶走路，听沙沙的声音。", "target_word": "落叶", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "落葉", "label": "繁体"}, {"form": "片", "label": "量词"}, {"form": "一片落叶", "label": "量词"}], "register": "中性", "sense_fingerprint": "从树上掉落的叶子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12f9422c-71d5-4159-b92d-1d18b93b36af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25662, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "雪花", "is_correct": false, "explanation": "语义：秋天一般不下雪，“雪花”与“秋天到了”矛盾。"}, {"text": "落叶", "is_correct": true, "explanation": "正确。“落叶”指秋天掉在地上的叶子，与句中的时令和“地上”相符。"}, {"text": "春芽", "is_correct": false, "explanation": "语义：“春芽”在春天长出，与“秋天到了”的时令矛盾。"}, {"text": "热浪", "is_correct": false, "explanation": "语义：“热浪”指夏天的高温气流，与“秋天到了”的时令矛盾，且“地上有很多热浪”不成立。"}], "explanations": {"雪花": "语义：秋天一般不下雪，“雪花”与“秋天到了”矛盾。", "落叶": "正确。“落叶”指秋天掉在地上的叶子，与句中的时令和“地上”相符。", "春芽": "语义：“春芽”在春天长出，与“秋天到了”的时令矛盾。", "热浪": "语义：“热浪”指夏天的高温气流，与“秋天到了”的时令矛盾，且“地上有很多热浪”不成立。"}, "sentence_index": 0, "correct_answer": "落叶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "春天，枝头长出了很多落叶。", "explanation": "这里应该用〈嫩叶〉。“落叶”指已经从树上掉下来的叶子，长在枝头的要说“嫩叶”。"}, {"text": "他摘了一片嫩绿的落叶。", "explanation": "这里应该用〈叶子〉。“落叶”已经掉落，摘下的是仍长在树上的叶子，应说“叶子”。"}, {"text": "这片落叶还连在树枝上，绿绿的，正在慢慢长大。", "explanation": "这里应该用〈绿叶〉。“落叶”已经脱离树枝，不能指仍连在枝上、还在生长的叶子，要用“绿叶”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe4d3447-d802-4dcc-982d-cc53a9016261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25662, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "哑铃", "is_correct": false, "explanation": "配价：“夹”要求扁平、轻薄的东西作宾语，“哑铃”太厚重，不能夹进书里。"}, {"text": "落叶", "is_correct": true, "explanation": "正确。“落叶”扁平轻薄，夹在书里当书签很自然，与句意相符。"}, {"text": "烟花", "is_correct": false, "explanation": "语义：“烟花”是要燃放的东西，夹在书里当书签不合常理。"}, {"text": "冰块", "is_correct": false, "explanation": "语义：“冰块”会融化，不能夹在书里当书签。"}], "explanations": {"哑铃": "配价：“夹”要求扁平、轻薄的东西作宾语，“哑铃”太厚重，不能夹进书里。", "落叶": "正确。“落叶”扁平轻薄，夹在书里当书签很自然，与句意相符。", "烟花": "语义：“烟花”是要燃放的东西，夹在书里当书签不合常理。", "冰块": "语义：“冰块”会融化，不能夹在书里当书签。"}, "sentence_index": 6, "correct_answer": "落叶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "院子里有一辆落叶，被风吹着滚来滚去。", "explanation": "这里应该用〈一片〉。量词“辆”用于车，落叶要用“片”。"}, {"text": "公园的小路上铺着一座落叶。", "explanation": "这里应该用〈一层〉。量词“座”用于山、桥、房屋等大型物体，落叶要用“层”。"}, {"text": "树下躺着一只落叶，很安静。", "explanation": "这里应该用〈一片〉。量词“只”多用于动物或成对物品中的单个，落叶要用“片”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe4d3447-d802-4dcc-982d-cc53a9016261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25662, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在台阶上捡到一个落叶。", "corrected_sentence": "我在台阶上捡到一片落叶。", "error_description": "量词错误：“落叶”前应用“片”，写成“一个落叶”不地道。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe4d3447-d802-4dcc-982d-cc53a9016261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25662, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在书里夹了一条落叶。", "corrected_sentence": "我在书里夹了一片落叶。", "error_description": "量词错误：“落叶”应搭配量词“片”，“条”多用于细长的东西，不能用于落叶。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe4d3447-d802-4dcc-982d-cc53a9016261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25664, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "拔", "is_correct": true, "explanation": "拔：拔出，与“刺入”方向相反，构成反义。"}, {"text": "看", "is_correct": false, "explanation": "看：观看，与“扎”的意思无关，不构成反义。"}, {"text": "唱", "is_correct": false, "explanation": "唱：发出歌声，与“扎”的意思无关，不构成反义。"}, {"text": "走", "is_correct": false, "explanation": "走：移动脚步，与“扎”的意思无关，不构成反义。"}], "correct_answer": "拔", "explanations": {"拔": "拔：拔出，与“刺入”方向相反，构成反义。", "看": "看：观看，与“扎”的意思无关，不构成反义。", "唱": "唱：发出歌声，与“扎”的意思无关，不构成反义。", "走": "走：移动脚步，与“扎”的意思无关，不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0defd26-0587-41c1-b427-02bf228d33be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25664, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "拔", "is_correct": true, "explanation": "拔：拔出，与“刺进去”方向相反，构成反义。"}, {"text": "喝", "is_correct": false, "explanation": "喝：饮用液体，与“扎”的意思无关，不构成反义。"}, {"text": "跑", "is_correct": false, "explanation": "跑：快速移动，与“扎”的意思无关，不构成反义。"}, {"text": "写", "is_correct": false, "explanation": "写：用笔记录文字，与“扎”的意思无关，不构成反义。"}], "correct_answer": "拔", "explanations": {"拔": "拔：拔出，与“刺进去”方向相反，构成反义。", "喝": "喝：饮用液体，与“扎”的意思无关，不构成反义。", "跑": "跑：快速移动，与“扎”的意思无关，不构成反义。", "写": "写：用笔记录文字，与“扎”的意思无关，不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0defd26-0587-41c1-b427-02bf228d33be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25664, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用尖的东西刺进去。", "primary_collocate": null, "pronunciation": "zhā", "ipa": "ʈʂa⁵⁵", "syllable_count": 1, "sentences": [{"text": "他用针扎破了气球。", "target_word": "扎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小心点，玫瑰的刺会扎到手。", "target_word": "扎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你用筷子在鱼身上扎一下，看看熟了没有。", "target_word": "扎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "仙人掌扎了我的手指。", "target_word": "扎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用牙签扎了一个小番茄。", "target_word": "扎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子拿着小棍子，在沙地上扎了几个洞。", "target_word": "扎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一根铁丝扎进了他的手心。", "target_word": "扎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在纸上扎了几个小洞，做成星星。", "target_word": "扎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蒸红薯以前，先用叉子扎几下。", "target_word": "扎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈用针在布上扎了一个小孔，准备缝衣服。", "target_word": "扎", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "扎了", "label": "完成体"}, {"form": "扎过", "label": "经历体"}, {"form": "扎着", "label": "持续体"}], "register": "中性", "sense_fingerprint": "用尖的东西刺进去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f52a17a-78f7-4fb3-bb7f-3ca4d49b212e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25664, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "扎", "is_correct": true, "explanation": "扎 zhā（第一声）：用尖的东西刺进去。"}, {"text": "炸", "is_correct": false, "explanation": "zhà（第四声）与 zhā（第一声）声调不同，炸的意思是油炸或爆炸。"}, {"text": "眨", "is_correct": false, "explanation": "zhǎ（第三声）与 zhā（第一声）声调不同，眨的意思是眨眼。"}, {"text": "沙", "is_correct": false, "explanation": "shā 与 zhā 声母不同（sh 与 zh），沙的意思是沙子。"}, {"text": "札", "is_correct": false, "explanation": "zhá（第二声）与 zhā（第一声）声调不同，札的意思是信札。"}], "explanations": {"扎": "扎 zhā（第一声）：用尖的东西刺进去。", "炸": "zhà（第四声）与 zhā（第一声）声调不同，炸的意思是油炸或爆炸。", "眨": "zhǎ（第三声）与 zhā（第一声）声调不同，眨的意思是眨眼。", "沙": "shā 与 zhā 声母不同（sh 与 zh），沙的意思是沙子。", "札": "zhá（第二声）与 zhā（第一声）声调不同，札的意思是信札。"}, "sentence_index": null, "correct_answer": "扎"}, "level_3": {"options": [{"text": "扎", "is_correct": true, "explanation": "扎：用尖的东西刺破，与“气球”相符，符合句意。"}, {"text": "挂", "is_correct": false, "explanation": "语义：“挂”指悬挂，不能用来说弄破气球。"}, {"text": "贴", "is_correct": false, "explanation": "搭配：“贴”配的是纸张、标签，“用针贴破气球”不成立。"}, {"text": "摸", "is_correct": false, "explanation": "语义：“摸”只是触碰，不会把气球弄破。"}], "explanations": {"扎": "扎：用尖的东西刺破，与“气球”相符，符合句意。", "挂": "语义：“挂”指悬挂，不能用来说弄破气球。", "贴": "搭配：“贴”配的是纸张、标签，“用针贴破气球”不成立。", "摸": "语义：“摸”只是触碰，不会把气球弄破。"}, "sentence_index": 0, "correct_answer": "扎"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈把鲜花扎进了花瓶里。", "explanation": "这里应该用〈插〉。插指把细长的东西放进容器或空隙中；扎强调尖锐物刺入，鲜花不是尖锐物，用“扎”不符合说法。"}, {"text": "他用力扎了一下开关，灯却没亮。", "explanation": "这里应该用〈按〉。按指用手指或手掌用力压下；扎强调尖锐物刺入，按开关不是刺入，不能用“扎”。"}, {"text": "她用力扎了一下湿毛巾，把水挤了出来。", "explanation": "这里应该用〈拧〉。拧指用力转动挤压；扎强调尖锐物刺入，毛巾不是尖锐物，不能用“扎”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0defd26-0587-41c1-b427-02bf228d33be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25664, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "扎", "is_correct": true, "explanation": "扎 zhā（第一声）：用尖的东西刺进去。"}, {"text": "诈", "is_correct": false, "explanation": "zhà（第四声）与 zhā（第一声）声调不同，诈的意思是欺骗。"}, {"text": "闸", "is_correct": false, "explanation": "zhá（第二声）与 zhā（第一声）声调不同，闸的意思是闸门。"}, {"text": "纱", "is_correct": false, "explanation": "shā 与 zhā 声母不同（sh 与 zh），纱的意思是纱布或纱线。"}, {"text": "刹", "is_correct": false, "explanation": "shā 与 zhā 声母不同（sh 与 zh），刹的意思是刹车。"}], "explanations": {"扎": "扎 zhā（第一声）：用尖的东西刺进去。", "诈": "zhà（第四声）与 zhā（第一声）声调不同，诈的意思是欺骗。", "闸": "zhá（第二声）与 zhā（第一声）声调不同，闸的意思是闸门。", "纱": "shā 与 zhā 声母不同（sh 与 zh），纱的意思是纱布或纱线。", "刹": "shā 与 zhā 声母不同（sh 与 zh），刹的意思是刹车。"}, "sentence_index": null, "correct_answer": "扎"}, "level_3": {"options": [{"text": "扎", "is_correct": true, "explanation": "扎：尖的铁丝刺入手心，符合句意。"}, {"text": "嚼", "is_correct": false, "explanation": "语义：“嚼”指咀嚼食物，铁丝不能被嚼进手心。"}, {"text": "绣", "is_correct": false, "explanation": "搭配：“绣”配的是布料和图案，不能说绣进手心。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，不能说吃进手心。"}], "explanations": {"扎": "扎：尖的铁丝刺入手心，符合句意。", "嚼": "语义：“嚼”指咀嚼食物，铁丝不能被嚼进手心。", "绣": "搭配：“绣”配的是布料和图案，不能说绣进手心。", "吃": "语义：“吃”指进食，不能说吃进手心。"}, "sentence_index": 6, "correct_answer": "扎"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用力扎开了门，冲了出去。", "explanation": "这里应该用〈推〉。推指用力使门等物体移动；扎强调尖锐物刺入，推门不能用“扎”。"}, {"text": "小朋友用手指扎了扎蛋糕，看看软不软。", "explanation": "这里应该用〈戳〉。戳指用手指或尖物轻轻碰、刺；扎强调尖锐物用力刺入，用手指轻轻戳蛋糕不能用“扎”。"}, {"text": "妈妈扎来一碗热汤，放在桌上。", "explanation": "这里应该用〈端〉。端指用手托着拿东西；扎强调尖锐物刺入，端碗不能用“扎”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0defd26-0587-41c1-b427-02bf228d33be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25664, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这根竹签扎很深，拔了半天才拔出来。", "corrected_sentence": "这根竹签扎得很深，拔了半天才拔出来。", "error_description": "程度补语错误：表示程度的补语要用“扎得很深”，“得”不能省略，写成“扎很深”不对。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0defd26-0587-41c1-b427-02bf228d33be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25664, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我昨天被仙人掌扎着手指。", "corrected_sentence": "我昨天被仙人掌扎了手指。", "error_description": "体标用错：昨天已经完成的动作要用“了”，说“扎了手指”；“着”表示持续，不能用在这里。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0defd26-0587-41c1-b427-02bf228d33be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
