INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25666, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da070831-f616-4c04-9f21-0dd2245724fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25666, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "茶树上的叶子，可以用来泡水喝。", "primary_collocate": null, "pronunciation": "chá yè", "ipa": "ʈʂʰa˧˥ jɛ˥˩", "syllable_count": 2, "sentences": [{"text": "茶叶是茶树上的叶子。", "target_word": "茶叶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请给我一点茶叶。", "target_word": "茶叶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他往杯子里放了一些茶叶。", "target_word": "茶叶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些茶叶是我自己种的。", "target_word": "茶叶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "茶叶的香味很好闻。", "target_word": "茶叶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把茶叶倒进了茶壶里。", "target_word": "茶叶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "茶农正在山上摘茶叶。", "target_word": "茶叶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "茶叶放久了就没有香味了。", "target_word": "茶叶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥送了我一罐茶叶。", "target_word": "茶叶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "喝完茶，别把茶叶倒进水池。", "target_word": "茶叶", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一包茶叶", "label": "量词"}, {"form": "一片茶叶", "label": "量词"}, {"form": "茶葉", "label": "繁体"}], "register": "中性", "sense_fingerprint": "茶树的叶子，可泡水喝", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e3475a8-bec8-456e-a0b2-f4294a76f115') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25666, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "花朵", "is_correct": false, "explanation": "语义：花朵不是叶子，“是茶树上的叶子”的说法与它不符。"}, {"text": "果实", "is_correct": false, "explanation": "语义：果实不是叶子，与“茶树上的叶子”的定义冲突。"}, {"text": "茶叶", "is_correct": true, "explanation": "茶叶指茶树上的叶子，可以用来泡水喝，符合句意。"}, {"text": "茶壶", "is_correct": false, "explanation": "语义：茶壶是泡茶的器具，不长在茶树上，不是叶子。"}], "explanations": {"花朵": "语义：花朵不是叶子，“是茶树上的叶子”的说法与它不符。", "果实": "语义：果实不是叶子，与“茶树上的叶子”的定义冲突。", "茶叶": "茶叶指茶树上的叶子，可以用来泡水喝，符合句意。", "茶壶": "语义：茶壶是泡茶的器具，不长在茶树上，不是叶子。"}, "sentence_index": 0, "correct_answer": "茶叶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家院子里的茶叶每年秋天都结出一串串果子。", "explanation": "这里应该用〈茶树〉。结果子的是茶树；茶叶是采下来的叶子，不会结果子。"}, {"text": "我把茶叶插在花瓶里，每天给它浇水。", "explanation": "这里应该用〈花〉。插在花瓶里浇水的是鲜花；茶叶是采下来泡水喝的叶子。"}, {"text": "这个孩子把茶叶当成零食，一口一口吃。", "explanation": "这里应该用〈糖果〉。零食是可以直接吃的食品；茶叶是干叶子，要泡水喝，不能直接吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da070831-f616-4c04-9f21-0dd2245724fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25666, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "电视", "is_correct": false, "explanation": "搭配：“摘”用于果实、叶子等可摘取的东西，不说“摘电视”。"}, {"text": "茶叶", "is_correct": true, "explanation": "茶叶是茶树上可以摘下的嫩叶，“摘茶叶”搭配自然，符合句意。"}, {"text": "钢琴", "is_correct": false, "explanation": "搭配：钢琴是乐器，不能用“摘”，不说“摘钢琴”。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是植物，不能被摘下，与句意不符。"}], "explanations": {"电视": "搭配：“摘”用于果实、叶子等可摘取的东西，不说“摘电视”。", "茶叶": "茶叶是茶树上可以摘下的嫩叶，“摘茶叶”搭配自然，符合句意。", "钢琴": "搭配：钢琴是乐器，不能用“摘”，不说“摘钢琴”。", "石头": "语义：石头不是植物，不能被摘下，与句意不符。"}, "sentence_index": 6, "correct_answer": "茶叶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天下午都直接喝茶叶，不用泡。", "explanation": "这里应该用〈茶水〉。“喝”的是泡好的茶水；茶叶是干叶子，要先用热水泡开，不能直接喝。"}, {"text": "游客们在茶叶里散步。", "explanation": "这里应该用〈茶园〉。散步的场所是茶园；茶叶是采下的叶子，不是可以散步的地方。"}, {"text": "他用茶叶给手机充电。", "explanation": "这里应该用〈充电器〉。给手机充电要用充电器；茶叶是泡水喝的叶子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da070831-f616-4c04-9f21-0dd2245724fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25666, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈正在茶树下摘了茶叶。", "corrected_sentence": "妈妈正在茶树下摘茶叶。", "error_description": "错误：“正在”后又加了“了”。“正在”表示动作进行中，与表示完成的“了”不能同用，应说“正在摘茶叶”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da070831-f616-4c04-9f21-0dd2245724fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25666, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她给我带了一只茶叶。", "corrected_sentence": "她给我带了一些茶叶。", "error_description": "错误：“茶叶”应用“些”“包”“罐”等计量，不能用“只”（“只”多用于单个物件或动物）。正确：“一些茶叶”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da070831-f616-4c04-9f21-0dd2245724fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
