INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25668, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "塑料桶是一种用塑料做的桶，可以用来装东西。", "primary_collocate": null, "pronunciation": "sù liào tǒng", "ipa": "su˥˩ liɑʊ˥˩ tʰʊŋ˨˩˦", "syllable_count": 3, "sentences": [{"text": "请把这些旧衣服装进塑料桶。", "target_word": "塑料桶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "塑料桶不会生锈，所以很多人喜欢用。", "target_word": "塑料桶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边的孩子用塑料桶玩沙子。", "target_word": "塑料桶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把塑料桶倒过来，当成小凳子坐。", "target_word": "塑料桶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个塑料桶能装二十升水。", "target_word": "塑料桶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房角落有一个大塑料桶，里面是大米。", "target_word": "塑料桶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "塑料桶破了一个洞，水都漏光了。", "target_word": "塑料桶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买两个塑料桶，一个装油，一个装醋。", "target_word": "塑料桶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "塑料桶里的水满得快要流出来了。", "target_word": "塑料桶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗车时，叔叔用塑料桶提水。", "target_word": "塑料桶", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个塑料桶", "label": "量词"}, {"form": "塑料水桶", "label": "复合"}], "register": "中性", "sense_fingerprint": "用塑料做的、可以装东西的桶", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e578585e-97ef-488a-a6d8-09a2c5e452b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25668, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "塑料桶", "is_correct": true, "explanation": "正确：“装进”的宾语需要能盛放东西的容器，塑料桶合适。"}, {"text": "大海", "is_correct": false, "explanation": "语义：大海不是容器，不能说把旧衣服“装进”大海。"}, {"text": "信纸", "is_correct": false, "explanation": "语义：信纸是薄纸，不是容器，旧衣服不能“装进”信纸。"}, {"text": "盘子", "is_correct": false, "explanation": "语义：盘子又浅又小，不能用来装这些旧衣服。"}], "explanations": {"塑料桶": "正确：“装进”的宾语需要能盛放东西的容器，塑料桶合适。", "大海": "语义：大海不是容器，不能说把旧衣服“装进”大海。", "信纸": "语义：信纸是薄纸，不是容器，旧衣服不能“装进”信纸。", "盘子": "语义：盘子又浅又小，不能用来装这些旧衣服。"}, "sentence_index": 0, "correct_answer": "塑料桶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天买了一张塑料桶，放在厨房门口。", "explanation": "这里应该用〈个〉。〈张〉用于纸、桌子等平面的东西，塑料桶要用〈个〉。"}, {"text": "爸爸修车时，用一条塑料桶装机油。", "explanation": "这里应该用〈个〉。〈条〉用于细长的东西，塑料桶要用〈个〉。"}, {"text": "小区门口新放了一辆塑料桶。", "explanation": "这里应该用〈个〉。〈辆〉用于车辆，塑料桶要用〈个〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4513d81-d5d4-4976-9efd-794037144f6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25668, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "塑料桶", "is_correct": true, "explanation": "正确：盛水的塑料桶破了洞，水才会漏光。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞不是盛水的容器，破了洞也不会让水“漏光”。"}, {"text": "饼干", "is_correct": false, "explanation": "搭配：“漏光”指液体流走，饼干不是液体容器，不能搭配“漏光”。"}, {"text": "树叶", "is_correct": false, "explanation": "语义：树叶不是盛放液体的器具，破洞后水不会“漏光”。"}], "explanations": {"塑料桶": "正确：盛水的塑料桶破了洞，水才会漏光。", "雨伞": "语义：雨伞不是盛水的容器，破了洞也不会让水“漏光”。", "饼干": "搭配：“漏光”指液体流走，饼干不是液体容器，不能搭配“漏光”。", "树叶": "语义：树叶不是盛放液体的器具，破洞后水不会“漏光”。"}, "sentence_index": 6, "correct_answer": "塑料桶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "门口摆着一座塑料桶。", "explanation": "这里应该用〈个〉。〈座〉用于山、桥、楼房等大型固定的东西，塑料桶要用〈个〉。"}, {"text": "他的书包里装着一支塑料桶。", "explanation": "这里应该用〈个〉。〈支〉用于笔、枪等细长的物件，塑料桶要用〈个〉。"}, {"text": "桌上放着一根塑料桶。", "explanation": "这里应该用〈个〉。〈根〉用于细长条的东西，塑料桶要用〈个〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4513d81-d5d4-4976-9efd-794037144f6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25668, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工地上堆着两本塑料桶。", "corrected_sentence": "工地上堆着两个塑料桶。", "error_description": "量词错误：塑料桶的量词应为“个”，“本”用于书册，应改为“两个塑料桶”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4513d81-d5d4-4976-9efd-794037144f6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25668, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "门口放着三条塑料桶。", "corrected_sentence": "门口放着三个塑料桶。", "error_description": "量词错误：塑料桶的量词应为“个”，“条”用于细长的东西，应改为“三个塑料桶”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4513d81-d5d4-4976-9efd-794037144f6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
