INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25672, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "蛋壳是鸡蛋外面硬硬的那一层。", "primary_collocate": null, "pronunciation": "dàn ké", "ipa": "tan˥˩ kʰɤ˧˥", "syllable_count": 2, "sentences": [{"text": "吃完鸡蛋，桌上留下了一堆蛋壳。", "target_word": "蛋壳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蛋壳白白的，摸起来又硬又滑。", "target_word": "蛋壳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸡啄破蛋壳，走进了新世界。", "target_word": "蛋壳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把蛋壳轻轻压碎，撒在菜地里。", "target_word": "蛋壳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蛋壳太薄了，一拿就裂开了。", "target_word": "蛋壳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在蛋壳上画了一张笑脸。", "target_word": "蛋壳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "煎蛋的时候，小心别让蛋壳掉进锅里。", "target_word": "蛋壳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蛋壳碎了，蛋清流到了手上。", "target_word": "蛋壳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶说，蛋壳洗干净后可以养花。", "target_word": "蛋壳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "复活节时，孩子们在蛋壳上涂上颜色。", "target_word": "蛋壳", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个蛋壳", "label": "量词"}, {"form": "鸡蛋壳", "label": "复合"}], "register": "中性", "sense_fingerprint": "鸡蛋外面硬硬的一层", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e578585e-97ef-488a-a6d8-09a2c5e452b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25672, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "蛋壳", "is_correct": true, "explanation": "正确答案：蛋壳（dàn ké）是鸡蛋外面硬硬的那一层。"}, {"text": "党课", "is_correct": false, "explanation": "党课（dǎng kè）：dǎng 比 dàn 多后鼻音 -ng，声调也不同，意思是关于党的课程。"}, {"text": "单科", "is_correct": false, "explanation": "单科（dān kē）：与 dàn ké 音段相同，两个音节声调都不同，只能靠声调区分，意思是某一门学科。"}, {"text": "蛋盒", "is_correct": false, "explanation": "蛋盒（dàn hé）：hé 与 ké 声母不同（h/k），意思是装鸡蛋的盒子。"}], "explanations": {"蛋壳": "正确答案：蛋壳（dàn ké）是鸡蛋外面硬硬的那一层。", "党课": "党课（dǎng kè）：dǎng 比 dàn 多后鼻音 -ng，声调也不同，意思是关于党的课程。", "单科": "单科（dān kē）：与 dàn ké 音段相同，两个音节声调都不同，只能靠声调区分，意思是某一门学科。", "蛋盒": "蛋盒（dàn hé）：hé 与 ké 声母不同（h/k），意思是装鸡蛋的盒子。"}, "sentence_index": null, "correct_answer": "蛋壳"}, "level_3": {"options": [{"text": "蛋壳", "is_correct": true, "explanation": "蛋壳是吃鸡蛋后留下的硬壳，符合“吃完鸡蛋，桌上留下了一堆”。"}, {"text": "蛋清", "is_correct": false, "explanation": "搭配：“一堆”只配可以堆起来的固体，蛋清是液体，不说“一堆蛋清”。"}, {"text": "鸡毛", "is_correct": false, "explanation": "语义：鸡蛋上没有鸡毛，吃完鸡蛋不会留下鸡毛。"}, {"text": "鸡骨头", "is_correct": false, "explanation": "语义：鸡蛋里没有骨头，吃完鸡蛋不会留下鸡骨头。"}], "explanations": {"蛋壳": "蛋壳是吃鸡蛋后留下的硬壳，符合“吃完鸡蛋，桌上留下了一堆”。", "蛋清": "搭配：“一堆”只配可以堆起来的固体，蛋清是液体，不说“一堆蛋清”。", "鸡毛": "语义：鸡蛋上没有鸡毛，吃完鸡蛋不会留下鸡毛。", "鸡骨头": "语义：鸡蛋里没有骨头，吃完鸡蛋不会留下鸡骨头。"}, "sentence_index": 0, "correct_answer": "蛋壳"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把蛋壳打发成奶油状，做成了蛋糕。", "explanation": "这里应该用〈蛋白〉。蛋壳是硬壳，打不出奶油状的泡沫；做蛋糕要打发的是蛋白。"}, {"text": "他每天早上吃两个蛋壳。", "explanation": "这里应该用〈鸡蛋〉。蛋壳是硬壳，不能当早餐吃。"}, {"text": "厨房的桌上放着一根蛋壳。", "explanation": "这里应该用〈片〉。蛋壳是薄片，“根”只用于细长的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4513d81-d5d4-4976-9efd-794037144f6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25672, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "蛋壳", "is_correct": true, "explanation": "蛋壳是坚硬的薄壳，煎蛋时掉进锅里是可能发生的，符合语境。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不会掉进锅里，与“煎蛋的时候”的语境矛盾。"}, {"text": "电视", "is_correct": false, "explanation": "搭配：“掉进锅里”的多是小件食材或碎屑，电视这样的大件不搭配这一说法。"}, {"text": "砖头", "is_correct": false, "explanation": "语义：砖头不会掉进煎蛋的锅里，与语境不符。"}], "explanations": {"蛋壳": "蛋壳是坚硬的薄壳，煎蛋时掉进锅里是可能发生的，符合语境。", "窗户": "语义：窗户不会掉进锅里，与“煎蛋的时候”的语境矛盾。", "电视": "搭配：“掉进锅里”的多是小件食材或碎屑，电视这样的大件不搭配这一说法。", "砖头": "语义：砖头不会掉进煎蛋的锅里，与语境不符。"}, "sentence_index": 6, "correct_answer": "蛋壳"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把蛋壳加进面粉里，搅成面团。", "explanation": "这里应该用〈蛋黄〉。蛋壳是硬壳，不能和面粉搅成面团。"}, {"text": "妈妈用蛋壳把菜卷起来，蒸着吃。", "explanation": "这里应该用〈蛋皮〉。蛋皮是摊成的薄蛋饼，可以卷东西；蛋壳太硬，卷不起来。"}, {"text": "妈妈把蛋壳刷在饼上，烤得金黄。", "explanation": "这里应该用〈蛋清〉。蛋清是液体，可以刷在饼上；蛋壳是硬壳，刷不上去。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4513d81-d5d4-4976-9efd-794037144f6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25672, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他收集了许多蛋壳们。", "corrected_sentence": "他收集了许多蛋壳。", "error_description": "复数标记错误：“们”只加在指人的名词后，蛋壳是物，不能说“蛋壳们”，应说“许多蛋壳”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4513d81-d5d4-4976-9efd-794037144f6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25672, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "桌上有一本蛋壳。", "corrected_sentence": "桌上有一个蛋壳。", "error_description": "量词错误：蛋壳不用“本”，“本”用于书册，应说“一个蛋壳”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4513d81-d5d4-4976-9efd-794037144f6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25674, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0defd26-0587-41c1-b427-02bf228d33be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25674, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0defd26-0587-41c1-b427-02bf228d33be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25674, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "东西坏了，有难闻的气味。", "primary_collocate": null, "pronunciation": "fā chòu", "ipa": "fa⁵⁵ ʈʂʰou̯⁵¹", "syllable_count": 2, "sentences": [{"text": "厨房的垃圾没有倒，已经发臭了。", "target_word": "发臭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气太热，菜放一晚上就发臭。", "target_word": "发臭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这碗汤发臭了，别喝了。", "target_word": "发臭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水沟里的水发臭，蚊子也很多。", "target_word": "发臭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的运动鞋好久没洗，开始发臭。", "target_word": "发臭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虾不放进冰箱，很快就会发臭。", "target_word": "发臭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过期的豆腐发臭了，倒掉吧。", "target_word": "发臭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鞋子湿着放在鞋柜里，很容易发臭。", "target_word": "发臭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "垃圾车来晚了，路边的垃圾都发臭了。", "target_word": "发臭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你闻，这个盒子里的肉是不是发臭了？", "target_word": "发臭", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "发臭了", "label": "完成体"}, {"form": "发臭过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "东西坏了散发难闻气味", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f52a17a-78f7-4fb3-bb7f-3ca4d49b212e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25674, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发臭", "is_correct": true, "explanation": "发臭：垃圾没倒而腐坏，散发臭味，与句意相符。"}, {"text": "发芽", "is_correct": false, "explanation": "语义：“发芽”指植物长出芽，垃圾不会发芽。"}, {"text": "生锈", "is_correct": false, "explanation": "搭配：“生锈”只用于金属，垃圾不能说生锈。"}, {"text": "开花", "is_correct": false, "explanation": "语义：“开花”指植物开放，与垃圾腐坏无关。"}], "explanations": {"发臭": "发臭：垃圾没倒而腐坏，散发臭味，与句意相符。", "发芽": "语义：“发芽”指植物长出芽，垃圾不会发芽。", "生锈": "搭配：“生锈”只用于金属，垃圾不能说生锈。", "开花": "语义：“开花”指植物开放，与垃圾腐坏无关。"}, "sentence_index": 0, "correct_answer": "发臭"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "院子里的花发臭了，香味很好闻。", "explanation": "这里应该用〈开〉。“花开了”才会有好闻的香味；发臭指东西坏了有难闻的气味，与“香味很好闻”矛盾。"}, {"text": "风一吹，树叶都发臭了。", "explanation": "这里应该用〈掉〉。风吹树叶，树叶会掉下来；发臭指东西坏了有难闻的气味，与风吹无关。"}, {"text": "教室里的铃声发臭了。", "explanation": "这里应该用〈响起〉。响起指声音发出来；发臭只指东西腐败后有臭味，不能用于声音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0defd26-0587-41c1-b427-02bf228d33be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25674, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发臭", "is_correct": true, "explanation": "发臭：豆腐过期后变质，散发臭味，与“倒掉吧”的语境相符。"}, {"text": "发亮", "is_correct": false, "explanation": "语义：“发亮”指发光，与豆腐变质无关。"}, {"text": "长高", "is_correct": false, "explanation": "搭配：“长高”不能用于豆腐。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：“唱歌”指发出歌声，与豆腐过期无关，句子不通。"}], "explanations": {"发臭": "发臭：豆腐过期后变质，散发臭味，与“倒掉吧”的语境相符。", "发亮": "语义：“发亮”指发光，与豆腐变质无关。", "长高": "搭配：“长高”不能用于豆腐。", "唱歌": "语义：“唱歌”指发出歌声，与豆腐过期无关，句子不通。"}, "sentence_index": 6, "correct_answer": "发臭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一进门，咖啡的香味发臭而来。", "explanation": "这里应该用〈扑鼻〉。扑鼻形容香味直冲鼻子；发臭只指东西腐败后有臭味，不能形容香味。"}, {"text": "天黑了，路灯都发臭了。", "explanation": "这里应该用〈亮〉。天黑后路灯会亮；发臭指东西坏了有难闻的气味，不能用于灯。"}, {"text": "太阳出来了，雪人发臭了。", "explanation": "这里应该用〈化〉。太阳一晒，雪人会化；发臭指东西坏了有难闻的气味，雪人不会发臭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0defd26-0587-41c1-b427-02bf228d33be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25674, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "厨房的垃圾两天没倒，已经很发臭了。", "corrected_sentence": "厨房的垃圾两天没倒，已经发臭了。", "error_description": "程度副词误加：“发臭”是动词，前面不能加“很”，应说“已经发臭了”，不说“很发臭”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0defd26-0587-41c1-b427-02bf228d33be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25674, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这双旧袜子湿着放在鞋柜里，很容易发臭地。", "corrected_sentence": "这双旧袜子湿着放在鞋柜里，很容易发臭。", "error_description": "多余的“地”：“地”用于状语后修饰动词，不能加在句末的“发臭”后面，应删去，说“很容易发臭”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0defd26-0587-41c1-b427-02bf228d33be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25678, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4513d81-d5d4-4976-9efd-794037144f6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25678, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4513d81-d5d4-4976-9efd-794037144f6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25678, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "东西用掉或拿走以后，还有一部分没有用掉或拿走。", "primary_collocate": null, "pronunciation": "shèng xià", "ipa": "ʂəŋ˥˩ ɕja˥˩", "syllable_count": 2, "sentences": [{"text": "衣服洗完后，盆里剩下一点水。", "target_word": "剩下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你先拿，剩下的留给我。", "target_word": "剩下", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "买了票以后，我只剩下十块钱。", "target_word": "剩下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书架上的书拿走了，只剩下几本旧杂志。", "target_word": "剩下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家分了蛋糕，我这里还剩下一块。", "target_word": "剩下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冰箱里的牛奶喝了一半，只剩下半瓶。", "target_word": "剩下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做完作业后，他还剩下一个小时的自由时间。", "target_word": "剩下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把零食都吃了，一点也没剩下。", "target_word": "剩下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们才走了一半，还剩下十公里。", "target_word": "剩下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水只剩下一点点，不够大家喝了。", "target_word": "剩下", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "剩下了", "label": "体标：了"}, {"form": "剩下来", "label": "趋向补语"}, {"form": "剩下的", "label": "的字结构"}], "register": "中性", "sense_fingerprint": "东西用掉或拿走后还有一部分没动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e578585e-97ef-488a-a6d8-09a2c5e452b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25678, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "剩下", "is_correct": true, "explanation": "剩下：衣服洗完后盆里留存的部分，与句意相符。"}, {"text": "吸收", "is_correct": false, "explanation": "语义：水被吸收后不会留在盆里，与句意相反。"}, {"text": "倒掉", "is_correct": false, "explanation": "语义：倒掉的水不会留在盆里，与句意相反。"}, {"text": "装满", "is_correct": false, "explanation": "搭配：「装满」与「一点」语义矛盾，不能搭配。"}], "explanations": {"剩下": "剩下：衣服洗完后盆里留存的部分，与句意相符。", "吸收": "语义：水被吸收后不会留在盆里，与句意相反。", "倒掉": "语义：倒掉的水不会留在盆里，与句意相反。", "装满": "搭配：「装满」与「一点」语义矛盾，不能搭配。"}, "sentence_index": 0, "correct_answer": "剩下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈去市场剩下了两斤鱼。", "explanation": "这里应该用〈买〉。剩下表示用掉后余留，不表示去市场买到东西。"}, {"text": "我今天剩下了一封信，很开心。", "explanation": "这里应该用〈收到〉。剩下表示余留，不表示收到别人寄来的东西。"}, {"text": "他不小心剩下了一个杯子。", "explanation": "这里应该用〈落下〉。剩下表示余留，不表示不小心把东西留在某处；忘在某处应说落下。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4513d81-d5d4-4976-9efd-794037144f6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25678, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "剩下", "is_correct": true, "explanation": "剩下：做完作业后仍留存的时间，句意成立。"}, {"text": "吃掉", "is_correct": false, "explanation": "语义：自由时间不能吃掉，与句意不符。"}, {"text": "倒掉", "is_correct": false, "explanation": "语义：时间不能倒掉，与句意不符。"}, {"text": "带走", "is_correct": false, "explanation": "搭配：说时间留存一般用「剩下」或「用掉」，不能说「带走」自由时间。"}], "explanations": {"剩下": "剩下：做完作业后仍留存的时间，句意成立。", "吃掉": "语义：自由时间不能吃掉，与句意不符。", "倒掉": "语义：时间不能倒掉，与句意不符。", "带走": "搭配：说时间留存一般用「剩下」或「用掉」，不能说「带走」自由时间。"}, "sentence_index": 6, "correct_answer": "剩下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他去邮局剩下了一封信。", "explanation": "这里应该用〈寄〉。去邮局是寄信，剩下表示余留，不表示把信寄出。"}, {"text": "他向朋友剩下了三本书。", "explanation": "这里应该用〈借〉。向朋友借书是借，剩下表示余留，不能用来说借入。"}, {"text": "他用抹布剩下了桌子。", "explanation": "这里应该用〈擦〉。用抹布做的是擦，剩下表示余留，不能用来说擦拭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4513d81-d5d4-4976-9efd-794037144f6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25678, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "桶里还剩下完一点油。", "corrected_sentence": "桶里还剩下一点油。", "error_description": "「剩下完一点油」错，「完」表示用尽，与「剩下」的留存义矛盾，应删去「完」，说「还剩下一点油」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4513d81-d5d4-4976-9efd-794037144f6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25678, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "车上被剩下两个座位。", "corrected_sentence": "车上还剩下两个座位。", "error_description": "「车上被剩下两个座位」错，「剩下」表示余留，不能用被字句，此处「被」应换为「还」，说「车上还剩下两个座位」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4513d81-d5d4-4976-9efd-794037144f6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
