INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25682, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用尖尖的东西转着挖洞。", "primary_collocate": null, "pronunciation": "zuān", "ipa": "tswan˥", "syllable_count": 1, "sentences": [{"text": "工人用机器在墙上钻了一个洞。", "target_word": "钻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想在木板上钻两个小洞。", "target_word": "钻", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸要在墙上钻洞，好挂一幅画。", "target_word": "钻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要先在铁板上钻一个孔，再放螺丝。", "target_word": "钻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块石头太硬，机器都钻不动。", "target_word": "钻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅在桌子腿上钻了一个小孔。", "target_word": "钻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用锥子在皮带上钻了一个新孔。", "target_word": "钻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在这块板子的中间钻一个洞。", "target_word": "钻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在这里钻了一口深井。", "target_word": "钻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先在木头上画个点，再从这里往下钻。", "target_word": "钻", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "钻了", "label": "体标（了）"}, {"form": "钻过", "label": "体标（过）"}, {"form": "钻着", "label": "体标（着）"}, {"form": "鑽", "label": "繁体"}], "register": "中性", "sense_fingerprint": "动词：用尖的工具旋转着在物体上打洞，如钻孔、钻井", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c8191f-7414-4b3d-a464-4b2f2d80104d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25682, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "钻", "is_correct": true, "explanation": "钻（zuān，第一声）：用尖的工具旋转着在物体上打洞，正是这个音。"}, {"text": "砖", "is_correct": false, "explanation": "zhuān（第一声）与 zuān 声母不同（zh 与 z），意思是砖头。"}, {"text": "酸", "is_correct": false, "explanation": "suān（第一声）与 zuān 声母不同（s 与 z），意思是味道酸。"}, {"text": "尊", "is_correct": false, "explanation": "zūn（第一声）与 zuān 韵母不同（un 与 uan），意思是尊重。"}, {"text": "攥", "is_correct": false, "explanation": "zuàn（第四声）与 zuān 声调不同，意思是紧紧握住。"}], "explanations": {"钻": "钻（zuān，第一声）：用尖的工具旋转着在物体上打洞，正是这个音。", "砖": "zhuān（第一声）与 zuān 声母不同（zh 与 z），意思是砖头。", "酸": "suān（第一声）与 zuān 声母不同（s 与 z），意思是味道酸。", "尊": "zūn（第一声）与 zuān 韵母不同（un 与 uan），意思是尊重。", "攥": "zuàn（第四声）与 zuān 声调不同，意思是紧紧握住。"}, "sentence_index": null, "correct_answer": "钻"}, "level_3": {"options": [{"text": "钻", "is_correct": true, "explanation": "钻：用机器旋转着打出孔洞，与“机器”和“洞”相合，正是本句所需。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，不能用机器在墙上吃出洞。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写”的对象是文字，不能与“洞”搭配，“写了一个洞”无法成立。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能与“洞”搭配，无法构成合理的动作。"}], "explanations": {"钻": "钻：用机器旋转着打出孔洞，与“机器”和“洞”相合，正是本句所需。", "吃": "语义：“吃”指进食，不能用机器在墙上吃出洞。", "写": "搭配：“写”的对象是文字，不能与“洞”搭配，“写了一个洞”无法成立。", "唱": "搭配：“唱”不能与“洞”搭配，无法构成合理的动作。"}, "sentence_index": 0, "correct_answer": "钻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在木头上钻了一幅画。", "explanation": "这里应该用〈刻〉。钻是用尖的东西打出孔洞，不能用来在木头上雕出图画；雕刻图案要说“刻”。"}, {"text": "他用螺丝刀钻了一颗螺丝。", "explanation": "这里应该用〈拧〉。钻是在物体上打出孔洞，不能用来旋转已有的螺丝；拧螺丝要说“拧”。"}, {"text": "他用剪刀钻了一块布，做成了一件衣服。", "explanation": "这里应该用〈裁〉。钻是用尖的工具旋转着打出孔洞，不能用来把布剪开；用剪刀裁布做衣服要说“裁”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0a31b1e-cf47-4ec3-8290-6230a7008ae8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25682, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "钻", "is_correct": true, "explanation": "钻（zuān，第一声）：用尖的工具旋转着在物体上打洞，正是这个音。"}, {"text": "专", "is_correct": false, "explanation": "zhuān（第一声）与 zuān 声母不同（zh 与 z），意思是专门。"}, {"text": "遵", "is_correct": false, "explanation": "zūn（第一声）与 zuān 韵母不同（un 与 uan），意思是遵守。"}, {"text": "簪", "is_correct": false, "explanation": "zān（第一声）与 zuān 只差一个 u 介音，意思是发簪。"}], "explanations": {"钻": "钻（zuān，第一声）：用尖的工具旋转着在物体上打洞，正是这个音。", "专": "zhuān（第一声）与 zuān 声母不同（zh 与 z），意思是专门。", "遵": "zūn（第一声）与 zuān 韵母不同（un 与 uan），意思是遵守。", "簪": "zān（第一声）与 zuān 只差一个 u 介音，意思是发簪。"}, "sentence_index": null, "correct_answer": "钻"}, "level_3": {"options": [{"text": "钻", "is_correct": true, "explanation": "钻：用锥子旋转着打出孔，与“锥子”“皮带”和“新孔”相合，正是本句所需。"}, {"text": "烤", "is_correct": false, "explanation": "语义：“烤”需要热源，锥子无法把皮带烤出孔。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”不能与“孔”搭配，无法构成合理的动作。"}, {"text": "熬", "is_correct": false, "explanation": "语义：“熬”指加热煮制，与用锥子在皮带上打孔的动作不相符。"}], "explanations": {"钻": "钻：用锥子旋转着打出孔，与“锥子”“皮带”和“新孔”相合，正是本句所需。", "烤": "语义：“烤”需要热源，锥子无法把皮带烤出孔。", "喝": "搭配：“喝”不能与“孔”搭配，无法构成合理的动作。", "熬": "语义：“熬”指加热煮制，与用锥子在皮带上打孔的动作不相符。"}, "sentence_index": 6, "correct_answer": "钻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用锯子钻了几下，把木板锯开了。", "explanation": "这里的“钻”被用来表示“切断”义，与本词“用尖的工具旋转着打洞”的意思不同；钻只能打出孔洞，不能把木板切断。"}, {"text": "他用抹布钻了一块玻璃，玻璃变得很亮。", "explanation": "这里应该用〈擦〉。钻是旋转着打出孔洞，不能用来擦拭玻璃；擦拭要说“擦”。"}, {"text": "他用刨子钻平了木板的表面。", "explanation": "这里的“钻”被用来表示“削平”义，与本词“用尖的工具旋转着打洞”的意思不同；钻只能打出孔洞，不能把木板表面削平。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0a31b1e-cf47-4ec3-8290-6230a7008ae8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25682, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工匠把钢板钻了透。", "corrected_sentence": "工匠把钢板钻透了。", "error_description": "错误形式“钻了透”，正确形式“钻透了”。结果补语“透”须紧接在“钻”之后，“了”放在补语之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0a31b1e-cf47-4ec3-8290-6230a7008ae8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25682, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他曾经用锥子在皮带上钻了过一个新孔。", "corrected_sentence": "他曾经用锥子在皮带上钻过一个新孔。", "error_description": "错误形式“钻了过”，正确形式“钻过”。表示经历的“过”直接接在动词后，不能再与“了”并用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0a31b1e-cf47-4ec3-8290-6230a7008ae8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
