INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25684, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "洞是东西里面空空的、可以伸进去的地方。", "primary_collocate": null, "pronunciation": "dòng", "ipa": "toŋ˥˩", "syllable_count": 1, "sentences": [{"text": "树上有一个洞，里面住着小鸟。", "target_word": "洞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "兔子的洞在大树下面。", "target_word": "洞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把手伸进洞里，摸到了一块石头。", "target_word": "洞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙上的洞里藏着一把旧钥匙。", "target_word": "洞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小熊找到一个洞，在里面睡觉。", "target_word": "洞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "河边的洞里住着一只小动物。", "target_word": "洞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "洞很深，手电筒也照不到底。", "target_word": "洞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个洞太小，我的手伸不进去。", "target_word": "洞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蛇躲在洞里一动不动。", "target_word": "洞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他往洞里看了看，什么也没有。", "target_word": "洞", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个洞", "label": "量词搭配"}, {"form": "山洞", "label": "复合"}, {"form": "树洞", "label": "复合"}, {"form": "洞口", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词：东西里面空着、可以伸进去或藏身的地方，如树上的洞、动物的洞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c8191f-7414-4b3d-a464-4b2f2d80104d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25684, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "洞", "is_correct": true, "explanation": "洞（dòng，第四声）：东西里面空着、可以伸进去的地方，正是这个音。"}, {"text": "东", "is_correct": false, "explanation": "dōng（第一声）与 dòng 声调不同，意思是东方。"}, {"text": "懂", "is_correct": false, "explanation": "dǒng（第三声）与 dòng 声调不同，意思是明白。"}, {"text": "凳", "is_correct": false, "explanation": "dèng（第四声）与 dòng 韵母不同（eng 与 ong），意思是板凳。"}], "explanations": {"洞": "洞（dòng，第四声）：东西里面空着、可以伸进去的地方，正是这个音。", "东": "dōng（第一声）与 dòng 声调不同，意思是东方。", "懂": "dǒng（第三声）与 dòng 声调不同，意思是明白。", "凳": "dèng（第四声）与 dòng 韵母不同（eng 与 ong），意思是板凳。"}, "sentence_index": null, "correct_answer": "洞"}, "level_3": {"options": [{"text": "洞", "is_correct": true, "explanation": "洞：树干上空着、可供小鸟藏身的地方，正是句中所指。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是实心的，里面不能住着小鸟。"}, {"text": "花", "is_correct": false, "explanation": "语义：花不能让小鸟住在里面，与“里面住着小鸟”的语境不符。"}, {"text": "书", "is_correct": false, "explanation": "搭配：“书”不用量词“个”，且书里住不了小鸟。"}], "explanations": {"洞": "洞：树干上空着、可供小鸟藏身的地方，正是句中所指。", "石头": "语义：石头是实心的，里面不能住着小鸟。", "花": "语义：花不能让小鸟住在里面，与“里面住着小鸟”的语境不符。", "书": "搭配：“书”不用量词“个”，且书里住不了小鸟。"}, "sentence_index": 0, "correct_answer": "洞"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "墙角有一条洞，老鼠常从那里进出。", "explanation": "这里应该用〈个〉。洞用量词“个”，“条”多用于长条形的东西，搭配不当。"}, {"text": "学针灸要先找准人体的洞位。", "explanation": "这里应该用〈穴〉。“穴位”是针灸的固定说法，指施针的部位，不能说“洞位”。"}, {"text": "树下有一颗洞，松鼠常在那里藏果子。", "explanation": "这里应该用〈个〉。洞用量词“个”，“颗”多用于圆粒状的东西，搭配不当。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0a31b1e-cf47-4ec3-8290-6230a7008ae8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25684, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "洞", "is_correct": true, "explanation": "洞（dòng，第四声）：东西里面空着、可以伸进去的地方，正是这个音。"}, {"text": "痛", "is_correct": false, "explanation": "tòng（第四声）与 dòng 声母不同（t 与 d），意思是疼痛。"}, {"text": "弄", "is_correct": false, "explanation": "nòng（第四声）与 dòng 声母不同（n 与 d），意思是摆弄。"}, {"text": "定", "is_correct": false, "explanation": "dìng（第四声）与 dòng 韵母不同（ing 与 ong），意思是确定。"}], "explanations": {"洞": "洞（dòng，第四声）：东西里面空着、可以伸进去的地方，正是这个音。", "痛": "tòng（第四声）与 dòng 声母不同（t 与 d），意思是疼痛。", "弄": "nòng（第四声）与 dòng 声母不同（n 与 d），意思是摆弄。", "定": "dìng（第四声）与 dòng 韵母不同（ing 与 ong），意思是确定。"}, "sentence_index": null, "correct_answer": "洞"}, "level_3": {"options": [{"text": "洞", "is_correct": true, "explanation": "洞：东西里面空着的地方，深得手电也照不到底，正是本句所指。"}, {"text": "树", "is_correct": false, "explanation": "语义：树是实体，不能用“很深，手电筒照不到底”来形容。"}, {"text": "笔", "is_correct": false, "explanation": "语义：笔不能用“很深，手电筒也照不到底”来描述，与句意不符。"}, {"text": "饼", "is_correct": false, "explanation": "语义：饼是食物，不能说“饼很深”，句意不成立。"}], "explanations": {"洞": "洞：东西里面空着的地方，深得手电也照不到底，正是本句所指。", "树": "语义：树是实体，不能用“很深，手电筒照不到底”来形容。", "笔": "语义：笔不能用“很深，手电筒也照不到底”来描述，与句意不符。", "饼": "语义：饼是食物，不能说“饼很深”，句意不成立。"}, "sentence_index": 6, "correct_answer": "洞"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "河边有一朵洞，水鸟常在那里栖息。", "explanation": "这里应该用〈个〉。“朵”只用于花朵，洞要用量词“个”，搭配不当。"}, {"text": "他的鼻洞有点发炎。", "explanation": "这里应该用〈孔〉。“鼻孔”是固定说法，指鼻腔的开口，不能说“鼻洞”。"}, {"text": "线头要对准针洞穿过去。", "explanation": "这里应该用〈眼〉。“针眼”是固定说法，指针上穿线的小孔，不能说“针洞”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0a31b1e-cf47-4ec3-8290-6230a7008ae8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25684, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "草丛里有三条洞，兔子常常躲在那里。", "corrected_sentence": "草丛里有三个洞，兔子常常躲在那里。", "error_description": "错误形式“三条洞”，正确形式“三个洞”。洞用量词“个”，“条”用于长条形的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0a31b1e-cf47-4ec3-8290-6230a7008ae8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25684, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "树上有一个很深洞的。", "corrected_sentence": "树上有一个很深的洞。", "error_description": "错误形式“很深洞的”，正确形式“很深的洞”。修饰语“很深”和助词“的”应放在名词之前，“的”须紧接修饰语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0a31b1e-cf47-4ec3-8290-6230a7008ae8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
