INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25688, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种用来盛汤或舀东西的勺子，柄很长。", "primary_collocate": null, "pronunciation": "cháng sháo", "ipa": "ʈʂʰɑŋ˧˥ ʂɑʊ̯˧˥", "syllable_count": 2, "sentences": [{"text": "煮粥的时候，我常用长勺慢慢搅。", "target_word": "长勺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶拿着长勺，给大家盛了满满一碗汤。", "target_word": "长勺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这口锅太大，普通的勺子够不到，要换长勺。", "target_word": "长勺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌上的汤盆里放着一把长勺。", "target_word": "长勺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用长勺从缸里舀水浇花。", "target_word": "长勺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做火锅的时候，大家都用长勺捞肉丸。", "target_word": "长勺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长勺放在锅里太久，柄也会变热。", "target_word": "长勺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买一把长勺吧，煮大锅汤比较方便。", "target_word": "长勺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师傅用长勺把热油浇在面上。", "target_word": "长勺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个长勺是不锈钢做的，很好洗。", "target_word": "长勺", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一把长勺", "label": "量词搭配"}, {"form": "長勺", "label": "繁体"}], "register": "中性", "sense_fingerprint": "长柄的盛汤、舀东西用的勺子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c8191f-7414-4b3d-a464-4b2f2d80104d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25688, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "长勺", "is_correct": true, "explanation": "正确：长勺柄很长，煮粥时可以用它慢慢搅。"}, {"text": "书", "is_correct": false, "explanation": "语义：书不是搅粥的工具，用书搅粥说不通。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子不能用来搅动粥。"}, {"text": "手套", "is_correct": false, "explanation": "搭配：手套不是搅拌器具，不能与“慢慢搅”搭配。"}], "explanations": {"长勺": "正确：长勺柄很长，煮粥时可以用它慢慢搅。", "书": "语义：书不是搅粥的工具，用书搅粥说不通。", "椅子": "语义：椅子不能用来搅动粥。", "手套": "搭配：手套不是搅拌器具，不能与“慢慢搅”搭配。"}, "sentence_index": 0, "correct_answer": "长勺"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用长勺把土豆切成了细丝。", "explanation": "这里应该用〈菜刀〉。切丝要用刀，长勺是盛汤的勺子，不能用来切东西。"}, {"text": "他用长勺把面团擀平了。", "explanation": "这里应该用〈擀面杖〉。擀面杖用来把面团压平；长勺是盛汤的勺子，不能擀面。"}, {"text": "他用长勺给饼干刷上蛋液。", "explanation": "这里应该用〈刷子〉。刷蛋液要用刷子，长勺是勺子，不能均匀地涂抹。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0a31b1e-cf47-4ec3-8290-6230a7008ae8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25688, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "长勺", "is_correct": true, "explanation": "正确：长勺有柄，放在锅里太久，柄会变热。"}, {"text": "碗", "is_correct": false, "explanation": "语义：碗没有柄，“柄也会变热”不能指碗。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包没有柄，“柄也会变热”说不通。"}, {"text": "课本", "is_correct": false, "explanation": "搭配：课本不会放在锅里，“放在锅里”与课本不搭配。"}], "explanations": {"长勺": "正确：长勺有柄，放在锅里太久，柄会变热。", "碗": "语义：碗没有柄，“柄也会变热”不能指碗。", "书包": "语义：书包没有柄，“柄也会变热”说不通。", "课本": "搭配：课本不会放在锅里，“放在锅里”与课本不搭配。"}, "sentence_index": 6, "correct_answer": "长勺"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用长勺把土豆皮削掉。", "explanation": "这里应该用〈削皮刀〉。削皮要用削皮刀，长勺是勺子，不能削皮。"}, {"text": "他用长勺把布料剪成了两块。", "explanation": "这里应该用〈剪刀〉。剪布要用剪刀，长勺是盛汤的勺子，不能用来剪断布料。"}, {"text": "他用长勺量了一升水。", "explanation": "这里应该用〈量杯〉。量取一升水要用量杯，长勺不能准确量出容量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0a31b1e-cf47-4ec3-8290-6230a7008ae8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25688, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他买了一条长勺。", "corrected_sentence": "他买了一把长勺。", "error_description": "错误形式：“一条长勺”；正确形式：“一把长勺”。长勺带柄，量词用“把”；“条”用于细长的东西，不用于勺子。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0a31b1e-cf47-4ec3-8290-6230a7008ae8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25688, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请长勺洗干净。", "corrected_sentence": "请把长勺洗干净。", "error_description": "错误形式：“请长勺洗干净”；正确形式：“请把长勺洗干净”。处置式要用“把”引出被处置的“长勺”，漏掉“把”就不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0a31b1e-cf47-4ec3-8290-6230a7008ae8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
