INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25694, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西放到一个地方里面。", "primary_collocate": null, "pronunciation": "fàng jìn qù", "ipa": "fɑŋ˥˩ tɕin˥˩ tɕʰy˥˩", "syllable_count": 3, "sentences": [{"text": "信封打开了，他把照片放进去，再封好口。", "target_word": "放进去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这些书放进去，书架上还有地方。", "target_word": "放进去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰箱里很空，把牛奶放进去吧。", "target_word": "放进去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明把铅笔放进去，然后拉上了笔袋的拉链。", "target_word": "放进去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "锅里的水热了，把饺子放进去。", "target_word": "放进去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "抽屉是空的，你可以把证件放进去。", "target_word": "放进去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他打开盒子，把戒指放进去，盖好了盖子。", "target_word": "放进去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "袋子还没满，再把橘子放进去吧。", "target_word": "放进去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她拿起杯子，把一块冰放进去了。", "target_word": "放进去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "行李箱打开着，他把外套放进去，然后合上。", "target_word": "放进去", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "放进去了", "label": "体标（了）"}, {"form": "放进去过", "label": "体标（过）"}, {"form": "放得进去", "label": "可能补语"}, {"form": "放进来", "label": "趋向相对形式"}], "register": "中性", "sense_fingerprint": "把东西放到某个地方的里面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c8191f-7414-4b3d-a464-4b2f2d80104d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25694, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "放进去", "is_correct": true, "explanation": "“放进去”指把照片放入信封内，与“信封打开了”后再封口的顺序相合。"}, {"text": "放出去", "is_correct": false, "explanation": "语义：放出去指向外放，与把照片放入信封的动作方向相反。"}, {"text": "放下去", "is_correct": false, "explanation": "搭配：“放下去”指往下放低，不用于把照片装进信封，搭配不当。"}, {"text": "拿出来", "is_correct": false, "explanation": "语义：拿出来是从里面取出，与放入照片后再封口的顺序相反。"}], "explanations": {"放进去": "“放进去”指把照片放入信封内，与“信封打开了”后再封口的顺序相合。", "放出去": "语义：放出去指向外放，与把照片放入信封的动作方向相反。", "放下去": "搭配：“放下去”指往下放低，不用于把照片装进信封，搭配不当。", "拿出来": "语义：拿出来是从里面取出，与放入照片后再封口的顺序相反。"}, "sentence_index": 0, "correct_answer": "放进去"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把太阳放进去，屋子里就亮了。", "explanation": "这里应该用〈照进去〉。阳光是照射进屋里的，不能说“放进去”。"}, {"text": "他出门前把门放进去了。", "explanation": "这里应该用〈关上〉。门是关上的，不能把门放到某个地方里面。"}, {"text": "我在屋外，你在屋里，把钥匙放进去给我。", "explanation": "这里应该用〈拿出来〉。钥匙要从屋里送到屋外，应说“拿出来”，不能说“放进去”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0a31b1e-cf47-4ec3-8290-6230a7008ae8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25694, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "放进去", "is_correct": true, "explanation": "“放进去”指把戒指放入盒内，与“打开盒子”后再盖上盖子的顺序相合。"}, {"text": "放出来", "is_correct": false, "explanation": "语义：放出来指取出或释放，与把戒指放入盒内的动作相反。"}, {"text": "放上去", "is_correct": false, "explanation": "语义：放上去指放在表面，不是放入盒内，与盖盖子前的动作不符。"}, {"text": "放下来", "is_correct": false, "explanation": "搭配：“放下来”指降低位置，不用于把东西收进盒中，搭配不当。"}], "explanations": {"放进去": "“放进去”指把戒指放入盒内，与“打开盒子”后再盖上盖子的顺序相合。", "放出来": "语义：放出来指取出或释放，与把戒指放入盒内的动作相反。", "放上去": "语义：放上去指放在表面，不是放入盒内，与盖盖子前的动作不符。", "放下来": "搭配：“放下来”指降低位置，不用于把东西收进盒中，搭配不当。"}, "sentence_index": 6, "correct_answer": "放进去"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一直把这句话放进去，从来不对别人说。", "explanation": "这里的“放进去”表示放入具体的地方，此处用于抽象的话语，应说〈记在心里〉。"}, {"text": "我站在屋外，妈妈在屋里，把饭放进去给我。", "explanation": "这里应该用〈递出来〉。饭要从屋里送到屋外，应说“递出来”，不能说“放进去”。"}, {"text": "他把这件事放进去，结果谁也没有解决。", "explanation": "这里的“放进去”表示放入某处，“这件事”不能放入容器，应说〈提出〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0a31b1e-cf47-4ec3-8290-6230a7008ae8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25694, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈把饼干放进去着，然后关上柜门。", "corrected_sentence": "妈妈把饼干放进去了，然后关上柜门。", "error_description": "体标错误：表示动作已完成应用“了”，不能用“着”。“放进去”是结果补语结构，已完成的动作要说“放进去了”，不能说“放进去着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0a31b1e-cf47-4ec3-8290-6230a7008ae8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25694, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他钥匙放进去，然后锁上了抽屉。", "corrected_sentence": "他把钥匙放进去，然后锁上了抽屉。", "error_description": "缺少“把”：处置式“把钥匙放进去”需要用“把”引出被处置的宾语，省去“把”不合规范。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0a31b1e-cf47-4ec3-8290-6230a7008ae8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
