INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25696, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "味道是吃东西时舌头感觉到的酸甜苦辣等。", "primary_collocate": null, "pronunciation": "wèi dao", "ipa": "weɪ˥˩ tɑʊ", "syllable_count": 2, "sentences": [{"text": "这个苹果的味道酸酸甜甜的。", "target_word": "味道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "药的味道很苦，孩子不想喝。", "target_word": "味道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你尝尝这个菜，味道怎么样？", "target_word": "味道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这碗面的味道有点辣。", "target_word": "味道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "柠檬的味道很酸。", "target_word": "味道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不喜欢这种茶的味道，太苦了。", "target_word": "味道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "糖放多了，汤的味道太甜。", "target_word": "味道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭馆的菜，味道特别好。", "target_word": "味道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他吃了一口，说味道不错。", "target_word": "味道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个蛋糕的味道不太甜，我很喜欢。", "target_word": "味道", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种味道", "label": "量词"}], "register": "中性", "sense_fingerprint": "名词，指吃东西时舌头尝到的酸甜苦辣等味觉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b87e49c7-61d3-43e4-8c3e-581be990683a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25696, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "味道", "is_correct": true, "explanation": "味道：指吃东西时舌头尝到的酸甜滋味，与“酸酸甜甜”相合。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不能用“酸酸甜甜”来形容，味觉词不搭配颜色。"}, {"text": "形状", "is_correct": false, "explanation": "语义：苹果的形状不是酸甜，与句中的味觉描述不符。"}, {"text": "重量", "is_correct": false, "explanation": "语义：重量是数量特征，不能用“酸酸甜甜”来描述。"}], "explanations": {"味道": "味道：指吃东西时舌头尝到的酸甜滋味，与“酸酸甜甜”相合。", "颜色": "搭配：“颜色”不能用“酸酸甜甜”来形容，味觉词不搭配颜色。", "形状": "语义：苹果的形状不是酸甜，与句中的味觉描述不符。", "重量": "语义：重量是数量特征，不能用“酸酸甜甜”来描述。"}, "sentence_index": 0, "correct_answer": "味道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块蛋糕的味道很松软。", "explanation": "这里应该用〈口感〉。松软、有嚼劲等质地要用“口感”，“味道”指酸甜苦辣等味觉，不能说“味道很松软”。"}, {"text": "这碗汤的味道太烫了。", "explanation": "这里应该用〈温度〉。冷热要用“温度”，“味道”不能用“太烫”来形容。"}, {"text": "这辆车的味道要两万块。", "explanation": "这里应该用〈价格〉。说东西要花多少钱要用“价格”，“味道”只指酸甜苦辣等味觉，不能用来说价钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edfee2d8-cb11-4467-b59a-da561cd30af9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25696, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "味道", "is_correct": true, "explanation": "味道：指食物的滋味，与“汤的……太甜”相合。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度不能用“甜”来形容，与“太甜”矛盾。"}, {"text": "分量", "is_correct": false, "explanation": "语义：分量指多少，不能用“太甜”来形容。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“脾气”用于人，不能说汤的“脾气太甜”。"}], "explanations": {"味道": "味道：指食物的滋味，与“汤的……太甜”相合。", "温度": "语义：温度不能用“甜”来形容，与“太甜”矛盾。", "分量": "语义：分量指多少，不能用“太甜”来形容。", "脾气": "搭配：“脾气”用于人，不能说汤的“脾气太甜”。"}, "sentence_index": 6, "correct_answer": "味道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服的味道很漂亮。", "explanation": "这里应该用〈样子〉。衣服好不好看要说“样子”，“味道”指吃东西时尝到的酸甜苦辣，不能说“味道很漂亮”。"}, {"text": "这碗汤的味道很清澈。", "explanation": "这里应该用〈颜色〉。描述清澈、透明的是颜色或外观，“味道”不能用“清澈”来形容。"}, {"text": "这根面条的味道有一米。", "explanation": "这里应该用〈长度〉。说有多长要用“长度”，“味道”不能用数字来量化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edfee2d8-cb11-4467-b59a-da561cd30af9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25696, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块糖有一颗甜甜的味道。", "corrected_sentence": "这块糖有一股甜甜的味道。", "error_description": "错误：“味道”的量词用了“颗”。“颗”用于圆粒状的东西，“味道”应用“一股”或“一种”，正确说法是“一股甜甜的味道”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edfee2d8-cb11-4467-b59a-da561cd30af9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25696, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这碗粥有一只清淡的味道。", "corrected_sentence": "这碗粥有一股清淡的味道。", "error_description": "错误：“味道”的量词用了“只”。“只”用于动物或成对物品中的一个，“味道”应用“一股”或“一种”，正确说法是“一股清淡的味道”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edfee2d8-cb11-4467-b59a-da561cd30af9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
