INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25698, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "根据情况作出的不太肯定的推测，相当于多半、可能。", "primary_collocate": null, "pronunciation": "dà gài", "ipa": "ta˥˩ kaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "天这么黑，他大概已经睡了。", "target_word": "大概", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面地上是湿的，昨晚大概下雨了。", "target_word": "大概", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没接电话，大概在开会。", "target_word": "大概", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天这么冷，明天大概会下雪。", "target_word": "大概", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她今天没来，大概是生病了。", "target_word": "大概", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灯还亮着，他大概还在工作。", "target_word": "大概", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地方我没来过，我大概记错了路。", "target_word": "大概", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么晚了，他大概不会来了。", "target_word": "大概", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上堵车，他大概会晚到。", "target_word": "大概", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他大概忘了今天是我的生日。", "target_word": "大概", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词，表示根据情况作出的不太肯定的推测，相当于多半、可能", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b87e49c7-61d3-43e4-8c3e-581be990683a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25698, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大概", "is_correct": true, "explanation": "大概：表示根据情况作出的不太肯定的推测，与“天这么黑”的推断相合。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”表示立即发生，与“已经睡了”的完成状态矛盾。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”多用于否定或习惯，不能与“已经睡了”这样的具体事件搭配。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不常发生，与“已经睡了”这一具体事件矛盾。"}], "explanations": {"大概": "大概：表示根据情况作出的不太肯定的推测，与“天这么黑”的推断相合。", "马上": "语义：“马上”表示立即发生，与“已经睡了”的完成状态矛盾。", "从来": "搭配：“从来”多用于否定或习惯，不能与“已经睡了”这样的具体事件搭配。", "偶尔": "语义：“偶尔”表示不常发生，与“已经睡了”这一具体事件矛盾。"}, "sentence_index": 0, "correct_answer": "大概"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "请你大概准时到。", "explanation": "这里应该用〈务必〉。请求或要求别人做事要用“务必”，“大概”是推测，不能用于请求句。"}, {"text": "他大概一定会来，我很确定。", "explanation": "这里不该用〈大概〉。“大概”表示不肯定的推测，与“一定”“很确定”的语气矛盾。"}, {"text": "我亲眼看到他上了车，所以大概他没上车。", "explanation": "这里不该用〈大概〉。“亲眼看到”是确定的经历，与表示推测的“大概”相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edfee2d8-cb11-4467-b59a-da561cd30af9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25698, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大概", "is_correct": true, "explanation": "大概：表示根据情况作出的不太肯定的推测，与“我没来过”的情况相合。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”表示马上发生，与“记错了路”这种已完成的事矛盾。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：“正在”表示动作进行中，不能修饰“记错了路”这种已完成的结果。"}, {"text": "赶紧", "is_correct": false, "explanation": "语义：“赶紧”表示急忙去做某事，不能用来修饰“记错了路”这种无意的错误。"}], "explanations": {"大概": "大概：表示根据情况作出的不太肯定的推测，与“我没来过”的情况相合。", "立刻": "语义：“立刻”表示马上发生，与“记错了路”这种已完成的事矛盾。", "正在": "体貌：“正在”表示动作进行中，不能修饰“记错了路”这种已完成的结果。", "赶紧": "语义：“赶紧”表示急忙去做某事，不能用来修饰“记错了路”这种无意的错误。"}, "sentence_index": 6, "correct_answer": "大概"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工地上的人员大概必须戴安全帽。", "explanation": "这里不该用〈大概〉。“大概”表示不确定的估计，与句中确定的安全规定语气不合，规定只能用明确的语气，不能用估计来修饰。"}, {"text": "这一点大概毫无疑问：地球绕着太阳转。", "explanation": "这里不该用〈大概〉。“大概”表示不肯定的估计，与这句确定无疑的语气矛盾；这是确定的事实，应使用表示确定的〈肯定〉。"}, {"text": "我确定他来过，他大概没来。", "explanation": "这里不该用〈大概〉。“大概”表示不肯定的推测，与“确定”的语气矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edfee2d8-cb11-4467-b59a-da561cd30af9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25698, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明天大概的不会下雨。", "corrected_sentence": "明天大概不会下雨。", "error_description": "错误：“大概”后多加了“的”。“大概”是副词，应直接放在“不会”之前，应说“明天大概不会下雨”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edfee2d8-cb11-4467-b59a-da561cd30af9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25698, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他大概的忘了带钥匙。", "corrected_sentence": "他大概忘了带钥匙。", "error_description": "错误：“大概”后多加了“的”。“大概”是副词，直接修饰动词“忘”，应说“他大概忘了带钥匙”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edfee2d8-cb11-4467-b59a-da561cd30af9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25700, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "浪费", "is_correct": true, "explanation": "反义：“节省”是省着用，“浪费”是白白耗费，二者构成反义关系。"}, {"text": "研究", "is_correct": false, "explanation": "“研究”指探讨、琢磨，与“节省”不构成反义。"}, {"text": "欢迎", "is_correct": false, "explanation": "“欢迎”指接纳、迎接，与“节省”没有反义关系。"}, {"text": "观察", "is_correct": false, "explanation": "“观察”指仔细看、留意，与“节省”不构成反义。"}], "correct_answer": "浪费", "explanations": {"浪费": "反义：“节省”是省着用，“浪费”是白白耗费，二者构成反义关系。", "研究": "“研究”指探讨、琢磨，与“节省”不构成反义。", "欢迎": "“欢迎”指接纳、迎接，与“节省”没有反义关系。", "观察": "“观察”指仔细看、留意，与“节省”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edfee2d8-cb11-4467-b59a-da561cd30af9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25700, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "浪费", "is_correct": true, "explanation": "反义：“节省”是省着用，“浪费”是白白耗费，二者构成反义关系。"}, {"text": "修理", "is_correct": false, "explanation": "“修理”指修复损坏的东西，与“节省”没有反义关系。"}, {"text": "思考", "is_correct": false, "explanation": "“思考”指动脑筋考虑，与“节省”不构成反义。"}, {"text": "出发", "is_correct": false, "explanation": "“出发”指动身前往，与“节省”没有反义关系。"}], "correct_answer": "浪费", "explanations": {"浪费": "反义：“节省”是省着用，“浪费”是白白耗费，二者构成反义关系。", "修理": "“修理”指修复损坏的东西，与“节省”没有反义关系。", "思考": "“思考”指动脑筋考虑，与“节省”不构成反义。", "出发": "“出发”指动身前往，与“节省”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edfee2d8-cb11-4467-b59a-da561cd30af9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25700, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不浪费东西，比如用很少的钱买东西。", "primary_collocate": null, "pronunciation": "jié shěng", "ipa": "tɕjɛ˧˥ ʂɤŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他每个月都节省一点钱，存进银行。", "target_word": "节省", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了买新书包，小明节省早饭的钱。", "target_word": "节省", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买东西的时候，她总是想节省一些钱。", "target_word": "节省", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气很冷，我们节省着用煤。", "target_word": "节省", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶节省了一辈子，才买下这个小房子。", "target_word": "节省", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了节省钱，他每天走路上班。", "target_word": "节省", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想节省一点钱，所以不去饭馆吃饭。", "target_word": "节省", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们节省纸张，作业写在两面。", "target_word": "节省", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥节省过零花钱，给妈妈买了礼物。", "target_word": "节省", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打折的时候买菜，可以节省不少钱。", "target_word": "节省", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "节省了", "label": "体标（了）"}, {"form": "节省过", "label": "体标（过）"}, {"form": "节省着", "label": "体标（着）"}], "register": "中性", "sense_fingerprint": "少花钱、不浪费东西，把钱省下来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b87e49c7-61d3-43e4-8c3e-581be990683a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25700, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "节省", "is_correct": true, "explanation": "正确：“节省”指每月省下一点钱，与“存进银行”的积累之义一致。"}, {"text": "购买", "is_correct": false, "explanation": "搭配：“购买”的对象是商品，“一点钱”不能被购买。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”针对物品、设备，不能说修理“钱”。"}, {"text": "花费", "is_correct": false, "explanation": "语义：“花费”指支出，与“存进银行”的积累之义相反。"}], "explanations": {"节省": "正确：“节省”指每月省下一点钱，与“存进银行”的积累之义一致。", "购买": "搭配：“购买”的对象是商品，“一点钱”不能被购买。", "修理": "搭配：“修理”针对物品、设备，不能说修理“钱”。", "花费": "语义：“花费”指支出，与“存进银行”的积累之义相反。"}, "sentence_index": 0, "correct_answer": "节省"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这学期他的成绩节省了很多。", "explanation": "这里应该用〈提高〉。提高用于成绩、水平、质量；节省只用于时间、金钱、物资的使用。"}, {"text": "这次休息让他的疲劳节省了不少。", "explanation": "这里应该用〈减轻〉。减轻用于疲劳、压力、负担；节省只用于时间、金钱、物资的使用。"}, {"text": "这个月我的体重节省了三公斤。", "explanation": "这里应该用〈减轻〉。体重下降要用减轻或减少，不能说节省；节省只用于时间、金钱、物资的使用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edfee2d8-cb11-4467-b59a-da561cd30af9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25700, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "节省", "is_correct": true, "explanation": "正确：“节省”指省下钱，与“所以不去饭馆吃饭”的理由一致。"}, {"text": "增加", "is_correct": false, "explanation": "语义：“增加”说数量变多，与“所以不去饭馆吃饭”的省钱理由相反。"}, {"text": "讨论", "is_correct": false, "explanation": "搭配：“讨论”的对象是问题、事情，不能说讨论“一点钱”。"}, {"text": "调查", "is_correct": false, "explanation": "搭配：“调查”的对象是事件、情况，不能说调查“钱”。"}], "explanations": {"节省": "正确：“节省”指省下钱，与“所以不去饭馆吃饭”的理由一致。", "增加": "语义：“增加”说数量变多，与“所以不去饭馆吃饭”的省钱理由相反。", "讨论": "搭配：“讨论”的对象是问题、事情，不能说讨论“一点钱”。", "调查": "搭配：“调查”的对象是事件、情况，不能说调查“钱”。"}, "sentence_index": 6, "correct_answer": "节省"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今年的事故节省了不少。", "explanation": "这里应该用〈减少〉。减少用于事故、数量的下降；节省只用于时间、金钱、物资的使用。"}, {"text": "室内温度节省了两度。", "explanation": "这里应该用〈降低〉。温度下降要用降低，不能说节省。"}, {"text": "公司节省了安全隐患。", "explanation": "这里应该用〈消除〉。隐患要说消除或排除，节省只用于时间、金钱、物资的使用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edfee2d8-cb11-4467-b59a-da561cd30af9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25700, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们每个月都把电费节省。", "corrected_sentence": "我们每个月都把电费节省下来。", "error_description": "错误形式：“把电费节省”，“把”字句中动词后缺少补语。正确形式：“把电费节省下来”。原因：“把”字句的动词后要带补语来说明结果，“节省下来”表示把电费省了下来。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edfee2d8-cb11-4467-b59a-da561cd30af9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25700, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每天带便当，节省一只钱。", "corrected_sentence": "他每天带便当，节省一笔钱。", "error_description": "错误形式：「一只钱」；正确形式：「一笔钱」。“只”用于动物或成对之物，不能修饰“钱”；“钱”作为一笔款项，量词应用“笔”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edfee2d8-cb11-4467-b59a-da561cd30af9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25702, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "坚硬", "is_correct": true, "explanation": "反义：“松软”指软而有弹性，“坚硬”指硬而不软，二者在摸起来的质地上相对。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”形容明白、不模糊，与“松软”的触感无关，不构成反义。"}, {"text": "缓慢", "is_correct": false, "explanation": "“缓慢”形容速度慢，与“松软”不在同一维度，没有反义关系。"}, {"text": "善良", "is_correct": false, "explanation": "“善良”形容品性，与“松软”描述的物体质地无关。"}], "correct_answer": "坚硬", "explanations": {"坚硬": "反义：“松软”指软而有弹性，“坚硬”指硬而不软，二者在摸起来的质地上相对。", "清楚": "“清楚”形容明白、不模糊，与“松软”的触感无关，不构成反义。", "缓慢": "“缓慢”形容速度慢，与“松软”不在同一维度，没有反义关系。", "善良": "“善良”形容品性，与“松软”描述的物体质地无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edfee2d8-cb11-4467-b59a-da561cd30af9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25702, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "坚硬", "is_correct": true, "explanation": "反义：“松软”指软而有弹性，“坚硬”指硬而不软，二者在物体质地上相对。"}, {"text": "热闹", "is_correct": false, "explanation": "“热闹”形容场面喧嚷，与“松软”描述的质地无关，不构成反义。"}, {"text": "宽敞", "is_correct": false, "explanation": "“宽敞”形容空间大，与“松软”不在同一维度，没有反义关系。"}, {"text": "复杂", "is_correct": false, "explanation": "“复杂”形容事物的构成繁多，与“松软”的触感无关。"}], "correct_answer": "坚硬", "explanations": {"坚硬": "反义：“松软”指软而有弹性，“坚硬”指硬而不软，二者在物体质地上相对。", "热闹": "“热闹”形容场面喧嚷，与“松软”描述的质地无关，不构成反义。", "宽敞": "“宽敞”形容空间大，与“松软”不在同一维度，没有反义关系。", "复杂": "“复杂”形容事物的构成繁多，与“松软”的触感无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edfee2d8-cb11-4467-b59a-da561cd30af9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25702, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "摸起来软软的，像面包一样。", "primary_collocate": null, "pronunciation": "sōng ruǎn", "ipa": "sʊŋ˥ ʐwan˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个枕头摸起来很松软。", "target_word": "松软", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面包刚做好，摸着很松软。", "target_word": "松软", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新被子摸起来又松软又暖和。", "target_word": "松软", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种蛋糕做得很松软。", "target_word": "松软", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她做的馒头松软好吃。", "target_word": "松软", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "床垫很松软，睡得很舒服。", "target_word": "松软", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢吃松软的面包。", "target_word": "松软", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用手压一下面包，发现很松软。", "target_word": "松软", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种饼很松软，老人也能吃。", "target_word": "松软", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙发又大又松软，坐上去真舒服。", "target_word": "松软", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "形容词，形容摸起来或吃起来软而不硬，像面包一样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b87e49c7-61d3-43e4-8c3e-581be990683a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25702, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "松软", "is_correct": true, "explanation": "“松软”形容摸起来软而有弹性，与“摸起来”和“枕头”搭配自然。"}, {"text": "尖锐", "is_correct": false, "explanation": "语义：“尖锐”形容物体末端或声音刺耳，枕头摸起来不会尖锐。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”形容声音或脆食的口感，不能用于“摸起来”的触感。"}, {"text": "透明", "is_correct": false, "explanation": "语义：枕头不具有透光的性质，“透明”无法用来描述摸起来的感觉。"}], "explanations": {"松软": "“松软”形容摸起来软而有弹性，与“摸起来”和“枕头”搭配自然。", "尖锐": "语义：“尖锐”形容物体末端或声音刺耳，枕头摸起来不会尖锐。", "清脆": "搭配：“清脆”形容声音或脆食的口感，不能用于“摸起来”的触感。", "透明": "语义：枕头不具有透光的性质，“透明”无法用来描述摸起来的感觉。"}, "sentence_index": 0, "correct_answer": "松软"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块石头很松软。", "explanation": "这里应该用〈坚硬〉。松软指摸起来软软的，像面包一样；石头坚硬，不能说松软。"}, {"text": "这种薯片很松软，很好吃。", "explanation": "这里应该用〈松脆〉。薯片酥脆，松软形容摸起来软软的东西，不能形容薯片。"}, {"text": "这根树枝很松软，弯而不断。", "explanation": "这里应该用〈柔韧〉。树枝弯而不断是有韧性，松软形容摸起来软软的东西，不能形容树枝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edfee2d8-cb11-4467-b59a-da561cd30af9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25702, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "松软", "is_correct": true, "explanation": "“松软”形容面包摸起来或吃起来软而不硬，与“吃”的对象“面包”搭配自然。"}, {"text": "宽阔", "is_correct": false, "explanation": "搭配：“宽阔”形容空间或道路的广度，不能用来描述食物。"}, {"text": "瘦小", "is_correct": false, "explanation": "体貌：“瘦小”形容人或动物的体形，不能用于面包的形态。"}, {"text": "锋利", "is_correct": false, "explanation": "语义：“锋利”形容刀刃等物的尖利，面包不具有锋利的性质。"}], "explanations": {"松软": "“松软”形容面包摸起来或吃起来软而不硬，与“吃”的对象“面包”搭配自然。", "宽阔": "搭配：“宽阔”形容空间或道路的广度，不能用来描述食物。", "瘦小": "体貌：“瘦小”形容人或动物的体形，不能用于面包的形态。", "锋利": "语义：“锋利”形容刀刃等物的尖利，面包不具有锋利的性质。"}, "sentence_index": 6, "correct_answer": "松软"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的嗓音很松软，很好听。", "explanation": "这里应该用〈柔和〉。松软形容摸起来软软的东西，嗓音不能用松软来形容，要说柔和。"}, {"text": "这把剪刀很松软，剪布很费劲。", "explanation": "这里应该用〈锋利〉。松软指摸起来软软的，像面包一样；剪刀要说锋利。"}, {"text": "这个团队的纪律很松软。", "explanation": "这里应该用〈松散〉。松软形容摸起来软软的东西；纪律、组织的松懈要用松散。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edfee2d8-cb11-4467-b59a-da561cd30af9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25702, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个馒头蒸了得很松软。", "corrected_sentence": "这个馒头蒸得很松软。", "error_description": "错误：动词“蒸”与补语标记“得”之间多加了“了”。“得”应紧跟动词“蒸”，之后再接“很松软”，应说“蒸得很松软”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edfee2d8-cb11-4467-b59a-da561cd30af9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25702, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他躺在松软地床垫上。", "corrected_sentence": "他躺在松软的床垫上。", "error_description": "错误形式：「松软地床垫」；正确形式：「松软的床垫」。形容词修饰名词时应用“的”，“地”用于修饰动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edfee2d8-cb11-4467-b59a-da561cd30af9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
