INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25716, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指东西有多少或大小、长短、轻重等。", "primary_collocate": null, "pronunciation": "liàng", "ipa": "ljɑŋ˥˩", "syllable_count": 1, "sentences": [{"text": "这个药的量太大了，你要少吃一点。", "target_word": "量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做菜的时候，盐的量不能太多。", "target_word": "量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请告诉我水的量是多少。", "target_word": "量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次买的水果，量很大。", "target_word": "量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天喝水的量不够。", "target_word": "量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的饭菜，量少，价钱高。", "target_word": "量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牛奶的量不多了，我们去买吧。", "target_word": "量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，这个药的量要看年龄。", "target_word": "量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这盘菜的量太大，两个人吃不完。", "target_word": "量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把糖的量减少一点。", "target_word": "量", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "数量", "label": "复合"}, {"form": "大量", "label": "复合"}], "register": "中性", "sense_fingerprint": "东西的多少、大小，如药的量、盐的量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76649259-ba21-4681-8829-56e282963d15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25716, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "量", "is_correct": true, "explanation": "量（liàng）：指东西有多少或大小、长短、轻重等。"}, {"text": "两", "is_correct": false, "explanation": "声调不同：liǎng（第三声）与 liàng（第四声），“两”意思是二。"}, {"text": "凉", "is_correct": false, "explanation": "声调不同：liáng（第二声）与 liàng（第四声），“凉”意思是冷。"}, {"text": "粮", "is_correct": false, "explanation": "声调不同：liáng（第二声）与 liàng（第四声），“粮”意思是粮食。"}, {"text": "练", "is_correct": false, "explanation": "韵母不同：an 与 ang，声调相同（第四声），“练”意思是练习。"}, {"text": "恋", "is_correct": false, "explanation": "韵母不同：an 与 ang，声调相同（第四声），“恋”意思是恋爱。"}, {"text": "良", "is_correct": false, "explanation": "声调不同：liáng（第二声）与 liàng（第四声），「良」意思是好。"}], "explanations": {"量": "量（liàng）：指东西有多少或大小、长短、轻重等。", "两": "声调不同：liǎng（第三声）与 liàng（第四声），“两”意思是二。", "凉": "声调不同：liáng（第二声）与 liàng（第四声），“凉”意思是冷。", "粮": "声调不同：liáng（第二声）与 liàng（第四声），“粮”意思是粮食。", "练": "韵母不同：an 与 ang，声调相同（第四声），“练”意思是练习。", "恋": "韵母不同：an 与 ang，声调相同（第四声），“恋”意思是恋爱。", "良": "声调不同：liáng（第二声）与 liàng（第四声），「良」意思是好。"}, "sentence_index": null, "correct_answer": "量"}, "level_3": {"options": [{"text": "量", "is_correct": true, "explanation": "量：药品的用量，这里指一次吃多少，与“太大”和“少吃一点”相合。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指外观，药的颜色不能“太大”，与“少吃”也不相关。"}, {"text": "价钱", "is_correct": false, "explanation": "搭配：“价钱”说“高”或“贵”，不说“太大”。"}, {"text": "名字", "is_correct": false, "explanation": "语义：“名字”指称呼，药的名字不能“太大”，与“少吃一点”也无关。"}], "explanations": {"量": "量：药品的用量，这里指一次吃多少，与“太大”和“少吃一点”相合。", "颜色": "语义：“颜色”指外观，药的颜色不能“太大”，与“少吃”也不相关。", "价钱": "搭配：“价钱”说“高”或“贵”，不说“太大”。", "名字": "语义：“名字”指称呼，药的名字不能“太大”，与“少吃一点”也无关。"}, "sentence_index": 0, "correct_answer": "量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "教室里的量越来越多。", "explanation": "这里应该用〈人数〉。量多用于东西、食物、药品等的多少，说人的数目要用人数。"}, {"text": "他不知道事情会严重到什么量。", "explanation": "这里应该用〈程度〉。量指东西的多少或大小，不能用来表示事情严重的程度。"}, {"text": "这辆车的量很快，一小时能开一百公里。", "explanation": "这里应该用〈速度〉。量指东西的多少或大小，车的快慢要用速度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0489c55-8039-48f8-b79a-4bbe2c466f24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25716, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "量", "is_correct": true, "explanation": "量（liàng）：指东西有多少或大小、长短、轻重等。"}, {"text": "梁", "is_correct": false, "explanation": "声调不同：liáng（第二声）与 liàng（第四声），“梁”意思是房梁。"}, {"text": "酿", "is_correct": false, "explanation": "声母不同：n 与 l，声调相同（第四声），“酿”意思是酿造。"}, {"text": "链", "is_correct": false, "explanation": "韵母不同：an 与 ang，声调相同（第四声），“链”意思是链条。"}, {"text": "炼", "is_correct": false, "explanation": "韵母不同：an 与 ang，声调相同（第四声），“炼”意思是冶炼或锻炼。"}], "explanations": {"量": "量（liàng）：指东西有多少或大小、长短、轻重等。", "梁": "声调不同：liáng（第二声）与 liàng（第四声），“梁”意思是房梁。", "酿": "声母不同：n 与 l，声调相同（第四声），“酿”意思是酿造。", "链": "韵母不同：an 与 ang，声调相同（第四声），“链”意思是链条。", "炼": "韵母不同：an 与 ang，声调相同（第四声），“炼”意思是冶炼或锻炼。"}, "sentence_index": null, "correct_answer": "量"}, "level_3": {"options": [{"text": "量", "is_correct": true, "explanation": "量：牛奶的剩余多少，这里指数量不多了，与“不多了”相合。"}, {"text": "温度", "is_correct": false, "explanation": "语义：“温度”指冷热程度，牛奶的温度不能“不多了”。"}, {"text": "香味", "is_correct": false, "explanation": "搭配：“香味”说“浓”或“淡”，不说“多了”。"}, {"text": "年纪", "is_correct": false, "explanation": "语义：“年纪”指年龄，牛奶没有年纪，也不能“不多了”。"}], "explanations": {"量": "量：牛奶的剩余多少，这里指数量不多了，与“不多了”相合。", "温度": "语义：“温度”指冷热程度，牛奶的温度不能“不多了”。", "香味": "搭配：“香味”说“浓”或“淡”，不说“多了”。", "年纪": "语义：“年纪”指年龄，牛奶没有年纪，也不能“不多了”。"}, "sentence_index": 6, "correct_answer": "量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "室内的量很高，大家都出汗了。", "explanation": "这里应该用〈温度〉。量指东西的多少或大小，表示冷热要用温度。"}, {"text": "这部电影的量很贵，一张票要八十块。", "explanation": "这里应该用〈票价〉。量表示多少、大小、长短、轻重，不能用来说价钱的贵贱。"}, {"text": "这朵花的量很红，特别漂亮。", "explanation": "这里应该用〈颜色〉。量表示多少、大小、长短、轻重，不能用来描述颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0489c55-8039-48f8-b79a-4bbe2c466f24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25716, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "水量的不能太少。", "corrected_sentence": "水的量不能太少。", "error_description": "错误：水量的不能太少。正确：水的量不能太少。“的”应放在修饰语“水”和中心语“量”之间，不能放在“量”后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0489c55-8039-48f8-b79a-4bbe2c466f24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25716, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种饮料的量糖很高，要少喝。", "corrected_sentence": "这种饮料的糖量很高，要少喝。", "error_description": "错误：量糖。正确：糖量。“糖量”指糖的含量，词序应为“糖量”，不能说“量糖”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0489c55-8039-48f8-b79a-4bbe2c466f24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
