INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25722, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '663775be-f27c-44e2-a340-d8c04f699ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25722, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "让空气可以流动。", "primary_collocate": null, "pronunciation": "tōng qì", "ipa": "tʰʊŋ˥ tɕʰi˥˩", "syllable_count": 2, "sentences": [{"text": "山上的房子窗户大，很通气。", "target_word": "通气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把窗户打开，让教室通气。", "target_word": "通气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这间办公室窗户小，平时不太通气，大家都觉得闷。", "target_word": "通气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地下室没有窗，一点儿也不通气。", "target_word": "通气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡觉时开一点儿窗，房间才通气。", "target_word": "通气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "土要经常翻一翻，让它通气，植物才长得好。", "target_word": "通气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间很久没开窗了，一直不通气，空气很闷。", "target_word": "通气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花盆下面要有小洞，土里才能通气。", "target_word": "通气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房要通气，不然油烟出不去。", "target_word": "通气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条街的楼太近了，风进不来，不通气。", "target_word": "通气", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "通通气", "label": "重叠"}, {"form": "通气性", "label": "复合"}, {"form": "通氣", "label": "繁体"}], "register": "中性", "sense_fingerprint": "空气能够流动、进出", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec18da45-1d04-4db4-bc9e-52cf006b7b9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25722, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "通气", "is_correct": true, "explanation": "正确：通气，让空气可以流动。"}, {"text": "空气", "is_correct": false, "explanation": "kōng 与 tōng 声母不同（k 与 t），意思是空气。"}, {"text": "同期", "is_correct": false, "explanation": "tóng（第二声）与 tōng（第一声）声调不同，qī（第一声）与 qì（第四声）声调也不同，意思是同一时期。"}, {"text": "铜器", "is_correct": false, "explanation": "tóng（第二声）与 tōng（第一声）声调不同，意思是铜制的器具。"}], "explanations": {"通气": "正确：通气，让空气可以流动。", "空气": "kōng 与 tōng 声母不同（k 与 t），意思是空气。", "同期": "tóng（第二声）与 tōng（第一声）声调不同，qī（第一声）与 qì（第四声）声调也不同，意思是同一时期。", "铜器": "tóng（第二声）与 tōng（第一声）声调不同，意思是铜制的器具。"}, "sentence_index": null, "correct_answer": "通气"}, "level_3": {"options": [{"text": "通气", "is_correct": true, "explanation": "正确：“很通气”说房子窗户大、空气流动好，符合句意。"}, {"text": "阴暗", "is_correct": false, "explanation": "语义：窗户大的房子通常明亮，“阴暗”与窗户大的描述矛盾。"}, {"text": "陡峭", "is_correct": false, "explanation": "搭配：“陡峭”形容地势，不用来形容房子。"}, {"text": "憋闷", "is_correct": false, "explanation": "语义：“憋闷”说的是空气不流通，与窗户大、空气流动好的描述相反。"}], "explanations": {"通气": "正确：“很通气”说房子窗户大、空气流动好，符合句意。", "阴暗": "语义：窗户大的房子通常明亮，“阴暗”与窗户大的描述矛盾。", "陡峭": "搭配：“陡峭”形容地势，不用来形容房子。", "憋闷": "语义：“憋闷”说的是空气不流通，与窗户大、空气流动好的描述相反。"}, "sentence_index": 0, "correct_answer": "通气"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块玻璃很通气，擦干净后看着很清楚。", "explanation": "这里应该用〈透明〉。通气说的是空气能流动，玻璃能透光要说透明。"}, {"text": "这条河的水一直在通气。", "explanation": "这里应该用〈流动〉。通气只指空气能流动，水的流动要说流动。"}, {"text": "这段文字读起来很通气。", "explanation": "这里应该用〈流畅〉。通气只说空气能流动，文字读起来顺畅要说流畅。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '663775be-f27c-44e2-a340-d8c04f699ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25722, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "通气", "is_correct": true, "explanation": "正确：“一直不通气，空气很闷”说的是房间缺少空气流动，符合句意。"}, {"text": "光滑", "is_correct": false, "explanation": "搭配：“光滑”多形容表面，不用来形容空气的流动情况。"}, {"text": "响亮", "is_correct": false, "explanation": "语义：“响亮”形容声音，与“空气很闷”的描述不合。"}, {"text": "尖锐", "is_correct": false, "explanation": "语义：“尖锐”形容锋利或刺耳的声音，与房间里空气的状况不合。"}], "explanations": {"通气": "正确：“一直不通气，空气很闷”说的是房间缺少空气流动，符合句意。", "光滑": "搭配：“光滑”多形容表面，不用来形容空气的流动情况。", "响亮": "语义：“响亮”形容声音，与“空气很闷”的描述不合。", "尖锐": "语义：“尖锐”形容锋利或刺耳的声音，与房间里空气的状况不合。"}, "sentence_index": 6, "correct_answer": "通气"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的血液循环很通气。", "explanation": "这里应该用〈通畅〉。通气只说空气能流动，血液、交通这类流动顺畅要说通畅。"}, {"text": "这座大桥明年就能通气了。", "explanation": "这里应该用〈通车〉。通气说空气能流动，桥梁开放交通要说通车。"}, {"text": "谈判进行得很通气。", "explanation": "这里应该用〈顺利〉。通气不用于事情的进展，谈判进行顺利要说顺利。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '663775be-f27c-44e2-a340-d8c04f699ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25722, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这间屋子窗户很大，一点儿也通气。", "corrected_sentence": "这间屋子窗户很大，很通气。", "error_description": "错误：“一点儿也”只能用在否定句中，不能直接接“通气”。窗户大说明空气流动好，应说“很通气”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '663775be-f27c-44e2-a340-d8c04f699ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25722, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这间屋子一点儿也很通气。", "corrected_sentence": "这间屋子一点儿也不通气。", "error_description": "错误：“一点儿也”后应接否定词“不”，不能用“很”。“很”表示程度，与“一点儿也”的否定语义矛盾，正确说法是“一点儿也不通气”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '663775be-f27c-44e2-a340-d8c04f699ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
