INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25726, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "做东西时用的材料。", "primary_collocate": null, "pronunciation": "wù liào", "ipa": "u˥˩ ljɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "做手工要先准备好物料。", "target_word": "物料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店卖做蛋糕用的物料。", "target_word": "物料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们带着物料来上手工课。", "target_word": "物料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我买的物料不够，还要再去一次。", "target_word": "物料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给每个学生发了一包物料。", "target_word": "物料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做灯笼的物料很便宜，一家店就能买到。", "target_word": "物料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把物料放在桌子上，我们马上开始做。", "target_word": "物料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些物料都是纸和布做成的。", "target_word": "物料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做模型要用的物料，网上也能买到。", "target_word": "物料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为做小船准备了很多物料。", "target_word": "物料", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "包", "label": "量词"}], "register": "中性", "sense_fingerprint": "做手工、做东西时用的材料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec18da45-1d04-4db4-bc9e-52cf006b7b9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25726, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "物料", "is_correct": true, "explanation": "正确：物料，做东西时用的材料。"}, {"text": "预料", "is_correct": false, "explanation": "yù 与 wù 韵母不同（ü 与 u），意思是事先估计。"}, {"text": "木料", "is_correct": false, "explanation": "mù 与 wù 声母不同（m 与 w），意思是木材。"}, {"text": "无聊", "is_correct": false, "explanation": "wú 与 wù 声调不同，liáo 与 liào 声调也不同，意思是没意思。"}], "explanations": {"物料": "正确：物料，做东西时用的材料。", "预料": "yù 与 wù 韵母不同（ü 与 u），意思是事先估计。", "木料": "mù 与 wù 声母不同（m 与 w），意思是木材。", "无聊": "wú 与 wù 声调不同，liáo 与 liào 声调也不同，意思是没意思。"}, "sentence_index": null, "correct_answer": "物料"}, "level_3": {"options": [{"text": "物料", "is_correct": true, "explanation": "正确：做手工前要准备好“物料”，即做东西用的材料，符合句意。"}, {"text": "食物", "is_correct": false, "explanation": "语义：食物不是做手工用的材料，与“做手工”的语境不合。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“准备”做手工时要准备的是材料，不说“准备好房子”。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲不是做手工用的材料，与句意不合。"}], "explanations": {"物料": "正确：做手工前要准备好“物料”，即做东西用的材料，符合句意。", "食物": "语义：食物不是做手工用的材料，与“做手工”的语境不合。", "房子": "搭配：“准备”做手工时要准备的是材料，不说“准备好房子”。", "歌曲": "语义：歌曲不是做手工用的材料，与句意不合。"}, "sentence_index": 0, "correct_answer": "物料"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天早上跑步，锻炼时要喝很多物料。", "explanation": "这里应该用〈水〉。锻炼时要补充的是水，物料指做东西用的材料，不能喝。"}, {"text": "这幅画是她的得意物料。", "explanation": "这里应该用〈作品〉。物料指做东西时用的材料，做成的成品要说作品。"}, {"text": "他读完这本书，学会了不少物料。", "explanation": "这里应该用〈知识〉。物料指做东西用的材料，学到的内容要说知识。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '663775be-f27c-44e2-a340-d8c04f699ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25726, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "物料", "is_correct": true, "explanation": "正确：物料，做东西时用的材料。"}, {"text": "塑料", "is_correct": false, "explanation": "sù 与 wù 声母不同（s 与 w），意思是塑胶材料。"}, {"text": "辅料", "is_correct": false, "explanation": "fǔ 与 wù 声母不同（f 与 w），意思是辅助用的材料。"}, {"text": "物流", "is_correct": false, "explanation": "liú 与 liào 韵母、声调不同，意思是货物运送。"}], "explanations": {"物料": "正确：物料，做东西时用的材料。", "塑料": "sù 与 wù 声母不同（s 与 w），意思是塑胶材料。", "辅料": "fǔ 与 wù 声母不同（f 与 w），意思是辅助用的材料。", "物流": "liú 与 liào 韵母、声调不同，意思是货物运送。"}, "sentence_index": null, "correct_answer": "物料"}, "level_3": {"options": [{"text": "物料", "is_correct": true, "explanation": "正确：“请把物料放在桌子上”，物料是可以放在桌上的材料，符合句意。"}, {"text": "大象", "is_correct": false, "explanation": "语义：大象体积太大，不能放在桌子上，与句中的语境不合。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳无法被放在桌子上，与句中的语境不合。"}, {"text": "名字", "is_correct": false, "explanation": "配价：“放”要求有形的具体物体作宾语，“名字”不能被放在桌上。"}], "explanations": {"物料": "正确：“请把物料放在桌子上”，物料是可以放在桌上的材料，符合句意。", "大象": "语义：大象体积太大，不能放在桌子上，与句中的语境不合。", "太阳": "语义：太阳无法被放在桌子上，与句中的语境不合。", "名字": "配价：“放”要求有形的具体物体作宾语，“名字”不能被放在桌上。"}, "sentence_index": 6, "correct_answer": "物料"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "睡觉前，妈妈给孩子讲了一个物料。", "explanation": "这里应该用〈故事〉。物料指做东西时用的材料，讲给人听的要说故事。"}, {"text": "孩子们在房间里吃物料，很开心。", "explanation": "这里应该用〈食物〉。物料指做东西时用的材料，吃的东西要说食物。"}, {"text": "他穿着新物料去上学。", "explanation": "这里应该用〈衣服〉。物料指做东西时用的材料，穿在身上的衣物要说衣服。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '663775be-f27c-44e2-a340-d8c04f699ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25726, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子们每人领了一本物料，开始做手工。", "corrected_sentence": "孩子们每人领了一包物料，开始做手工。", "error_description": "错误：量词用错。“本”用于书册，手工物料应按“包”计，正确说法是“一包物料”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '663775be-f27c-44e2-a340-d8c04f699ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25726, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些新地物料都很适合做灯笼。", "corrected_sentence": "这些新的物料都很适合做灯笼。", "error_description": "错误：修饰名词“物料”的“新”后应用“的”，不能用“地”。“地”用于修饰动词，正确说法是“这些新的物料”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '663775be-f27c-44e2-a340-d8c04f699ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
