INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25728, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "动来动去还能保持平稳。", "primary_collocate": null, "pronunciation": "dòng tài píng héng", "ipa": "tʊŋ˥˩ tʰaɪ˥˩ pʰiŋ˧˥ xɤŋ˧˥", "syllable_count": 4, "sentences": [{"text": "身体需要动态平衡。", "target_word": "动态平衡", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "湖里的鱼和水草保持着动态平衡。", "target_word": "动态平衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动态平衡不是不动，而是一直在变。", "target_word": "动态平衡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "骑自行车时，人要找到动态平衡。", "target_word": "动态平衡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "森林里的动物数量保持着动态平衡。", "target_word": "动态平衡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师给我们讲了什么是动态平衡。", "target_word": "动态平衡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "人口增加得太快，会破坏自然的动态平衡。", "target_word": "动态平衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人体里的水分也要保持动态平衡。", "target_word": "动态平衡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "池塘里有水进来也有水出去，这就是动态平衡。", "target_word": "动态平衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "走钢丝的人靠动态平衡才不会掉下来。", "target_word": "动态平衡", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "動態平衡", "label": "繁体"}], "register": "书面", "sense_fingerprint": "名词，指事物一直在变化，但整体保持稳定的状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e424837-2e8c-4c86-b782-2097d65b46d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25728, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "动态平衡", "is_correct": true, "explanation": "正确：“身体需要动态平衡”指身体在变化中保持稳定，符合句意。"}, {"text": "汽油", "is_correct": false, "explanation": "语义：身体不需要汽油，“身体需要汽油”句意不通。"}, {"text": "图书", "is_correct": false, "explanation": "语义：身体不需要图书，“身体需要图书”句意不通。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“需要”后接“手机”与身体的需要不搭，这里不合理。"}], "explanations": {"动态平衡": "正确：“身体需要动态平衡”指身体在变化中保持稳定，符合句意。", "汽油": "语义：身体不需要汽油，“身体需要汽油”句意不通。", "图书": "语义：身体不需要图书，“身体需要图书”句意不通。", "手机": "搭配：“需要”后接“手机”与身体的需要不搭，这里不合理。"}, "sentence_index": 0, "correct_answer": "动态平衡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道难题的动态平衡很难解决。", "explanation": "这里应该用〈问题〉。“动态平衡”指事物运动中保持稳定的状态，不是待解决的难题，应说“这个问题很难解决”。"}, {"text": "这个系统有一把动态平衡。", "explanation": "这里应该用〈种〉。“动态平衡”是抽象概念，量词要用“种”，不能用“把”。"}, {"text": "他把动态平衡送给了朋友。", "explanation": "这里应该用〈礼物〉。“动态平衡”是事物的状态，不能送人，应说“他把礼物送给了朋友”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b82f074-9073-48a1-a25a-cbb1a7b7ac41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25728, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "动态平衡", "is_correct": true, "explanation": "正确：“破坏自然的动态平衡”指破坏自然界中的稳定状态，符合句意。"}, {"text": "步伐", "is_correct": false, "explanation": "搭配：“破坏”后接的多是秩序、规律一类的对象，“自然的步伐”不搭。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格不能用“自然的”来修饰，“自然的价格”句意不通。"}, {"text": "账单", "is_correct": false, "explanation": "语义：账单与“自然”没有关系，“破坏自然的账单”句意不通。"}], "explanations": {"动态平衡": "正确：“破坏自然的动态平衡”指破坏自然界中的稳定状态，符合句意。", "步伐": "搭配：“破坏”后接的多是秩序、规律一类的对象，“自然的步伐”不搭。", "价格": "语义：价格不能用“自然的”来修饰，“自然的价格”句意不通。", "账单": "语义：账单与“自然”没有关系，“破坏自然的账单”句意不通。"}, "sentence_index": 6, "correct_answer": "动态平衡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他坐在动态平衡上看书。", "explanation": "这里应该用〈椅子〉。“动态平衡”是抽象概念，不能用“在……上”表示地点，应说“他坐在椅子上看书”。"}, {"text": "他把动态平衡装进了箱子里。", "explanation": "这里应该用〈书〉。“动态平衡”是抽象的状态，不能装进箱子，应说“他把书装进了箱子里”。"}, {"text": "他把动态平衡拿起来了。", "explanation": "这里应该用〈杯子〉。“动态平衡”是抽象状态，不能被“拿起来”，应说“他把杯子拿起来了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b82f074-9073-48a1-a25a-cbb1a7b7ac41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25728, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个生态系统里有一件动态平衡。", "corrected_sentence": "这个生态系统里有一种动态平衡。", "error_description": "量词错误：“动态平衡”是抽象概念，量词应该用“种”，写成“件”不对，应改为“一种动态平衡”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b82f074-9073-48a1-a25a-cbb1a7b7ac41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25728, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个池塘的水量正在保持动态平衡过。", "corrected_sentence": "这个池塘的水量正在保持动态平衡。", "error_description": "体标错误：“过”表示已经有过的经历，不能与表示进行中的“正在”同用；应去掉“过”，写作“这个池塘的水量正在保持动态平衡”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b82f074-9073-48a1-a25a-cbb1a7b7ac41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
