INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25745, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "指后面提到的人或事物。", "primary_collocate": null, "pronunciation": "hòu zhě", "ipa": "xoʊ˥˩ ʈʂɤ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他有一本书和一支笔，后者是新的。", "target_word": "后者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢猫和狗，但后者太吵了。", "target_word": "后者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北京和上海我都去过，后者更热。", "target_word": "后者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王和小李是同学，后者住在北京。", "target_word": "后者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐火车和坐飞机，后者更快。", "target_word": "后者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "茶和咖啡，我更喜欢后者。", "target_word": "后者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想学画画或者唱歌，后者更难。", "target_word": "后者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥和弟弟都爱运动，后者踢得更好。", "target_word": "后者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天和夏天相比，后者更适合去海边。", "target_word": "后者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个办法，我们选后者吧。", "target_word": "后者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "前者", "label": "反义词"}], "register": "书面语", "sense_fingerprint": "指两者中后提到的那一个，与前者相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76649259-ba21-4681-8829-56e282963d15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25745, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "后者", "is_correct": true, "explanation": "后者：指两者中后提到的那一个，这里指笔。"}, {"text": "彼此", "is_correct": false, "explanation": "语义：“彼此”指双方互相，与“是新的”无关，这里不指笔。"}, {"text": "大家", "is_correct": false, "explanation": "搭配：“大家”指人，不能作为物品“是新的”的主语。"}, {"text": "对方", "is_correct": false, "explanation": "语义：“对方”指与自己对立的一方，句中没有对立的人，不指笔。"}], "explanations": {"后者": "后者：指两者中后提到的那一个，这里指笔。", "彼此": "语义：“彼此”指双方互相，与“是新的”无关，这里不指笔。", "大家": "搭配：“大家”指人，不能作为物品“是新的”的主语。", "对方": "语义：“对方”指与自己对立的一方，句中没有对立的人，不指笔。"}, "sentence_index": 0, "correct_answer": "后者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们看了三部电影，后者最精彩。", "explanation": "这里应该用〈最后一个〉。后者只指两者中后提到的一个，三者以上不能用后者。"}, {"text": "我昨天在车站遇到了王老师，后者很热情。", "explanation": "这里应该用〈他〉。后者只指前文两者中后提到的一个，这里前文只有王老师一人，应用代词“他”指他。"}, {"text": "两个同学都来了，后者很高兴。", "explanation": "这里应该用〈他们〉。后者只指两者中的后一个，前文说两人都来了，应用〈他们〉指整体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0489c55-8039-48f8-b79a-4bbe2c466f24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25745, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "后者", "is_correct": true, "explanation": "后者：指两者中后提到的那一个，这里指唱歌。"}, {"text": "自己", "is_correct": false, "explanation": "语义：“自己”指说话人或主语本人，不指画画与唱歌这两件事。"}, {"text": "他人", "is_correct": false, "explanation": "语义：“他人”指别人，不指画画或唱歌。"}, {"text": "本人", "is_correct": false, "explanation": "搭配：“本人”指某人自身，不能说活动“更难”。"}], "explanations": {"后者": "后者：指两者中后提到的那一个，这里指唱歌。", "自己": "语义：“自己”指说话人或主语本人，不指画画与唱歌这两件事。", "他人": "语义：“他人”指别人，不指画画或唱歌。", "本人": "搭配：“本人”指某人自身，不能说活动“更难”。"}, "sentence_index": 6, "correct_answer": "后者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这两个办法，我们选后者，就是第一个办法。", "explanation": "这里应该用〈前者〉。后者指两者中后提到的那一个，这里说的是第一个，应该用“前者”。"}, {"text": "我们这些后者要向前辈学习。", "explanation": "这里应该用〈后来者〉。后者只表示两者中后提到的那一个，不指后来的人。"}, {"text": "车的后者坏了。", "explanation": "这里应该用〈后面〉。后者只指两者中后提到的一个，不能表示车的位置。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0489c55-8039-48f8-b79a-4bbe2c466f24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25745, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我有两个朋友，后者的住在上海。", "corrected_sentence": "我有两个朋友，后者住在上海。", "error_description": "错误：后者的住在上海。正确：后者住在上海。“后者”是代词，后面直接接动词，不能加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0489c55-8039-48f8-b79a-4bbe2c466f24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25745, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们有两份方案，后者们更便宜。", "corrected_sentence": "我们有两份方案，后者更便宜。", "error_description": "错误：后者们更便宜。正确：后者更便宜。“后者”指两者中后提到的那一个，是单数，不能加复数词尾“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0489c55-8039-48f8-b79a-4bbe2c466f24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
