INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25750, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '663775be-f27c-44e2-a340-d8c04f699ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25750, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "水果里面硬硬的小东西。", "primary_collocate": null, "pronunciation": "guǒ hé", "ipa": "kuɔ˨˩ xɤ˧˥", "syllable_count": 2, "sentences": [{"text": "橄榄的果核两头尖，里面很硬。", "target_word": "果核", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不小心咬到了果核，牙很疼。", "target_word": "果核", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "荔枝的果核是黑色的，又圆又亮。", "target_word": "果核", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟把枣的果核吐在小盘子里。", "target_word": "果核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃李子时，他把果核放在了盘子里。", "target_word": "果核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个果核太硬了，小鸟也啄不开。", "target_word": "果核", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "把果核洗干净晒干，可以做小玩具。", "target_word": "果核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做山楂果酱前，要先把果核去掉。", "target_word": "果核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在院子里种下了一个桃子的果核。", "target_word": "果核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "龙眼的果核像黑色的小球，很光滑。", "target_word": "果核", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "颗", "label": "量词"}], "register": "中性", "sense_fingerprint": "水果里面又小又硬的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec18da45-1d04-4db4-bc9e-52cf006b7b9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25750, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "果核", "is_correct": true, "explanation": "果核是橄榄里面的硬核，两头尖、里面很硬，与语境一致。"}, {"text": "果肉", "is_correct": false, "explanation": "语义：果肉柔软多汁，与“里面很硬”相反，不能说“两头尖、里面很硬”。"}, {"text": "叶子", "is_correct": false, "explanation": "体貌：叶子是薄片，没有“里面”可言，不能用“两头尖、里面很硬”来描述。"}, {"text": "果汁", "is_correct": false, "explanation": "体貌：果汁是液体，没有固定的形状，不能说“两头尖”。"}], "explanations": {"果核": "果核是橄榄里面的硬核，两头尖、里面很硬，与语境一致。", "果肉": "语义：果肉柔软多汁，与“里面很硬”相反，不能说“两头尖、里面很硬”。", "叶子": "体貌：叶子是薄片，没有“里面”可言，不能用“两头尖、里面很硬”来描述。", "果汁": "体貌：果汁是液体，没有固定的形状，不能说“两头尖”。"}, "sentence_index": 0, "correct_answer": "果核"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个桃子的果核红红的，又甜又多汁。", "explanation": "这里应该用〈果肉〉。果核是坚硬、不能吃的部分，不能说又甜又多汁；甜美多汁的部分要说果肉。"}, {"text": "我喝了一杯橙子果核。", "explanation": "这里应该用〈果汁〉。果核是坚硬的固体，不能喝；橙子榨出的饮料要说果汁。"}, {"text": "橘子的果核很薄，很容易剥下来。", "explanation": "这里应该用〈果皮〉。果核是包在果肉中间的硬核，不会很薄、很容易剥下来；能剥下来的薄皮要说果皮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '663775be-f27c-44e2-a340-d8c04f699ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25750, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "果核", "is_correct": true, "explanation": "果核是硬的，洗干净晒干后可以做小玩具，符合语境。"}, {"text": "糖", "is_correct": false, "explanation": "语义：糖遇水会溶化，不能洗干净后再晒干做玩具。"}, {"text": "冰块", "is_correct": false, "explanation": "语义：冰块遇热会融化，不能晒干，也不能做成小玩具。"}, {"text": "洗衣粉", "is_correct": false, "explanation": "配价：“洗”的对象要能被洗涤，洗衣粉是洗涤用品，不能被“洗干净”。"}], "explanations": {"果核": "果核是硬的，洗干净晒干后可以做小玩具，符合语境。", "糖": "语义：糖遇水会溶化，不能洗干净后再晒干做玩具。", "冰块": "语义：冰块遇热会融化，不能晒干，也不能做成小玩具。", "洗衣粉": "配价：“洗”的对象要能被洗涤，洗衣粉是洗涤用品，不能被“洗干净”。"}, "sentence_index": 6, "correct_answer": "果核"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把篮子里的果核洗干净，一口一口全吃光了，甜甜的。", "explanation": "这里应该用〈果实〉。果核坚硬，不能一口一口吃光；可以吃的甜美果实要说果实。"}, {"text": "这把葵花籽炒得香脆，每一颗都是咸香的果核。", "explanation": "这里应该用〈瓜子〉。果核坚硬不能当零食；炒熟的葵花籽香脆可口，要说瓜子。"}, {"text": "这颗栗子的果核又香又软，剥开就能吃。", "explanation": "这里应该用〈果仁〉。果核是坚硬的外壳，剥开就能吃的是包在里面的果仁，要说果仁。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '663775be-f27c-44e2-a340-d8c04f699ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25750, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在草丛里发现一根果核。", "corrected_sentence": "我在草丛里发现一颗果核。", "error_description": "错误形式“一根果核”；正确形式“一颗果核”。“根”用于细长的东西，果核要用“颗”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '663775be-f27c-44e2-a340-d8c04f699ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25750, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "桌上有一只果核。", "corrected_sentence": "桌上有一颗果核。", "error_description": "错误形式“一只果核”；正确形式“一颗果核”。“只”用于动物或成对器物中的一个，果核要用“颗”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '663775be-f27c-44e2-a340-d8c04f699ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
