INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25752, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "指两个事物或两个人。", "primary_collocate": null, "pronunciation": "liǎng zhě", "ipa": "liɑŋ˨˩ ʈʂɤ˨˩", "syllable_count": 2, "sentences": [{"text": "我有一本中文书和一本英文书，两者都很新。", "target_word": "两者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王和小李是同学，两者都爱打篮球。", "target_word": "两者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁和公共汽车，两者我都常坐。", "target_word": "两者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店有蛋糕和面包，两者都不贵。", "target_word": "两者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥和弟弟长得很像，两者都有大眼睛。", "target_word": "两者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北京和上海，两者我都去过。", "target_word": "两者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机和电脑都能上网，两者各有用处。", "target_word": "两者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天和秋天很舒服，两者都不冷不热。", "target_word": "两者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要选咖啡还是茶？两者我都可以。", "target_word": "两者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汉字和拼音，两者都要学。", "target_word": "两者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "代指刚提到的两个事物或两个人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b5a3a5a-e3c1-4dad-8df2-068a10a8f807') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25752, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "两者", "is_correct": true, "explanation": "正确。两者 liǎng zhě 指两个事物或两个人。"}, {"text": "讲者", "is_correct": false, "explanation": "jiǎng（第三声）与 liǎng（第三声）声母不同，l 与 j 不同，意思是讲者（讲话的人）。"}, {"text": "两只", "is_correct": false, "explanation": "第二音节 zhī（第一声）与 zhě（第三声）声调不同，意思是“两只”，是数量词组。"}, {"text": "两折", "is_correct": false, "explanation": "第二音节 zhé（第二声）与 zhě（第三声）声调不同，“两折”指打两折（原价的20%）。"}], "explanations": {"两者": "正确。两者 liǎng zhě 指两个事物或两个人。", "讲者": "jiǎng（第三声）与 liǎng（第三声）声母不同，l 与 j 不同，意思是讲者（讲话的人）。", "两只": "第二音节 zhī（第一声）与 zhě（第三声）声调不同，意思是“两只”，是数量词组。", "两折": "第二音节 zhé（第二声）与 zhě（第三声）声调不同，“两折”指打两折（原价的20%）。"}, "sentence_index": null, "correct_answer": "两者"}, "level_3": {"options": [{"text": "两者", "is_correct": true, "explanation": "正确。「两者」回指前面的中文书和英文书，都很新。"}, {"text": "双方", "is_correct": false, "explanation": "语义：「双方」指双方人员或团体，不指书。"}, {"text": "他们", "is_correct": false, "explanation": "语义：「他们」指人，不指书。"}, {"text": "彼此", "is_correct": false, "explanation": "配价：「彼此」表示互相的关系，句中“都很新”无法构成互相关系。"}], "explanations": {"两者": "正确。「两者」回指前面的中文书和英文书，都很新。", "双方": "语义：「双方」指双方人员或团体，不指书。", "他们": "语义：「他们」指人，不指书。", "彼此": "配价：「彼此」表示互相的关系，句中“都很新”无法构成互相关系。"}, "sentence_index": 0, "correct_answer": "两者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家店有蛋糕、面包和饼干，两者都不贵。", "explanation": "这里应该用〈三者〉。两者只指两个事物或两个人，这里列出了蛋糕、面包、饼干三样东西。"}, {"text": "我们全班两者都参加了比赛。", "explanation": "这里应该用〈大家〉。两者只指两个事物或两个人，不能用来指整个班级。"}, {"text": "这次考试很难，两者都没考好。", "explanation": "这里应该用〈大家〉。两者要回指前文已提到的两个对象，这句前文没有，泛指一群人应说〈大家〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf1a3ec7-449c-48e0-8566-4389d94b2815') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25752, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "两者", "is_correct": true, "explanation": "正确。「两者」指手机和电脑，各有用处。"}, {"text": "大家", "is_correct": false, "explanation": "语义：「大家」指人，手机和电脑不是人。"}, {"text": "你们", "is_correct": false, "explanation": "语义：「你们」指听话的人，不指物品。"}, {"text": "自己", "is_correct": false, "explanation": "配价：「自己」需要有明确的施事者，句中“各有用处”并不指向某人。"}], "explanations": {"两者": "正确。「两者」指手机和电脑，各有用处。", "大家": "语义：「大家」指人，手机和电脑不是人。", "你们": "语义：「你们」指听话的人，不指物品。", "自己": "配价：「自己」需要有明确的施事者，句中“各有用处”并不指向某人。"}, "sentence_index": 6, "correct_answer": "两者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "汉字，两者都要学。", "explanation": "这里应该用〈它〉。两者指两个对象，这里只提到汉字一个。"}, {"text": "她只有一个孩子，两者都在上学。", "explanation": "这里应该用〈他〉。两者要指两个人或事物，这里只有一个孩子。"}, {"text": "我一个人去了超市，两者都买了东西。", "explanation": "这里应该用〈自己〉。两者只指两个事物或两个人，这句只有一个人去超市。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf1a3ec7-449c-48e0-8566-4389d94b2815') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25752, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "红茶和咖啡，两者能都提神。", "corrected_sentence": "红茶和咖啡，两者都能提神。", "error_description": "语序错误。“都”应紧跟“两者”，说“两者都能”；“都”放在“能”后面是错的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf1a3ec7-449c-48e0-8566-4389d94b2815') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25752, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "电视和电脑，两者们都能看视频。", "corrected_sentence": "电视和电脑，两者都能看视频。", "error_description": "错误：“两者”后不能加“们”。正确：“两者都能”，“两者”是指两个对象的代词，不接“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf1a3ec7-449c-48e0-8566-4389d94b2815') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
