INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25756, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "太多了", "primary_collocate": null, "pronunciation": "guò liàng", "ipa": "kwo˥˩ ljaŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他喝水过量，一直跑厕所。", "target_word": "过量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小孩吃糖过量，牙会坏。", "target_word": "过量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种维生素吃过量会中毒。", "target_word": "过量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你今天的咖啡已经过量了。", "target_word": "过量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "药水倒过量了，要再加点水。", "target_word": "过量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她工作过量，晚上睡不好。", "target_word": "过量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶茶喝过量对身体不好。", "target_word": "过量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "锅里的盐放得过量，菜没法吃。", "target_word": "过量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看手机过量会让眼睛很累。", "target_word": "过量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸说酒喝过量会醉。", "target_word": "过量", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "過量", "label": "繁体"}], "register": "中性", "sense_fingerprint": "做某事或摄入某物太多", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8690e496-04c6-47d2-9989-640dbeda1136') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25756, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "过量", "is_correct": true, "explanation": "正确：喝水超出需要的量，才会一直跑厕所。"}, {"text": "适量", "is_correct": false, "explanation": "语义：喝水适量不会一直跑厕所，与后半句「一直跑厕所」矛盾。"}, {"text": "不够", "is_correct": false, "explanation": "语义：喝水不够，不会频繁跑厕所，与后半句「一直跑厕所」矛盾。"}, {"text": "节制", "is_correct": false, "explanation": "搭配：「节制」多用于饮食、欲望的克制，不能直接描述喝水的量。"}], "explanations": {"过量": "正确：喝水超出需要的量，才会一直跑厕所。", "适量": "语义：喝水适量不会一直跑厕所，与后半句「一直跑厕所」矛盾。", "不够": "语义：喝水不够，不会频繁跑厕所，与后半句「一直跑厕所」矛盾。", "节制": "搭配：「节制」多用于饮食、欲望的克制，不能直接描述喝水的量。"}, "sentence_index": 0, "correct_answer": "过量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次活动参加的人过量了，会场都挤满了。", "explanation": "这里应该用〈过多〉。人数、次数等可以数的量要说过多；过量用于物质或用量。"}, {"text": "他跑步的速度过量了，很快就累了。", "explanation": "这里应该用〈过快〉。速度的快慢要说过快；过量指数量或用量超出限度，不用来形容速度。"}, {"text": "这间屋子的温度过量，人都出汗了。", "explanation": "这里应该用〈过高〉。温度要说过高，过量不用来描述温度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85f1dd45-87d6-4a03-8c0c-feb4b82a9282') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25756, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "过量", "is_correct": true, "explanation": "正确：奶茶喝得超出限度，才会对身体不好。"}, {"text": "少", "is_correct": false, "explanation": "语义：奶茶喝少通常对身体无害，与后半句「对身体不好」矛盾。"}, {"text": "适度", "is_correct": false, "explanation": "语义：「适度」表示恰当，适度喝奶茶不会伤身，与后半句矛盾。"}, {"text": "适中", "is_correct": false, "explanation": "搭配：「适中」形容程度不高不低，不能直接修饰「喝」这个动作。"}], "explanations": {"过量": "正确：奶茶喝得超出限度，才会对身体不好。", "少": "语义：奶茶喝少通常对身体无害，与后半句「对身体不好」矛盾。", "适度": "语义：「适度」表示恰当，适度喝奶茶不会伤身，与后半句矛盾。", "适中": "搭配：「适中」形容程度不高不低，不能直接修饰「喝」这个动作。"}, "sentence_index": 6, "correct_answer": "过量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "屋里的音乐声过量，我没法说话。", "explanation": "这里应该用〈过大〉。声音的强度要说过大，过量只用于超出限度的数量或用量。"}, {"text": "他的动作过量，差点把杯子打翻了。", "explanation": "这里应该用〈过猛〉。动作的力度、幅度要说过猛；过量不用来描述动作的力度。"}, {"text": "这份报告的页数过量，没人愿意看。", "explanation": "这里应该用〈过多〉。页数是可以数的数目，要说过多；过量用于物质或用量，不用于数目。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85f1dd45-87d6-4a03-8c0c-feb4b82a9282') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25756, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他吃药吃地过量，心跳明显变快了。", "corrected_sentence": "他吃药吃得过量，心跳明显变快了。", "error_description": "补语标记错误：引出补语应用「得」，「地」是状语标记，不能用于动词后的补语，「吃地过量」不通，应说「吃得过量」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85f1dd45-87d6-4a03-8c0c-feb4b82a9282') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25756, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一下子吃了很过量的零食，结果吃坏了肚子。", "corrected_sentence": "他一下子吃了过量的零食，结果吃坏了肚子。", "error_description": "“过量”表示已超出限度，属非等级形容词，不能受“很”修饰，应说“过量的零食”，不说“很过量的零食”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85f1dd45-87d6-4a03-8c0c-feb4b82a9282') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
